INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96561, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时常", "is_correct": true, "explanation": "正确答案。时常 shí cháng，意思是常常发生、多次反复。"}, {"text": "时尚", "is_correct": false, "explanation": "第二个音节声母由 ch 变为 sh，声调也变了：shàng（第四声），意思是流行的潮流。"}, {"text": "试场", "is_correct": false, "explanation": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是考试的场地。"}, {"text": "日常", "is_correct": false, "explanation": "第一个音节声母由 sh 变为 r，声调也变了：rì（第四声），意思是平常、每天的。"}], "explanations": {"时常": "正确答案。时常 shí cháng，意思是常常发生、多次反复。", "时尚": "第二个音节声母由 ch 变为 sh，声调也变了：shàng（第四声），意思是流行的潮流。", "试场": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是考试的场地。", "日常": "第一个音节声母由 sh 变为 r，声调也变了：rì（第四声），意思是平常、每天的。"}, "sentence_index": null, "correct_answer": "时常"}, "level_3": {"options": [{"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意去做某事，“听到火车的声音”不是人有意完成的行为。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做，与“能听到”描述的平常状况不相符。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”多与动手的动作搭配，不能修饰“能听到”。"}, {"text": "时常", "is_correct": true, "explanation": "正确答案。“时常”表示经常能听到火车声，与句意相符。"}], "explanations": {"特意": "语义：“特意”表示有意去做某事，“听到火车的声音”不是人有意完成的行为。", "赶紧": "语义：“赶紧”表示急忙去做，与“能听到”描述的平常状况不相符。", "亲手": "搭配：“亲手”多与动手的动作搭配，不能修饰“能听到”。", "时常": "正确答案。“时常”表示经常能听到火车声，与句意相符。"}, "sentence_index": 6, "correct_answer": "时常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服时常是昨天买的。", "explanation": "这里应该用〈刚〉。〈时常〉表示反复发生，“昨天买的”是一次性的事，应说“这件衣服是昨天刚买的”。"}, {"text": "这首歌时常是四分钟。", "explanation": "这里应该用〈通常〉。〈时常〉表示次数多，“是四分钟”说的是一般情况，应说“这首歌通常是四分钟”。"}, {"text": "他时常在上海工作了十年。", "explanation": "这里应该用〈长期〉。〈时常〉说明反复出现，“工作了十年”是一段持续的时间，应说“他长期在上海工作了十年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇很时常停电。", "corrected_sentence": "这个小镇时常停电。", "error_description": "错误：“时常”前多加了程度副词“很”。“时常”本身已表示“经常”，不能再受“很”修饰，应去掉“很”，说“时常停电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的时常生病，所以要多休息。", "corrected_sentence": "妈妈时常生病，所以要多休息。", "error_description": "错误：“时常”前多加了“的”。“时常”是副词，修饰动词时不带“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "经常；常常。", "primary_collocate": null, "pronunciation": "shí cháng", "ipa": "ʂʅ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他时常给远方的母亲打电话。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶时常坐在门口晒太阳。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我时常跟爸爸去河边钓鱼。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的夏天时常下雨。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很忙，时常很晚才回家。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师时常提醒我们要多读书。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她时常想起在大学的那些日子。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我时常在公园里看到那位老人。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在海边的人时常能吃到新鲜的鱼。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他时常忘记带钥匙，只好在门口等家人。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示动作或情况经常出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时常", "is_correct": true, "explanation": "正确答案。时常 shí cháng，意思是经常、常常。"}, {"text": "失常", "is_correct": false, "explanation": "第一个音节声调不同：shī（第一声）与 shí（第二声），意思是不正常、反常，与“经常”不符。"}, {"text": "市场", "is_correct": false, "explanation": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是交易的场所。"}, {"text": "时尚", "is_correct": false, "explanation": "第二个音节声母由 ch 变为 sh，声调也变了：shàng（第四声），意思是流行的潮流。"}], "explanations": {"时常": "正确答案。时常 shí cháng，意思是经常、常常。", "失常": "第一个音节声调不同：shī（第一声）与 shí（第二声），意思是不正常、反常，与“经常”不符。", "市场": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是交易的场所。", "时尚": "第二个音节声母由 ch 变为 sh，声调也变了：shàng（第四声），意思是流行的潮流。"}, "sentence_index": null, "correct_answer": "时常"}, "level_3": {"options": [{"text": "互相", "is_correct": false, "explanation": "配价：“互相”要求动作在双方之间彼此进行，句中只有“他”一人，不能说“互相给母亲打电话”。"}, {"text": "时常", "is_correct": true, "explanation": "正确答案。“时常”表示动作经常发生，与句意相符。"}, {"text": "逐渐", "is_correct": false, "explanation": "语义：“逐渐”表示变化慢慢发生，而“打电话”是一次完成的动作，句子说不通。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求多人或多件事同时进行，句中只有“他”一人，不能说“一起给母亲打电话”。"}], "explanations": {"互相": "配价：“互相”要求动作在双方之间彼此进行，句中只有“他”一人，不能说“互相给母亲打电话”。", "时常": "正确答案。“时常”表示动作经常发生，与句意相符。", "逐渐": "语义：“逐渐”表示变化慢慢发生，而“打电话”是一次完成的动作，句子说不通。", "一起": "搭配：“一起”要求多人或多件事同时进行，句中只有“他”一人，不能说“一起给母亲打电话”。"}, "sentence_index": 0, "correct_answer": "时常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我时常去过北京一次。", "explanation": "这里应该用〈曾经〉。〈时常〉表示反复发生，与“一次”的经历相矛盾；只去过一次应说“曾经去过北京一次”。"}, {"text": "明天下午我时常去银行办事。", "explanation": "这里应该用〈要〉。〈时常〉说明反复发生，“明天下午”指一次具体安排，应说“明天下午我要去银行办事”。"}, {"text": "这次考试我时常拿到了第一名。", "explanation": "这里应该用〈终于〉。〈时常〉表示反复发生，“这次考试”只发生一次，应说“这次考试我终于拿到了第一名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时常", "is_correct": true, "explanation": "正确答案。时常 shí cháng，意思是经常、常常。"}, {"text": "试场", "is_correct": false, "explanation": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是考试的场地。"}, {"text": "日常", "is_correct": false, "explanation": "第一个音节声母由 sh 变为 r，声调也变了：rì（第四声），意思是平常、每天的。"}, {"text": "职场", "is_correct": false, "explanation": "第一个音节声母由 sh 变为 zh：zhí（第二声），第二个音节声调变为第三声，意思是工作的场所。"}], "explanations": {"时常": "正确答案。时常 shí cháng，意思是经常、常常。", "试场": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是考试的场地。", "日常": "第一个音节声母由 sh 变为 r，声调也变了：rì（第四声），意思是平常、每天的。", "职场": "第一个音节声母由 sh 变为 zh：zhí（第二声），第二个音节声调变为第三声，意思是工作的场所。"}, "sentence_index": null, "correct_answer": "时常"}, "level_3": {"options": [{"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”指自己动手去做，“想起”不是动手的动作，不能说“亲手想起”。"}, {"text": "狠狠", "is_correct": false, "explanation": "搭配：“狠狠”多修饰打、骂等动作，不能说“狠狠想起”。"}, {"text": "时常", "is_correct": true, "explanation": "正确答案。“时常”表示经常想起，与句意相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，而“想起”是一瞬间完成的心理活动，不能说“正在想起”。"}], "explanations": {"亲手": "语义：“亲手”指自己动手去做，“想起”不是动手的动作，不能说“亲手想起”。", "狠狠": "搭配：“狠狠”多修饰打、骂等动作，不能说“狠狠想起”。", "时常": "正确答案。“时常”表示经常想起，与句意相符。", "正在": "体貌：“正在”表示动作正在进行，而“想起”是一瞬间完成的心理活动，不能说“正在想起”。"}, "sentence_index": 6, "correct_answer": "时常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他时常从不迟到。", "explanation": "这里不能用〈时常〉。〈时常〉表示经常发生，与“从不”的否定意思相矛盾；若要说从不迟到，应去掉〈时常〉。"}, {"text": "这项任务时常完成了。", "explanation": "这里应该用〈终于〉。〈时常〉表示反复发生，“完成了”只能发生一次，应说“这项任务终于完成了”。"}, {"text": "他时常在北京住了三年。", "explanation": "这里应该用〈长期〉。〈时常〉说明反复出现，“住了三年”是一段持续的时间，应说“他长期在北京住了三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟很时常在周末打篮球。", "corrected_sentence": "我弟弟时常在周末打篮球。", "error_description": "错误：“时常”前多加了程度副词“很”。“时常”本身已表示“经常”，不能再受“很”修饰，应去掉“很”，说“时常在周末打篮球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐的时常忘记带钥匙。", "corrected_sentence": "我姐姐时常忘记带钥匙。", "error_description": "错误：“时常”前多加了“的”。“时常”是副词，修饰动词时不带“的”，应去掉“的”，说“时常忘记带钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有益", "is_correct": true, "explanation": "“有害”与“有益”相对：有害指有坏处，有益指有好处。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音，与“有害”的意思无关。"}, {"text": "顺利", "is_correct": false, "explanation": "“顺利”指进展没有障碍，与“有害”无反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白，与“有害”无反义关系。"}], "correct_answer": "有益", "explanations": {"有益": "“有害”与“有益”相对：有害指有坏处，有益指有好处。", "安静": "“安静”指没有声音，与“有害”的意思无关。", "顺利": "“顺利”指进展没有障碍，与“有害”无反义关系。", "清楚": "“清楚”指明白，与“有害”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有益", "is_correct": true, "explanation": "“有害”与“有益”相对：有害指有坏处，有益指有好处。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“有害”无反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "“辛苦”指费力或劳累，与“有害”无反义关系。"}, {"text": "新鲜", "is_correct": false, "explanation": "“新鲜”指刚出现或没有变质，与“有害”无反义关系。"}], "correct_answer": "有益", "explanations": {"有益": "“有害”与“有益”相对：有害指有坏处，有益指有好处。", "简单": "“简单”指不复杂，与“有害”无反义关系。", "辛苦": "“辛苦”指费力或劳累，与“有害”无反义关系。", "新鲜": "“新鲜”指刚出现或没有变质，与“有害”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "会让人或东西变坏、受伤。", "primary_collocate": null, "pronunciation": "yǒu hài", "ipa": "joʊ˨˩˦ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "抽烟对身体有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种药水对小鱼有害，别倒进河里。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太多糖对牙齿有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂的黑烟对空气有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种虫子对树有害，要快点处理。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有害的气体会让人头疼。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长时间玩手机对眼睛有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些有害的东西不能放在孩子身边。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳太大时，晒太久对皮肤有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料袋对海里的动物有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "对身体、动植物、空气等造成伤害，使其变坏或受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。有害指对身体造成伤害，与“抽烟”的危害相符。"}, {"text": "健康", "is_correct": false, "explanation": "语义：抽烟若对身体健康，与“有害”所表达的危害相反，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容对身体的影响。"}, {"text": "强壮", "is_correct": false, "explanation": "语义：抽烟不会让身体强壮，“强壮”与吸烟的危害方向相反。"}], "explanations": {"有害": "正确。有害指对身体造成伤害，与“抽烟”的危害相符。", "健康": "语义：抽烟若对身体健康，与“有害”所表达的危害相反，句意不通。", "甜": "搭配：“甜”形容味道，不用来形容对身体的影响。", "强壮": "语义：抽烟不会让身体强壮，“强壮”与吸烟的危害方向相反。"}, "sentence_index": 0, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种运动对身体很有害，经常做能增强体质。", "explanation": "这里应该用〈有益〉。有害指造成伤害，对身体有好处应说有益，不能说有害。"}, {"text": "这种方法对学习很有害，成绩提高得很快。", "explanation": "这里应该用〈有利〉。有害指造成伤害，能促进学习、提高成绩应说有利，不能说有害。"}, {"text": "这个方法对提高成绩很有害，老师很推荐。", "explanation": "这里应该用〈有帮助〉。有害指造成伤害，对提高成绩有帮助应说有帮助，不能说有害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。长时间玩手机会伤害眼睛，有害符合句意。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”用于形容人的态度，句意不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，“对眼睛明亮”不成立。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，不用于形容眼睛。"}], "explanations": {"有害": "正确。长时间玩手机会伤害眼睛，有害符合句意。", "凶狠": "语义：“凶狠”用于形容人的态度，句意不通。", "明亮": "搭配：“明亮”形容光线或眼神，“对眼睛明亮”不成立。", "香": "搭配：“香”形容气味，不用于形容眼睛。"}, "sentence_index": 6, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药对治疗感冒很有害，吃了两天就好了。", "explanation": "这里应该用〈有效〉。有害指造成伤害；药能治好病应说有效，与“好了”矛盾。"}, {"text": "这个工具对修理机器很有害，所以师傅们每天都用它。", "explanation": "这里应该用〈有用〉。有害指造成伤害，好用的修理工具应说有用，与“每天都用”矛盾。"}, {"text": "这笔资金对项目很有害，因为它帮助项目顺利完成。", "explanation": "这里应该用〈有帮助〉。有害指造成伤害，资金帮助项目完成应说有帮助，不能说有害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种化学品向河水有害。", "corrected_sentence": "这种化学品对河水有害。", "error_description": "“有害”引出的对象应用介词“对”，不能用“向”。应为“对河水有害”，“向河水有害”用错介词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
