INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96564, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人或事物有损害的。", "primary_collocate": null, "pronunciation": "yǒu hài", "ipa": "joʊ˨˩˦ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "说谎对朋友的关系有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总是熬夜对学习有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做对公司的名声有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有些有害的信息，孩子不应该看。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有害的习惯要早点改。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都觉得这个办法对城市有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太多的压力对工作有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，抄作业对你有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的话对我们的合作有害，大家很不高兴。", "target_word": "有害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾对环境有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "对关系、学习、名声、环境等人或事物的利益造成损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。说谎会损害朋友之间的关系，有害符合句意。"}, {"text": "友好", "is_correct": false, "explanation": "语义：说谎不会使关系友好，“友好”与句中的危害语境相反。"}, {"text": "松软", "is_correct": false, "explanation": "搭配：“松软”形容食物或土壤，不能修饰“关系”。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道或言辞，不用来说关系。"}], "explanations": {"有害": "正确。说谎会损害朋友之间的关系，有害符合句意。", "友好": "语义：说谎不会使关系友好，“友好”与句中的危害语境相反。", "松软": "搭配：“松软”形容食物或土壤，不能修饰“关系”。", "辛辣": "搭配：“辛辣”形容味道或言辞，不用来说关系。"}, "sentence_index": 0, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多读书对学习很有害，成绩提高了不少。", "explanation": "这里应该用〈有益〉。有害指造成损害，多读书对学习有好处应说有益。"}, {"text": "这次合作对公司的名声很有害，大家都夸公司做得好。", "explanation": "这里应该用〈有利〉。有害指造成损害，让公司被夸应说有利，与“夸”矛盾。"}, {"text": "互相帮助对朋友的关系很有害，所以他们越来越好。", "explanation": "这里应该用〈有帮助〉。有害指造成损害，让关系变好应说有帮助，与“越来越好”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。压力过多会损害工作，有害符合句意。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：压力过多不会让工作愉快，“愉快”与句中的危害语境相反。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”多用于思路或声音，不说对工作清晰。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能修饰“工作”。"}], "explanations": {"有害": "正确。压力过多会损害工作，有害符合句意。", "愉快": "语义：压力过多不会让工作愉快，“愉快”与句中的危害语境相反。", "清晰": "搭配：“清晰”多用于思路或声音，不说对工作清晰。", "嘹亮": "搭配：“嘹亮”形容声音，不能修饰“工作”。"}, "sentence_index": 6, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种办法对改善环境很有害，一年后环境明显变好了。", "explanation": "这里应该用〈有效〉。有害指造成损害；办法让环境变好应说有效，与“变好了”矛盾。"}, {"text": "这台机器对生产很有害，工厂每天都在用它增加产量。", "explanation": "这里应该用〈有用〉。有害指造成损害，帮助生产应说有用，与“增加产量”的句意相反。"}, {"text": "这份资料对研究很有害，研究员们都非常需要它。", "explanation": "这里应该用〈必要〉。有害指造成损害，对研究不可少的资料应说必要，不能说有害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种做法向公司的信誉有害。", "corrected_sentence": "这种做法对公司的信誉有害。", "error_description": "“有害”引出的对象应用介词“对”，不能用“向”。应为“对公司的信誉有害”，“向公司的信誉有害”用错介词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "说谎向朋友之间的友谊非常有害。", "corrected_sentence": "说谎对朋友之间的友谊非常有害。", "error_description": "“有害”引出的对象应用介词“对”，不能用“向”。应为“对朋友之间的友谊非常有害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
