INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古时候皇帝和大臣们商量国家大事的地方。", "primary_collocate": null, "pronunciation": "cháo tíng", "ipa": "ʈʂʰɑʊ˧˥ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大臣们早上都去朝廷见皇帝。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝在朝廷上问大家的意见。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷里站着很多大臣。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次走进朝廷，心里很紧张。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们在朝廷上商量打仗的事。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷的大门每天早上都会打开。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老大臣在朝廷上说了一句真话。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝坐在朝廷最前面。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷里没有人敢大声说话。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员们站在朝廷外等着皇帝。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古时皇帝与大臣聚在一起议事的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝廷", "is_correct": true, "explanation": "“朝廷”指古时皇帝与大臣议事的场所，与“去朝廷见皇帝”相符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买菜的地方，不是皇帝接见大臣的场所。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产的地方，不是议事和见皇帝的场所。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，与“见皇帝”的情景不符。"}], "explanations": {"朝廷": "“朝廷”指古时皇帝与大臣议事的场所，与“去朝廷见皇帝”相符。", "菜市场": "语义：菜市场是买菜的地方，不是皇帝接见大臣的场所。", "工厂": "语义：工厂是生产的地方，不是议事和见皇帝的场所。", "医院": "语义：医院是看病的地方，与“见皇帝”的情景不符。"}, "sentence_index": 0, "correct_answer": "朝廷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们跳进朝廷，玩得很开心。", "explanation": "“朝廷”指皇帝与大臣议事的殿堂，这里被误用成了“游泳池”的意思，不能跳进去玩，这里应该用“游泳池”。"}, {"text": "他第一次在朝廷里洗了澡，心里很紧张。", "explanation": "“朝廷”在这里被误用成了“浴室”的意思。它指皇帝与大臣议事的殿堂，不能用来洗澡，这里应该用“浴室”。"}, {"text": "妈妈走进朝廷买菜。", "explanation": "“朝廷”指皇帝与大臣议事的殿堂，这里被误用成了“超市”的意思，不能在里面买菜，这里应该用“超市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝廷", "is_correct": true, "explanation": "“朝廷”指议事的场所，老大臣在这里说真话与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是议事场所，不会在厨房上说真话。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场与议事和说真话的情景无关。"}, {"text": "菜园", "is_correct": false, "explanation": "搭配：“在……上说话”一般指在正式场所，菜园不能这样搭配。"}], "explanations": {"朝廷": "“朝廷”指议事的场所，老大臣在这里说真话与句意相符。", "厨房": "语义：厨房不是议事场所，不会在厨房上说真话。", "游乐场": "语义：游乐场与议事和说真话的情景无关。", "菜园": "搭配：“在……上说话”一般指在正式场所，菜园不能这样搭配。"}, "sentence_index": 6, "correct_answer": "朝廷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在朝廷里做饭，香味飘满了整个房子。", "explanation": "“朝廷”是议事场所，不是厨房，这里应该用“厨房”。"}, {"text": "他把朝廷放进了箱子里。", "explanation": "“朝廷”指皇帝与大臣议事的殿堂，这里被误用成了“模型”的意思。殿堂是大型建筑，不能装进箱子。"}, {"text": "朝廷是我的好朋友，每天陪我聊天。", "explanation": "“朝廷”在这里被误用成了“人、伙伴”的意思。它指议事的殿堂，是建筑，不能陪人聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大臣们早上朝廷上等待皇帝。", "corrected_sentence": "大臣们早上在朝廷上等待皇帝。", "error_description": "错误形式是“朝廷上”前缺少“在”，正确形式是“在朝廷上”。表示地点的“朝廷上”前面需要加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝廷的里坐满了官员。", "corrected_sentence": "朝廷里坐满了官员。", "error_description": "错误：“朝廷”和“里”之间多了“的”。正确是“朝廷里”，方位词“里”直接跟在名词后，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
