INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "君主时代君主及其官员处理国家政务的机构。", "primary_collocate": null, "pronunciation": "cháo tíng", "ipa": "ʈʂʰɑʊ˧˥ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "朝廷派人去南方管理税收。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的朝廷有很多官员。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷每年都要向百姓收税。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个朝廷已经没有钱了。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷下令修一条长长的河。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在朝廷当了二十年官。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷决定减少农民的税。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百姓不满朝廷的新规定。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷派兵去保护边境。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝是朝廷的最高统治者。", "target_word": "朝廷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝廷命官", "label": "复合词"}], "register": "书面", "sense_fingerprint": "君主时代由君主和官员组成、负责处理国家政务的统治机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝廷", "is_correct": true, "explanation": "“朝廷”指君主时代处理国家政务的统治机构，句中指它派人去收税。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不负责派人管理税收，句意不通。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“管理税收”不能搭配学校，学校不征税。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场不负责税收管理，句子无法成立。"}], "explanations": {"朝廷": "“朝廷”指君主时代处理国家政务的统治机构，句中指它派人去收税。", "医院": "语义：医院不负责派人管理税收，句意不通。", "学校": "搭配：“管理税收”不能搭配学校，学校不征税。", "农场": "语义：农场不负责税收管理，句子无法成立。"}, "sentence_index": 0, "correct_answer": "朝廷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下班后我们去朝廷吃火锅。", "explanation": "“朝廷”指古代的统治机构，不是可以吃饭的地方；这里应该用“饭店”。"}, {"text": "我昨天去朝廷借了一本书。", "explanation": "“朝廷”指君主时代的统治机构，不是可以借书的地方；这里应该用“图书馆”。"}, {"text": "这家公司的朝廷今年要上市。", "explanation": "“朝廷”在这里被误用成了“企业”的意思。它指君主时代的统治机构，现代企业不能称为朝廷，这里应该用“企业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝廷", "is_correct": true, "explanation": "“朝廷”指统治机构，只有它能够决定减免百姓的税，与句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不负责决定减免农民的税，这不是它的职能。"}, {"text": "花店", "is_correct": false, "explanation": "搭配：“减少农民的税”需要有征税权的主体，花店不能作这样的主语。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场与税收政策无关，句意不通。"}], "explanations": {"朝廷": "“朝廷”指统治机构，只有它能够决定减免百姓的税，与句意相符。", "银行": "语义：银行不负责决定减免农民的税，这不是它的职能。", "花店": "搭配：“减少农民的税”需要有征税权的主体，花店不能作这样的主语。", "游乐场": "语义：游乐场与税收政策无关，句意不通。"}, "sentence_index": 6, "correct_answer": "朝廷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在中国的朝廷由人民选出。", "explanation": "“朝廷”指君主时代的统治机构，不能用来指现代国家的政府；这里应该用“政府”。"}, {"text": "妈妈昨天去朝廷看病了。", "explanation": "“朝廷”指君主时代的统治机构，这里被误用成了“医院”的意思，不能去朝廷看病，这里应该用“医院”。"}, {"text": "我们球队的朝廷今晚赢了比赛。", "explanation": "“朝廷”指古代的统治机构，不能用来指运动队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他朝廷做了十年官。", "corrected_sentence": "他在朝廷做了十年官。", "error_description": "错误：漏掉了介词“在”。“朝廷”作“做官”的处所时，需要用“在朝廷”引出，不能直接放在主语之后。正确形式为“他在朝廷做了十年官”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "里朝廷有很多大臣。", "corrected_sentence": "朝廷有很多大臣。", "error_description": "错误形式是“里朝廷”，方位词“里”不能放在名词“朝廷”前面。正确形式为“朝廷有很多大臣”；若要表示“在朝廷中”，应把“里”放在“朝廷”之后，说“朝廷里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
