INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96567, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数硬币、徽章、针这种小东西时用的字。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "我口袋里有一枚硬币。", "target_word": "枚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一枚漂亮的戒指。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上放着三枚棋子。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她胸前别着一枚小徽章。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两枚一元的硬币。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信上贴着一枚新邮票。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一枚别针递给了我。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我捡到过一枚旧硬币，不知道是谁的。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明有一枚红色的校徽，每天都戴着。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚戒指是奶奶送给我的。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用来数硬币、徽章、别针等小物件的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96567, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "枚", "is_correct": true, "explanation": "枚（第二声）是量词，用于硬币、徽章等小物件，即正确答案。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méi 韵母不同（-en 与 -ei），意思是门。"}, {"text": "雷", "is_correct": false, "explanation": "léi 与 méi 声母不同（l 与 m），意思是雷。"}, {"text": "迷", "is_correct": false, "explanation": "mí 与 méi 韵母不同（少了 e），意思是迷路、迷恋。"}], "explanations": {"枚": "枚（第二声）是量词，用于硬币、徽章等小物件，即正确答案。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "门": "mén 与 méi 韵母不同（-en 与 -ei），意思是门。", "雷": "léi 与 méi 声母不同（l 与 m），意思是雷。", "迷": "mí 与 méi 韵母不同（少了 e），意思是迷路、迷恋。"}, "sentence_index": null, "correct_answer": "枚"}, "level_3": {"options": [{"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来数硬币。"}, {"text": "条", "is_correct": false, "explanation": "体貌：“条”用于细长的东西，硬币是小圆片，形状不符。"}, {"text": "枚", "is_correct": true, "explanation": "枚是量词，用于硬币、徽章等小东西，与“硬币”搭配。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物品中的一个，不能用来数硬币。"}], "explanations": {"本": "搭配：“本”用于书册，不能用来数硬币。", "条": "体貌：“条”用于细长的东西，硬币是小圆片，形状不符。", "枚": "枚是量词，用于硬币、徽章等小东西，与“硬币”搭配。", "只": "搭配：“只”多用于动物或成对物品中的一个，不能用来数硬币。"}, "sentence_index": 0, "correct_answer": "枚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一枚苹果。", "explanation": "这里应该用〈个〉。〈枚〉用于硬币、徽章等小东西，苹果要用〈个〉。"}, {"text": "院子里停着一枚汽车。", "explanation": "这里应该用〈辆〉。〈枚〉用于硬币、徽章等小东西，汽车是大件，要用〈辆〉。"}, {"text": "他买了一枚书。", "explanation": "这里应该用〈本〉。〈枚〉不能用来数书，书要用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96567, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "枚", "is_correct": true, "explanation": "枚（第二声）是量词，用于硬币、徽章等小物件，即正确答案。"}, {"text": "陪", "is_correct": false, "explanation": "péi 与 méi 声母不同（p 与 m），意思是陪伴。"}, {"text": "肥", "is_correct": false, "explanation": "féi 与 méi 声母不同（f 与 m），意思是肥胖。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, {"text": "围", "is_correct": false, "explanation": "wéi 与 méi 声母不同（w 与 m），意思是围绕。"}], "explanations": {"枚": "枚（第二声）是量词，用于硬币、徽章等小物件，即正确答案。", "陪": "péi 与 méi 声母不同（p 与 m），意思是陪伴。", "肥": "féi 与 méi 声母不同（f 与 m），意思是肥胖。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。", "围": "wéi 与 méi 声母不同（w 与 m），意思是围绕。"}, "sentence_index": null, "correct_answer": "枚"}, "level_3": {"options": [{"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来数别针。"}, {"text": "枚", "is_correct": true, "explanation": "枚用于别针、硬币等小东西，与句意相合。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”指大而固定的东西，别针太小，形状与大小不符。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能用来数别针。"}], "explanations": {"本": "搭配：“本”用于书册，不能用来数别针。", "枚": "枚用于别针、硬币等小东西，与句意相合。", "座": "体貌：“座”指大而固定的东西，别针太小，形状与大小不符。", "首": "搭配：“首”用于诗歌、歌曲，不能用来数别针。"}, "sentence_index": 6, "correct_answer": "枚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这枚照片很漂亮，是我去年拍的。", "explanation": "这里应该用〈张〉。〈枚〉用于硬币、徽章等小东西，照片要用〈张〉。"}, {"text": "地上掉了一枚米。", "explanation": "这里应该用〈粒〉。〈枚〉不能用来数米，米粒要用〈粒〉。"}, {"text": "他在城里买了一枚大楼。", "explanation": "这里应该用〈座〉。〈枚〉用于硬币、徽章等小东西，大楼要用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手里拿着一枚旧雨伞。", "corrected_sentence": "他手里拿着一把旧雨伞。", "error_description": "错误形式：“一枚旧雨伞”；正确形式：“一把旧雨伞”。“枚”用于硬币、徽章等小东西，雨伞要用量词“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的抽屉里还藏着一枚旧书。", "corrected_sentence": "她的抽屉里还藏着一本旧书。", "error_description": "错误形式：“一枚旧书”；正确形式：“一本旧书”。“枚”用于邮票、硬币等小东西，不能用来数书，书要用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
