INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96568, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于形体小的东西，如硬币、棋子、勋章。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "他胸前戴着一枚勋章。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员得到了一枚金牌。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子里有三十二枚棋子。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给每个人发了一枚小印章。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有一枚图钉，小心点儿。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷保存着一枚很旧的纪念币。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出一枚硬币。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一枚金币放进了盒子里。", "target_word": "枚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚邮票是从国外寄来的。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一共收藏了二十枚古代的铜钱。", "target_word": "枚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用于形体较小的物品（硬币、棋子、勋章等）的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96568, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "枚", "is_correct": true, "explanation": "枚（第二声）是量词，用于勋章、硬币等小东西，即正确答案。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。"}, {"text": "陪", "is_correct": false, "explanation": "péi 与 méi 声母不同（p 与 m），意思是陪伴。"}, {"text": "雷", "is_correct": false, "explanation": "léi 与 méi 声母不同（l 与 m），意思是雷。"}, {"text": "迷", "is_correct": false, "explanation": "mí 与 méi 韵母不同（少了 e），意思是迷路。"}], "explanations": {"枚": "枚（第二声）是量词，用于勋章、硬币等小东西，即正确答案。", "美": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。", "陪": "péi 与 méi 声母不同（p 与 m），意思是陪伴。", "雷": "léi 与 méi 声母不同（l 与 m），意思是雷。", "迷": "mí 与 méi 韵母不同（少了 e），意思是迷路。"}, "sentence_index": null, "correct_answer": "枚"}, "level_3": {"options": [{"text": "根", "is_correct": false, "explanation": "体貌：“根”用于细长的东西，勋章不是细长的，形状不符。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”多用于花、云等，不能用来数勋章。"}, {"text": "枚", "is_correct": true, "explanation": "枚是量词，用于勋章、硬币等小物件，与句意相合。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或能握住的东西，不能用来数勋章。"}], "explanations": {"根": "体貌：“根”用于细长的东西，勋章不是细长的，形状不符。", "朵": "搭配：“朵”多用于花、云等，不能用来数勋章。", "枚": "枚是量词，用于勋章、硬币等小物件，与句意相合。", "把": "搭配：“把”用于有柄或能握住的东西，不能用来数勋章。"}, "sentence_index": 0, "correct_answer": "枚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一枚杯子。", "explanation": "这里应该用〈个〉。〈枚〉用于硬币、勋章等小东西，杯子要用〈个〉。"}, {"text": "他家门口停着一枚汽车。", "explanation": "这里应该用〈辆〉。〈枚〉用于小件物品，汽车是大件，要用〈辆〉。"}, {"text": "他在郊区买了一枚房子。", "explanation": "这里应该用〈套〉。〈枚〉只用于小件物品，房子要用〈套〉或〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96568, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "枚", "is_correct": true, "explanation": "枚（第二声）是量词，用于硬币、勋章等小东西，即正确答案。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méi 韵母不同（-en 与 -ei），意思是门。"}, {"text": "肥", "is_correct": false, "explanation": "féi 与 méi 声母不同（f 与 m），意思是肥胖。"}, {"text": "围", "is_correct": false, "explanation": "wéi 与 méi 声母不同（w 与 m），意思是围绕。"}], "explanations": {"枚": "枚（第二声）是量词，用于硬币、勋章等小东西，即正确答案。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "门": "mén 与 méi 韵母不同（-en 与 -ei），意思是门。", "肥": "féi 与 méi 声母不同（f 与 m），意思是肥胖。", "围": "wéi 与 méi 声母不同（w 与 m），意思是围绕。"}, "sentence_index": null, "correct_answer": "枚"}, "level_3": {"options": [{"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能用来数硬币。"}, {"text": "根", "is_correct": false, "explanation": "体貌：“根”用于细长的东西，硬币是圆片，形状不符。"}, {"text": "盏", "is_correct": false, "explanation": "搭配：“盏”用于灯、茶杯等，不能用来数硬币。"}, {"text": "枚", "is_correct": true, "explanation": "枚是量词，用于硬币、勋章等小东西，与句意相合。"}], "explanations": {"首": "搭配：“首”用于诗歌、歌曲，不能用来数硬币。", "根": "体貌：“根”用于细长的东西，硬币是圆片，形状不符。", "盏": "搭配：“盏”用于灯、茶杯等，不能用来数硬币。", "枚": "枚是量词，用于硬币、勋章等小东西，与句意相合。"}, "sentence_index": 6, "correct_answer": "枚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一枚火车票，准备回家。", "explanation": "这里应该用〈张〉。〈枚〉用于硬币、勋章等小东西，车票要用〈张〉。"}, {"text": "他在雨里撑开了一枚伞。", "explanation": "这里应该用〈把〉。〈枚〉用于硬币、勋章等小东西，伞要用〈把〉。"}, {"text": "他写了一枚诗送给朋友。", "explanation": "这里应该用〈首〉。〈枚〉不用于诗，诗要用〈首〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,