INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到很好的奖，是很光荣的事。", "primary_collocate": null, "pronunciation": "róng huò", "ipa": "ɻʊŋ˧˥ xuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他在比赛中荣获第一名。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影荣获了最佳影片奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的合唱团荣获金奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为画得好，荣获全国大奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师荣获过优秀教师奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在数学比赛中荣获二等奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书荣获了今年的文学奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队荣获世界杯冠军。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生荣获过很多奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品荣获国际设计奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "荣获了", "label": "体标"}, {"form": "荣获过", "label": "体标"}], "register": "书面", "sense_fingerprint": "荣获：动词，光荣地得到名次或奖项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96569, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”是授予他人奖项的人的动作，“他”作为参赛者不能颁发第一名。"}, {"text": "荣获", "is_correct": true, "explanation": "正确。“荣获”表示光荣地得到名次或奖项，与“第一名”搭配，句意通顺。"}, {"text": "赚", "is_correct": false, "explanation": "搭配：“赚”只与钱、利润等搭配，不能与“第一名”搭配。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语是比赛、活动等事件，“第一名”不能作它的宾语。"}], "explanations": {"颁发": "语义：“颁发”是授予他人奖项的人的动作，“他”作为参赛者不能颁发第一名。", "荣获": "正确。“荣获”表示光荣地得到名次或奖项，与“第一名”搭配，句意通顺。", "赚": "搭配：“赚”只与钱、利润等搭配，不能与“第一名”搭配。", "参加": "配价：“参加”的宾语是比赛、活动等事件，“第一名”不能作它的宾语。"}, "sentence_index": 0, "correct_answer": "荣获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他荣获了一份新工作。", "explanation": "这里应该用〈获得〉。荣获只用于称号、奖项等荣誉，工作、机会等不用荣获。"}, {"text": "我昨天荣获了一个好消息。", "explanation": "这里应该用〈得到〉。荣获针对奖项或称号，好消息只能说得到。"}, {"text": "他荣获了大家的尊重。", "explanation": "这里应该用〈赢得〉。荣获的对象是具体的奖项或称号，“尊重”是态度，应说赢得尊重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举办", "is_correct": false, "explanation": "语义：“举办”的主语应是组织者，“这本书”不能举办奖项。"}, {"text": "荣获", "is_correct": true, "explanation": "正确。“荣获”的主语是获奖者，与“了今年的文学奖”搭配，句意通顺。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”只能和商品搭配，不能和“文学奖”搭配。"}, {"text": "颁布", "is_correct": false, "explanation": "语义：“颁布”用于法令、政策，不用于奖项。"}], "explanations": {"举办": "语义：“举办”的主语应是组织者，“这本书”不能举办奖项。", "荣获": "正确。“荣获”的主语是获奖者，与“了今年的文学奖”搭配，句意通顺。", "卖": "搭配：“卖”只能和商品搭配，不能和“文学奖”搭配。", "颁布": "语义：“颁布”用于法令、政策，不用于奖项。"}, "sentence_index": 6, "correct_answer": "荣获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们荣获了一封感谢信。", "explanation": "这里应该用〈收到〉。荣获针对奖项或称号，感谢信只能说收到。"}, {"text": "妈妈荣获了一张电影票。", "explanation": "这里应该用〈拿到〉。荣获针对荣誉，电影票只能说拿到。"}, {"text": "他去窗口荣获了身份证。", "explanation": "这里应该用〈领取〉。荣获针对荣誉，证件应说领取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家荣获着国际艺术奖。", "corrected_sentence": "这位画家荣获了国际艺术奖。", "error_description": "错误形式：“荣获着”；正确形式：“荣获了”。“荣获”表示一次已经完成的获奖，应用“了”，“着”表示持续状态，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的论文荣获到省级一等奖。", "corrected_sentence": "他的论文荣获了省级一等奖。", "error_description": "错误形式：“荣获到”；正确形式：“荣获了”。“荣获”后不接结果补语“到”，表示完成应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
