INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "光荣地获得（称号、奖励等）。", "primary_collocate": null, "pronunciation": "róng huò", "ipa": "ɻʊŋ˧˥ xuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "王医生荣获“优秀医生”称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她荣获了“三八红旗手”称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子荣获“文明村”称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人荣获过国家颁发的勋章。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为救人荣获英雄称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班荣获了学校的流动红旗。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院荣获“先进单位”称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明荣获“三好学生”称号，大家都为他高兴。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家荣获了国家科学奖。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他荣获市里的“劳动模范”称号。", "target_word": "荣获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "荣获了", "label": "体标"}, {"form": "荣获过", "label": "体标"}], "register": "书面", "sense_fingerprint": "荣获：动词，光荣地获得称号、勋章、荣誉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，不能用于获得称号。"}, {"text": "荣获", "is_correct": true, "explanation": "正确。“荣获”表示光荣地获得称号，与“称号”搭配，句意通顺。"}, {"text": "遇到", "is_correct": false, "explanation": "配价：“遇到”的宾语是人或事，不能直接接“称号”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”一般接衣物，不能与“称号”搭配。"}], "explanations": {"写": "语义：“写”指书写文字，不能用于获得称号。", "荣获": "正确。“荣获”表示光荣地获得称号，与“称号”搭配，句意通顺。", "遇到": "配价：“遇到”的宾语是人或事，不能直接接“称号”作宾语。", "穿": "搭配：“穿”一般接衣物，不能与“称号”搭配。"}, "sentence_index": 0, "correct_answer": "荣获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她荣获了一张毕业证书。", "explanation": "这里应该用〈获得〉。荣获只用于称号、荣誉，毕业证书是普通证件，应说获得。"}, {"text": "他荣获了一份补助。", "explanation": "这里应该用〈领取〉。荣获指光荣地得到荣誉，补助是发放的钱物，应说领取。"}, {"text": "他荣获了老师的批评。", "explanation": "这里应该用〈受到〉。荣获是光荣的事，批评不能荣获，应说受到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”的宾语应是人或具体事物的喜好对象，不能是称号。"}, {"text": "荣获", "is_correct": true, "explanation": "正确。“荣获”表示光荣地获得称号，与“先进单位”称号搭配，句意通顺。"}, {"text": "考", "is_correct": false, "explanation": "搭配：“考”的宾语是考试、科目，不能接称号。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”一般接建筑、物品，不能与“称号”搭配。"}], "explanations": {"喜欢": "语义：“喜欢”的宾语应是人或具体事物的喜好对象，不能是称号。", "荣获": "正确。“荣获”表示光荣地获得称号，与“先进单位”称号搭配，句意通顺。", "考": "搭配：“考”的宾语是考试、科目，不能接称号。", "拆": "搭配：“拆”一般接建筑、物品，不能与“称号”搭配。"}, "sentence_index": 6, "correct_answer": "荣获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我荣获了一份工资。", "explanation": "这里应该用〈拿到〉。荣获针对称号、荣誉，工资是报酬，应说拿到。"}, {"text": "同学们荣获了老师的帮助。", "explanation": "这里应该用〈得到〉。荣获针对荣誉，帮助只能说得到。"}, {"text": "她荣获了大家的信任。", "explanation": "这里应该用〈赢得〉。荣获的对象是具体的奖项或称号，“信任”是态度，应说赢得信任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校正在荣获了“绿色校园”称号。", "corrected_sentence": "这所学校荣获了“绿色校园”称号。", "error_description": "错误形式：“正在荣获了”；正确形式：“荣获了”。“正在”表示动作进行中，与表示完成的“了”矛盾，应去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没荣获了“优秀员工”称号。", "corrected_sentence": "她没荣获“优秀员工”称号。", "error_description": "错误形式：“没荣获了”；正确形式：“没荣获”。否定词“没”表示事情未发生，与表示完成的“了”矛盾，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
