INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "快乐的地方；游乐场所。", "primary_collocate": null, "pronunciation": "lè yuán", "ipa": "lɤ˥˩ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "周末我们带孩子去乐园玩。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐园有很多好玩的游戏。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园门口有很多人在买票。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乐园里坐了三次过山车。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园里的小火车很受孩子喜欢。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐园晚上七点关门。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐地铁去乐园，只要二十分钟。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园里有吃的，也有玩的。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新开的乐园离我家很近。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他第一次去乐园，高兴得不想回家。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "儿童乐园", "label": "复合"}, {"form": "樂園", "label": "繁体"}], "register": "通用", "sense_fingerprint": "本义：有游戏设施、供人游玩的场所，如游乐园", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”指供人游玩的场所，与“周末我们带孩子去……玩”的句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，不是可以带孩子去游玩的地方。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱不是供人游玩的地方，与“带孩子去玩”的句意不符。"}, {"text": "墓地", "is_correct": false, "explanation": "搭配：“玩”不能与墓地搭配，墓地不是能游玩的场所。"}], "explanations": {"乐园": "“乐园”指供人游玩的场所，与“周末我们带孩子去……玩”的句意相符。", "银行": "语义：银行是办理金融业务的地方，不是可以带孩子去游玩的地方。", "监狱": "语义：监狱不是供人游玩的地方，与“带孩子去玩”的句意不符。", "墓地": "搭配：“玩”不能与墓地搭配，墓地不是能游玩的场所。"}, "sentence_index": 0, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在乐园里看病。", "explanation": "这里应该用〈医院〉。乐园是供人游玩的场所，看病应去医院。"}, {"text": "我们每天去乐园买菜。", "explanation": "这里应该用〈超市〉。乐园是游玩的地方，买菜应去超市。"}, {"text": "工人在乐园里生产汽车。", "explanation": "这里应该用〈工厂〉。乐园不是生产场所，生产汽车应在工厂进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”是供人游玩的场所，可以作为坐地铁前往的目的地，与句意相符。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“去”后接的应是地点，“玩具”是物品，不能作为坐地铁前往的目的地。"}, {"text": "炉子", "is_correct": false, "explanation": "语义：炉子是做饭取暖的设备，不是可以乘地铁前往的地方。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿在脚上的东西，不能作为坐地铁前往的地点。"}], "explanations": {"乐园": "“乐园”是供人游玩的场所，可以作为坐地铁前往的目的地，与句意相符。", "玩具": "搭配：“去”后接的应是地点，“玩具”是物品，不能作为坐地铁前往的目的地。", "炉子": "语义：炉子是做饭取暖的设备，不是可以乘地铁前往的地方。", "鞋子": "语义：鞋子是穿在脚上的东西，不能作为坐地铁前往的地点。"}, "sentence_index": 6, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去乐园办理银行卡。", "explanation": "这里应该用〈银行〉。乐园是游玩的地方，办理银行卡要去银行。"}, {"text": "汽车在乐园里加油，然后继续上路。", "explanation": "这里应该用〈加油站〉。乐园不是加油的地方，给汽车加油要去加油站。"}, {"text": "我今天去乐园寄了一个包裹。", "explanation": "这里应该用〈邮局〉。乐园是游玩的地方，寄包裹要去邮局。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑假我和朋友一起去了一只乐园。", "corrected_sentence": "暑假我和朋友一起去了一座乐园。", "error_description": "量词错误：“乐园”的量词应用“座”，“只”不能修饰乐园。应改为“一座乐园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们乐园里玩得很开心。", "corrected_sentence": "孩子们在乐园里玩得很开心。", "error_description": "漏词错误：表示地点的“乐园里”前要加介词“在”，应说“在乐园里玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
