INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一个人或东西看起来是什么样子。", "primary_collocate": null, "pronunciation": "mú yàng", "ipa": "mu˧˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "看他那副着急的模样，我也紧张了。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生气的模样很好笑。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着的模样真安静。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的小山村是什么模样？", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上新衣服，换了一个模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了一个小时，他还是一副没睡醒的模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小孩学大人说话的模样，让大家都笑了。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看你小时候的模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间整理好以后，完全变了模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒后爬起来，一脸不好意思的模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "模样：名词，人或物看起来的样子、神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是戴在脸上的物品，不能用来形容着急的神情。"}, {"text": "模样", "is_correct": true, "explanation": "正确。“模样”指神态、样子，与“那副着急的”搭配，句意通顺。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“着急的”形容神态，不能修饰“手套”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的形态，不表示着急的神情。"}], "explanations": {"眼镜": "语义：“眼镜”是戴在脸上的物品，不能用来形容着急的神情。", "模样": "正确。“模样”指神态、样子，与“那副着急的”搭配，句意通顺。", "手套": "搭配：“着急的”形容神态，不能修饰“手套”。", "身材": "体貌：“身材”指身体的形态，不表示着急的神情。"}, "sentence_index": 0, "correct_answer": "模样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果的模样很甜。", "explanation": "这里应该用〈味道〉。“甜”形容味道，“模样”指外形、神态，不能用来形容味觉。"}, {"text": "这双鞋的模样很贵。", "explanation": "这里应该用〈价格〉。“贵”形容价钱，“模样”指外形、神态，不能说很贵。"}, {"text": "这条路的模样很远。", "explanation": "这里应该用〈距离〉。“远”形容距离，“模样”不能用来形容距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的重量，不能表示说话时的样子。"}, {"text": "模样", "is_correct": true, "explanation": "正确。“模样”指神态、样子，与“学大人说话的”搭配，句意通顺。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿在脚上的东西，不能表示学话的样子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能与“学大人说话的”搭配。"}], "explanations": {"体重": "体貌：“体重”指身体的重量，不能表示说话时的样子。", "模样": "正确。“模样”指神态、样子，与“学大人说话的”搭配，句意通顺。", "鞋子": "语义：“鞋子”是穿在脚上的东西，不能表示学话的样子。", "颜色": "语义：“颜色”指色彩，不能与“学大人说话的”搭配。"}, "sentence_index": 6, "correct_answer": "模样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的模样很大声。", "explanation": "这里应该用〈音量〉。“大声”形容声音的大小，“模样”指外形、神态，不能用来形容声音。"}, {"text": "这朵花的模样很香。", "explanation": "这里应该用〈气味〉。“香”形容气味，“模样”指外形、神态，不能用来形容气味。"}, {"text": "这杯水的模样很烫。", "explanation": "这里应该用〈温度〉。“烫”形容温度，“模样”不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被老师批评后，露出一块委屈的模样。", "corrected_sentence": "他被老师批评后，露出一副委屈的模样。", "error_description": "错误形式：“一块委屈的模样”；正确形式：“一副委屈的模样”。“块”用于块状的东西，不能修饰表情神态，此处应用“副”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她听到消息后，露出一颗惊讶的模样。", "corrected_sentence": "她听到消息后，露出一副惊讶的模样。", "error_description": "错误形式：“一颗惊讶的模样”；正确形式：“一副惊讶的模样”。“颗”用于圆粒状的东西，不能修饰表情神态，此处应用“副”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
