INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人的长相或事物的外形。", "primary_collocate": null, "pronunciation": "mú yàng", "ipa": "mu˧˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她长得好看，模样很像她妈妈。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子的模样真可爱。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子的模样很特别。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不清他的模样了。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗的模样有点儿奇怪。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时模样很帅。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑起来的模样特别好看。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的模样跟老式火车差不多。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长着一副老实人的模样。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市现在的模样，我几乎不认识了。", "target_word": "模样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "模样：名词，人的长相、事物的外形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能说“很像她妈妈”。"}, {"text": "模样", "is_correct": true, "explanation": "正确。“模样”指人的长相，与“长得好看”“很像她妈妈”的语境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指报酬，与“很像她妈妈”语义不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”不能作“很像她妈妈”的主语，描述人的相貌要用“模样”之类的词。"}], "explanations": {"年龄": "语义：“年龄”指岁数，不能说“很像她妈妈”。", "模样": "正确。“模样”指人的长相，与“长得好看”“很像她妈妈”的语境相符。", "工资": "语义：“工资”指报酬，与“很像她妈妈”语义不通。", "书": "搭配：“书”不能作“很像她妈妈”的主语，描述人的相貌要用“模样”之类的词。"}, "sentence_index": 0, "correct_answer": "模样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的模样很甜。", "explanation": "这里应该用〈味道〉。“甜”形容味道，“模样”指外形，不能用来形容味觉。"}, {"text": "她的模样很好听。", "explanation": "这里应该用〈声音〉。“好听”形容声音，“模样”指外形，不能用来形容听觉。"}, {"text": "这道菜的模样很好吃。", "explanation": "这里应该用〈味道〉。“好吃”形容味道，“模样”指外形，不能用来形容味觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能用“好看”来形容笑起来的样子。"}, {"text": "模样", "is_correct": true, "explanation": "正确。“模样”指人的外形，与“笑起来的”“特别好看”搭配，句意通顺。"}, {"text": "嗓子", "is_correct": false, "explanation": "搭配：“好看”形容外貌或样子，不能用来形容嗓子。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，与“笑起来的”语义不通。"}], "explanations": {"脚步": "语义：“脚步”指走路的动作，不能用“好看”来形容笑起来的样子。", "模样": "正确。“模样”指人的外形，与“笑起来的”“特别好看”搭配，句意通顺。", "嗓子": "搭配：“好看”形容外貌或样子，不能用来形容嗓子。", "课本": "语义：“课本”是书，与“笑起来的”语义不通。"}, "sentence_index": 6, "correct_answer": "模样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的模样很贵。", "explanation": "这里应该用〈价格〉。“贵”形容价钱，“模样”指外形，不能说很贵。"}, {"text": "这首歌的模样很大声。", "explanation": "这里应该用〈音量〉。“大声”形容声音的强弱，“模样”不能用来形容声音。"}, {"text": "这杯茶的模样很烫。", "explanation": "这里应该用〈温度〉。“烫”形容温度，“模样”不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老奶奶有一块慈祥的模样。", "corrected_sentence": "这位老奶奶有一副慈祥的模样。", "error_description": "错误形式：“一块慈祥的模样”；正确形式：“一副慈祥的模样”。“块”用于块状的东西，形容长相、样子的“模样”前应用“副”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只猫露出一颗威风的模样。", "corrected_sentence": "这只猫露出一副威风的模样。", "error_description": "错误形式：“一颗威风的模样”；正确形式：“一副威风的模样”。“颗”用于圆粒状的东西，表示神态、样子时应用“副”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意思", "is_correct": true, "explanation": "“有意思”与“没有意思”构成反义，表示好玩、有趣。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”与“没有意思”无反义关系，指事情繁多或难懂。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“没有意思”无反义关系，指明白、分明。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”与“没有意思”无反义关系，指质地硬。"}], "correct_answer": "有意思", "explanations": {"有意思": "“有意思”与“没有意思”构成反义，表示好玩、有趣。", "复杂": "“复杂”与“没有意思”无反义关系，指事情繁多或难懂。", "清楚": "“清楚”与“没有意思”无反义关系，指明白、分明。", "坚硬": "“坚硬”与“没有意思”无反义关系，指质地硬。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
