INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好玩，让人觉得没趣。", "primary_collocate": null, "pronunciation": "méi yǒu yì si", "ipa": "meɪ˧˥ joʊ˨˩ i˥˩ sɹ̩", "syllable_count": 4, "sentences": [{"text": "这个游戏太没有意思了。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这部电影没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人在家玩，真没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书没有意思，我不想看。", "target_word": "没有意思", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天的足球比赛没有意思，没人看。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们都走了，我一个人觉得没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了一个小时电视，越看越没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课太长了，大家都觉得没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个节目没有意思，我关电视了。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑话一点也没有意思。", "target_word": "没有意思", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不好玩、让人觉得无聊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有意思", "is_correct": true, "explanation": "“没有意思”表示不好玩，与“太……了”搭配，评价游戏，句意通顺。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，游戏不说高大。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”指温度高，游戏不能说烫。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，游戏不能用咸来形容。"}], "explanations": {"没有意思": "“没有意思”表示不好玩，与“太……了”搭配，评价游戏，句意通顺。", "高大": "体貌：“高大”形容人或物的体型，游戏不说高大。", "烫": "语义：“烫”指温度高，游戏不能说烫。", "咸": "语义：“咸”指味道，游戏不能用咸来形容。"}, "sentence_index": 0, "correct_answer": "没有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很没有意思，我一口都没吃。", "explanation": "这里应该用〈没味道〉。“没有意思”说活动、节目等无趣，不用来形容菜的滋味。"}, {"text": "他这次考试的成绩很没有意思。", "explanation": "这里应该用〈不理想〉。“没有意思”评价活动或事情的趣味，不用来评价成绩的好坏。"}, {"text": "我今天身体没有意思，不想出门。", "explanation": "这里应该用〈没劲〉。“没劲”形容身体无力，“没有意思”只评价活动或事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有意思", "is_correct": true, "explanation": "“没有意思”表示不好玩，与“越看越”搭配，说的是看电视的感受，句意通顺。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容人或物的高度，电视不会越看越矮。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，与“越看越”的感受无关。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚度，看电视不会越看越厚。"}], "explanations": {"没有意思": "“没有意思”表示不好玩，与“越看越”搭配，说的是看电视的感受，句意通顺。", "矮": "体貌：“矮”形容人或物的高度，电视不会越看越矮。", "圆": "语义：“圆”形容形状，与“越看越”的感受无关。", "厚": "语义：“厚”形容物体的厚度，看电视不会越看越厚。"}, "sentence_index": 6, "correct_answer": "没有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很没有意思，大车开不过去。", "explanation": "这里应该用〈窄〉。“没有意思”说活动、节目等无趣，不用来形容道路的宽窄。"}, {"text": "我的手机没有意思，已经送人了。", "explanation": "这里应该用〈没用〉。“没有意思”评价活动或作品的趣味，手机失去功能应说“没用”。"}, {"text": "他最近很忙，没有意思吃饭。", "explanation": "这里应该用〈没心思〉。“没有意思”说事情或活动无趣，不用来说人的心思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得这部片子没有意思很，就走了。", "corrected_sentence": "我觉得这部片子没有意思，就走了。", "error_description": "错误：程度副词“很”放在了形容词“没有意思”后面，程度副词要放在形容词前。正确：应删去“很”，说“我觉得这部片子没有意思，就走了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天看了一场没有意思地演出，观众都走了。", "corrected_sentence": "我昨天看了一场没有意思的演出，观众都走了。", "error_description": "错误：“地”用在名词“演出”前，应为结构助词“的”。正确：修饰名词要用“的”，应为“没有意思的演出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
