INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水或东西倒进去。", "primary_collocate": null, "pronunciation": "zhù rù", "ipa": "ʈʂu˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他把热水注入杯子里。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水泥注入模具。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把温水注入浴缸里。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢把牛奶注入锅里。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把油注入机器里，它才会动。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士把药注入小瓶子里。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水注入水池，一会儿就满了。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把清水注入这个大瓶子。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把红色的水注入小杯。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把热汤注入碗里。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注入了", "label": "体标（了）"}, {"form": "注入过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "把液体或其他东西倒进容器、物体里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "注入：把热水倒进杯子里，与“他把……杯子里”的结构搭配，符合句意。"}, {"text": "搅拌", "is_correct": false, "explanation": "语义：“搅拌”指使物体混合，与把热水倒进杯子的动作不符。"}, {"text": "涂", "is_correct": false, "explanation": "语义：“涂”指把东西抹在表面，不能抹进杯子里。"}, {"text": "挤", "is_correct": false, "explanation": "搭配：“挤”多用于膏状物，热水不能说挤。"}], "explanations": {"注入": "注入：把热水倒进杯子里，与“他把……杯子里”的结构搭配，符合句意。", "搅拌": "语义：“搅拌”指使物体混合，与把热水倒进杯子的动作不符。", "涂": "语义：“涂”指把东西抹在表面，不能抹进杯子里。", "挤": "搭配：“挤”多用于膏状物，热水不能说挤。"}, "sentence_index": 0, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她慢慢把牛奶注入了桌面上。", "explanation": "这里应该用〈倒〉。注入强调灌进容器或物体内部，倒在桌面上的牛奶不说注入。"}, {"text": "妈妈把水果注入了篮子里。", "explanation": "这里应该用〈装〉。注入只用于液体或可流动的东西灌进容器，把水果放进篮子要说装。"}, {"text": "工人把钉子注入了木板里。", "explanation": "这里应该用〈钉〉。注入指液体或可流动的东西灌进去，把钉子打进木板要说钉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "注入：把水灌进水池，与“一会儿就满了”的结果相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”是把水送进口中，水不能被喝进水池。"}, {"text": "蒸", "is_correct": false, "explanation": "语义：“蒸”指用水汽加热食物，与往水池里放水不符。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，水不能被挖进水池。"}], "explanations": {"注入": "注入：把水灌进水池，与“一会儿就满了”的结果相符。", "喝": "语义：“喝”是把水送进口中，水不能被喝进水池。", "蒸": "语义：“蒸”指用水汽加热食物，与往水池里放水不符。", "挖": "语义：“挖”指挖掘，水不能被挖进水池。"}, "sentence_index": 6, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体重注入了。", "explanation": "这里应该用〈增加〉。注入表示某物流进或灌进某处，体重的变化要说增加。"}, {"text": "这台机器的温度注入了。", "explanation": "这里应该用〈降低〉。注入表示某物灌进某处，温度下降要说降低。"}, {"text": "大量游客注入了景区。", "explanation": "这里应该用〈涌入〉。注入多指液体、资金、力量流进某处，大量游客拥进景区要说涌入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把热汤注入在碗里。", "corrected_sentence": "工人把热汤注入碗里。", "error_description": "错误：“注入”后多加了“在”。“注入”后直接接处所“碗里”，不能说“注入在碗里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们把牛奶的注入杯子里。", "corrected_sentence": "孩子们把牛奶注入杯子里。", "error_description": "错误：「牛奶」后多加了「的」，「注入」变成名词，「把」字句缺少谓语动词。应说「把牛奶注入杯子里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "流出与流入相对，指液体从某处流到别处，是“注入小河”这一义项的反义词。"}, {"text": "保持", "is_correct": false, "explanation": "保持与注入没有反义关系，指使某种状态不变。"}, {"text": "收集", "is_correct": false, "explanation": "收集与注入没有反义关系，指聚拢、集中。"}, {"text": "停留", "is_correct": false, "explanation": "停留与注入没有反义关系，指暂时不动。"}], "correct_answer": "流出", "explanations": {"流出": "流出与流入相对，指液体从某处流到别处，是“注入小河”这一义项的反义词。", "保持": "保持与注入没有反义关系，指使某种状态不变。", "收集": "收集与注入没有反义关系，指聚拢、集中。", "停留": "停留与注入没有反义关系，指暂时不动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "流入或灌进；使进入。", "primary_collocate": null, "pronunciation": "zhù rù", "ipa": "ʈʂu˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "这条河向东注入大海。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司注入了一大笔钱。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新老师给班里注入了活力。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水注入小河，河水涨高了。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府向学校注入了很多资金。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌给我注入了新的力量。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江的水注入东海。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想给这家店注入新的想法。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小溪注入湖里，湖水变清了。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新朋友给生活注入了快乐。", "target_word": "注入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注入了", "label": "体标（了）"}, {"form": "注入过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "河水等流进某处，或把资金、活力等投入某处，使其进入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "注入", "is_correct": true, "explanation": "正确答案：注入（zhù rù），指流入或灌进。"}, {"text": "出入", "is_correct": false, "explanation": "chū rù（第一声）与 zhù rù 的声母 ch 与 zh 不同，声调也不同，意思是进出。"}, {"text": "坠入", "is_correct": false, "explanation": "zhuì rù（第四声）与 zhù rù 的韵母不同（-uì 与 -u），意思是掉进，如坠入深渊。"}, {"text": "准入", "is_correct": false, "explanation": "zhǔn rù（第三声）与 zhù rù 的韵母和声调都不同，意思是允许进入。"}], "explanations": {"注入": "正确答案：注入（zhù rù），指流入或灌进。", "出入": "chū rù（第一声）与 zhù rù 的声母 ch 与 zh 不同，声调也不同，意思是进出。", "坠入": "zhuì rù（第四声）与 zhù rù 的韵母不同（-uì 与 -u），意思是掉进，如坠入深渊。", "准入": "zhǔn rù（第三声）与 zhù rù 的韵母和声调都不同，意思是允许进入。"}, "sentence_index": null, "correct_answer": "注入"}, "level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "注入：流入某处，与“河”和“大海”搭配，符合句意。"}, {"text": "扔进", "is_correct": false, "explanation": "语义：河流不能扔东西，“扔进”的施事必须是人，与“河”不合。"}, {"text": "跳入", "is_correct": false, "explanation": "配价：“跳入”要求有生命的主语，河不会跳。"}, {"text": "喷入", "is_correct": false, "explanation": "搭配：“喷入”多指气体或液体从狭口射出，河水流入大海不说喷入。"}], "explanations": {"注入": "注入：流入某处，与“河”和“大海”搭配，符合句意。", "扔进": "语义：河流不能扔东西，“扔进”的施事必须是人，与“河”不合。", "跳入": "配价：“跳入”要求有生命的主语，河不会跳。", "喷入": "搭配：“喷入”多指气体或液体从狭口射出，河水流入大海不说喷入。"}, "sentence_index": 0, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨后小河的水量注入了。", "explanation": "这里应该用〈增加〉。注入表示某物流入或灌进某处，水量变多要说增加。"}, {"text": "他把书注入了书架。", "explanation": "这里应该用〈放〉。注入指资金、力量或液体流进某处，书是固体，摆上书架要说放。"}, {"text": "工人把石头注入了河里。", "explanation": "这里应该用〈扔〉。注入指液体或可流动的东西流进某处，石头是固体，把它扔进河里要说扔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "注入：流入某处，与“长江的水”和“东海”搭配，符合句意。"}, {"text": "照亮", "is_correct": false, "explanation": "语义：“照亮”指光使某处明亮，江水不会发光，不能照亮东海。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉”指给农田浇水，东海不需要灌溉。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：“喂养”要求有生命的宾语，东海不能被喂养。"}], "explanations": {"注入": "注入：流入某处，与“长江的水”和“东海”搭配，符合句意。", "照亮": "语义：“照亮”指光使某处明亮，江水不会发光，不能照亮东海。", "灌溉": "语义：“灌溉”指给农田浇水，东海不需要灌溉。", "喂养": "配价：“喂养”要求有生命的宾语，东海不能被喂养。"}, "sentence_index": 6, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格注入了。", "explanation": "这里应该用〈降低〉。注入表示流进某处或投入某处，价格下降要说降低。"}, {"text": "这座城市的规模注入了。", "explanation": "这里应该用〈扩大〉。注入表示流进某处或投入某处，规模变大要说扩大。"}, {"text": "这辆车的速度注入了。", "explanation": "这里应该用〈加快〉。注入表示流进某处或投入某处，速度变快要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水注入给这条小河。", "corrected_sentence": "雨水注入这条小河。", "error_description": "错误：“注入”后多加了“给”。“注入”直接带处所宾语，正确说法是“雨水注入这条小河”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔资金的注入了这个项目。", "corrected_sentence": "这笔资金注入了这个项目。", "error_description": "错误：「资金」后多加了「的」，「注入」变成名词，句子没有谓语。应说「这笔资金注入了这个项目」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "慢慢变小，最后没有了。", "primary_collocate": null, "pronunciation": "xiāo", "ipa": "ɕjau̯˥", "syllable_count": 1, "sentences": [{"text": "过了两天，脚上的肿慢慢消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，水慢慢消下去了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来，路上的雪消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的气过一会儿就消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，药吃完肿就会消。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，我的担心才慢慢消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脸上的红印还没消。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药吃了以后，热也慢慢消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，嗓子的痛一点一点消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，他心里的难过也就消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消了", "label": "体标"}, {"form": "消下去", "label": "复合"}], "register": "中性", "sense_fingerprint": "肿、气、痛等慢慢变小直到没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。"}, {"text": "笑", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。"}, {"text": "修", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。", "小": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。", "笑": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。", "香": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。", "修": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消”表示肿慢慢变小直到没有，与“脚上的肿慢慢……了”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指写字，肿不能被写，与句意不符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”要接可以穿戴的东西，不能与“肿”搭配。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，肿不能用说话的方式消失，与句意不符。"}], "explanations": {"消": "“消”表示肿慢慢变小直到没有，与“脚上的肿慢慢……了”相符。", "写": "语义：“写”指写字，肿不能被写，与句意不符。", "戴": "搭配：“戴”要接可以穿戴的东西，不能与“肿”搭配。", "说": "语义：“说”指说话，肿不能用说话的方式消失，与句意不符。"}, "sentence_index": 0, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察很快就消了这伙坏人。", "explanation": "这里应该用〈消灭〉。此处是人为歼灭坏人，“消”单用不表示这一意思，应用双音节“消灭”。"}, {"text": "他把钱消在了箱子里。", "explanation": "这里应该用〈藏〉。“消”表示慢慢变小直到没有，不表示把东西收起来，“藏”才是这个意思。"}, {"text": "农民用药水消了田里的害虫。", "explanation": "这里应该用〈消灭〉。用药杀死害虫要说“消灭”，“消”单用不表示这一意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。"}, {"text": "效", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。"}, {"text": "休", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。"}, {"text": "晓", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。", "效": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。", "休": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。", "乡": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。", "晓": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消”表示红印慢慢变淡直到没有，与“脸上的红印还没……”相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指发光或明亮，红印不能用“亮”来描述消失的过程。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”要接衣物等，不能与“红印”搭配。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，红印不能被吹掉，与句意不符。"}], "explanations": {"消": "“消”表示红印慢慢变淡直到没有，与“脸上的红印还没……”相符。", "亮": "语义：“亮”指发光或明亮，红印不能用“亮”来描述消失的过程。", "穿": "搭配：“穿”要接衣物等，不能与“红印”搭配。", "吹": "语义：“吹”指用气流推动，红印不能被吹掉，与句意不符。"}, "sentence_index": 6, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生很快就消了这种病毒。", "explanation": "这里应该用〈消灭〉。病毒被彻底杀死要说“消灭”，“消”单用不表示这一意思。"}, {"text": "他用湿布消了桌子上的灰。", "explanation": "这里应该用〈擦〉。用湿布去掉灰尘是擦拭的动作，“消”单用不表示这一意思，应说“擦”。"}, {"text": "厨房的蟑螂被他一晚上消了。", "explanation": "这里应该用〈消灭〉。蟑螂被杀死要说“消灭”，“消”单用不表示这一意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "第二天，他脸上的肿就消起来了。", "corrected_sentence": "第二天，他脸上的肿就消下去了。", "error_description": "补语错误：“消”表示慢慢减少直至没有，应接“下去”，不能接“起来”。应改为“消下去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他脸上的肿还没完全消了。", "corrected_sentence": "他脸上的肿还没完全消。", "error_description": "体标错误：“没”表示尚未发生，与“了”不能同用，应去掉“了”，说“还没完全消”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
