INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把食物放在火边或炉子里，让它变熟。", "primary_collocate": null, "pronunciation": "kǎo", "ipa": "kʰɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈在烤箱里烤蛋糕。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把肉放在火上烤。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园里烤鱼。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包要烤二十分钟。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他烤了两个红薯。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把鸡烤得很香。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在火边烤着玉米。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我想烤一块蛋糕。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把鱼烤熟了才拿出来。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些羊肉烤过以后很好吃。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烤了", "label": "体标（了）"}, {"form": "烤着", "label": "体标（着）"}, {"form": "烤过", "label": "体标（过）"}, {"form": "烤箱", "label": "复合词"}, {"form": "烤鸭", "label": "复合词"}], "register": "口语", "sense_fingerprint": "用火或烤炉把食物加热做熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烤", "is_correct": true, "explanation": "正确答案：烤（kǎo），用火或炉子把食物加热做熟。"}, {"text": "好", "is_correct": false, "explanation": "hǎo（第三声）与 kǎo 的声母 h 与 k 不同，意思是好。"}, {"text": "靠", "is_correct": false, "explanation": "kào（第四声）与 kǎo 的声调不同，意思是靠近。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 kǎo 的声母和声调都不同，意思是告诉。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同，意思是稿子。"}], "explanations": {"烤": "正确答案：烤（kǎo），用火或炉子把食物加热做熟。", "好": "hǎo（第三声）与 kǎo 的声母 h 与 k 不同，意思是好。", "靠": "kào（第四声）与 kǎo 的声调不同，意思是靠近。", "告": "gào（第四声）与 kǎo 的声母和声调都不同，意思是告诉。", "稿": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同，意思是稿子。"}, "sentence_index": null, "correct_answer": "烤"}, "level_3": {"options": [{"text": "烤", "is_correct": true, "explanation": "烤：用烤箱加热蛋糕使其做熟，与“烤箱里”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”多用于锅中加水加热的食物，不说在烤箱里煮蛋糕。"}, {"text": "炸", "is_correct": false, "explanation": "语义：“炸”要用热油，与烤箱里加热的条件不符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，不是对蛋糕加热的动作。"}], "explanations": {"烤": "烤：用烤箱加热蛋糕使其做熟，与“烤箱里”搭配，符合句意。", "煮": "搭配：“煮”多用于锅中加水加热的食物，不说在烤箱里煮蛋糕。", "炸": "语义：“炸”要用热油，与烤箱里加热的条件不符。", "吃": "语义：“吃”是进食，不是对蛋糕加热的动作。"}, "sentence_index": 0, "correct_answer": "烤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面条要烤五分钟。", "explanation": "这里应该用〈煮〉。面条要下锅用水煮，不用烤。"}, {"text": "妈妈在锅里烤青菜。", "explanation": "这里应该用〈炒〉。烤是把食物放在火边或炉子里使其变熟，青菜在锅里翻动加热要说炒。"}, {"text": "汤要烤一个小时。", "explanation": "这里应该用〈炖〉。汤是液体，要用炖或煮，不能放在火上烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烤", "is_correct": true, "explanation": "正确答案：烤（kǎo），用火或炉子把食物加热做熟。"}, {"text": "口", "is_correct": false, "explanation": "kǒu（第三声）与 kǎo 的韵母不同（-ou 与 -ao），意思是嘴。"}, {"text": "高", "is_correct": false, "explanation": "gāo（第一声）与 kǎo 的声母 g 与 k 不同，声调也不同，意思是高。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同（不送气与送气），意思是做、干。"}, {"text": "号", "is_correct": false, "explanation": "hào（第四声）与 kǎo 的声母和声调都不同，意思是号码。"}], "explanations": {"烤": "正确答案：烤（kǎo），用火或炉子把食物加热做熟。", "口": "kǒu（第三声）与 kǎo 的韵母不同（-ou 与 -ao），意思是嘴。", "高": "gāo（第一声）与 kǎo 的声母 g 与 k 不同，声调也不同，意思是高。", "搞": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同（不送气与送气），意思是做、干。", "号": "hào（第四声）与 kǎo 的声母和声调都不同，意思是号码。"}, "sentence_index": null, "correct_answer": "烤"}, "level_3": {"options": [{"text": "烤", "is_correct": true, "explanation": "烤：在火边加热玉米使其做熟，与“孩子们在火边”搭配，符合句意。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”是采下，与在火边加热的动作不符。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”需要接受者，“玉米”不能单独作“喂”的对象。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”指借助太阳变干，与“火边”的条件矛盾。"}], "explanations": {"烤": "烤：在火边加热玉米使其做熟，与“孩子们在火边”搭配，符合句意。", "摘": "语义：“摘”是采下，与在火边加热的动作不符。", "喂": "配价：“喂”需要接受者，“玉米”不能单独作“喂”的对象。", "晒": "语义：“晒”指借助太阳变干，与“火边”的条件矛盾。"}, "sentence_index": 6, "correct_answer": "烤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把橘子烤成了汁。", "explanation": "这里应该用〈榨〉。烤是加热做熟，把橘子变成汁要说榨。"}, {"text": "他把肉烤成了馅。", "explanation": "这里应该用〈剁〉。烤不能把肉变成碎末，把肉剁成馅要说剁。"}, {"text": "他把菜烤成了泡菜。", "explanation": "这里应该用〈腌〉。泡菜要把菜用盐水或调料腌制后发酵，不是烤出来的，烤只表示靠近火加热使食物变熟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在炉子上烤把羊肉。", "corrected_sentence": "他在炉子上烤羊肉。", "error_description": "错误：“把”的位置不对。“把”要放在宾语前面，不能插在“烤”和“羊肉”之间，应说“烤羊肉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把肉烤了熟才吃。", "corrected_sentence": "他把肉烤熟了才吃。", "error_description": "错误：结果补语“熟”的位置不对。应说“烤熟”，“熟”紧跟动词，“了”放在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
