INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西靠近火，使它变干或使人取暖。", "primary_collocate": null, "pronunciation": "kǎo", "ipa": "kʰɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把湿手套拿到火边烤干了。", "target_word": "烤", "complexity_tier": "T3", "furigana": "tā bǎ shī shǒu tào ná dào huǒ biān kǎo gān le", "sentence_source": "generated"}, {"text": "湿衣服要烤干才能穿。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风大，妈妈在火盆边烤干了孩子的湿衣服。", "target_word": "烤", "complexity_tier": "T3", "furigana": "fēng dà, mā ma zài huǒ pén biān kǎo gān le hái zi de shī yī fu", "sentence_source": "generated"}, {"text": "我把湿鞋子放在火边烤。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天奶奶在火盆边把湿棉鞋烤干。", "target_word": "烤", "complexity_tier": "T3", "furigana": "dōng tiān nǎi nai zài huǒ pén biān bǎ shī mián xié kǎo gān", "sentence_source": "generated"}, {"text": "他把湿帽子烤干了。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，大家在火边烤衣服。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，把湿袜子拿过来放火边烤干吧。", "target_word": "烤", "complexity_tier": "T3", "furigana": "lái, bǎ shī wà zi ná guò lái fàng huǒ biān kǎo gān ba", "sentence_source": "generated"}, {"text": "他把湿靴子放在炉子边烤干了。", "target_word": "烤", "complexity_tier": "T3", "furigana": "tā bǎ shī xuē zi fàng zài lú zi biān kǎo gān le", "sentence_source": "generated"}, {"text": "雨后他们烤了半天衣服。", "target_word": "烤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烤了", "label": "体标（了）"}, {"form": "烤着", "label": "体标（着）"}, {"form": "烤过", "label": "体标（过）"}, {"form": "烤烤", "label": "重叠"}, {"form": "烤火", "label": "复合词"}], "register": "口语", "sense_fingerprint": "把手、衣物等靠近火，使取暖或变干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烤", "is_correct": true, "explanation": "正确答案：烤（kǎo），把东西靠近火使熟或干。"}, {"text": "好", "is_correct": false, "explanation": "hǎo（第三声）与 kǎo 的声母 h 与 k 不同，意思是好。"}, {"text": "靠", "is_correct": false, "explanation": "kào（第四声）与 kǎo 的声调不同，意思是靠近。"}, {"text": "高", "is_correct": false, "explanation": "gāo（第一声）与 kǎo 的声母 g 与 k 不同，声调也不同，意思是高。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同（不送气与送气），意思是做、干。"}], "explanations": {"烤": "正确答案：烤（kǎo），把东西靠近火使熟或干。", "好": "hǎo（第三声）与 kǎo 的声母 h 与 k 不同，意思是好。", "靠": "kào（第四声）与 kǎo 的声调不同，意思是靠近。", "高": "gāo（第一声）与 kǎo 的声母 g 与 k 不同，声调也不同，意思是高。", "搞": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同（不送气与送气），意思是做、干。"}, "sentence_index": null, "correct_answer": "烤"}, "level_3": {"options": [{"text": "烤", "is_correct": true, "explanation": "烤：靠近火使湿物变干，与“拿到火边”和“干了”搭配，符合句意。"}, {"text": "泡", "is_correct": false, "explanation": "语义：“泡”指浸在水中，与使手套变干的结果相反。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”指借助太阳变干，与“火边”的条件矛盾。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：“熨”指用熨斗压平，不说靠近火使手套变干。"}], "explanations": {"烤": "烤：靠近火使湿物变干，与“拿到火边”和“干了”搭配，符合句意。", "泡": "语义：“泡”指浸在水中，与使手套变干的结果相反。", "晒": "语义：“晒”指借助太阳变干，与“火边”的条件矛盾。", "熨": "搭配：“熨”指用熨斗压平，不说靠近火使手套变干。"}, "sentence_index": 0, "correct_answer": "烤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把湿鞋子挂在通风处烤干。", "explanation": "这里应该用〈晾〉。烤要靠近火加热，挂在通风处让东西自然变干要说晾。"}, {"text": "他用熨斗把湿衣服烤平了。", "explanation": "这里应该用〈熨〉。烤是靠近火加热使物体干或熟，把衣服弄平要说熨，不能说烤。"}, {"text": "用毛巾烤干手上的水。", "explanation": "这里应该用〈擦〉。烤要靠近火加热，用毛巾去掉手上的水要说擦干，不能说烤干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烤", "is_correct": true, "explanation": "正确答案：烤（kǎo），把东西靠近火使熟或干。"}, {"text": "口", "is_correct": false, "explanation": "kǒu（第三声）与 kǎo 的韵母不同（-ou 与 -ao），意思是嘴。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 kǎo 的声母和声调都不同，意思是告诉。"}, {"text": "号", "is_correct": false, "explanation": "hào（第四声）与 kǎo 的声母和声调都不同，意思是号码。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同，意思是稿子。"}], "explanations": {"烤": "正确答案：烤（kǎo），把东西靠近火使熟或干。", "口": "kǒu（第三声）与 kǎo 的韵母不同（-ou 与 -ao），意思是嘴。", "告": "gào（第四声）与 kǎo 的声母和声调都不同，意思是告诉。", "号": "hào（第四声）与 kǎo 的声母和声调都不同，意思是号码。", "稿": "gǎo（第三声）与 kǎo 的声母 g 与 k 不同，意思是稿子。"}, "sentence_index": null, "correct_answer": "烤"}, "level_3": {"options": [{"text": "烤", "is_correct": true, "explanation": "烤：靠近火使衣服变干，与“下雨后”和“在火边”搭配，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”会把衣服烧坏，与下雨后取暖晾干的语境不符。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”的对象是食物，衣服不能嚼。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是扯破，与使衣服变干的意思不符。"}], "explanations": {"烤": "烤：靠近火使衣服变干，与“下雨后”和“在火边”搭配，符合句意。", "烧": "语义：“烧”会把衣服烧坏，与下雨后取暖晾干的语境不符。", "嚼": "搭配：“嚼”的对象是食物，衣服不能嚼。", "撕": "语义：“撕”是扯破，与使衣服变干的意思不符。"}, "sentence_index": 6, "correct_answer": "烤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在河里烤了半天衣服。", "explanation": "这里应该用〈洗〉。烤要靠近火加热，在河里处理衣物要说洗，不能说烤。"}, {"text": "她把衣服烤整齐了。", "explanation": "这里应该用〈叠〉。烤是靠近火加热使干或熟，衣服变整齐要说叠。"}, {"text": "她把布烤成了两块。", "explanation": "这里应该用〈剪〉。烤不会把东西切开，把布分成两块要说剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把湿鞋子烤了干。", "corrected_sentence": "他把湿鞋子烤干了。", "error_description": "错误：结果补语“干”的位置不对。应说“烤干”，“干”紧跟动词，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨后他们在火边烤把衣服。", "corrected_sentence": "雨后他们在火边烤衣服。", "error_description": "错误：“把”的位置不对。“把”要放在宾语前面，不能插在“烤”和“衣服”之间，应说“烤衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里很着急，很不安，担心事情不好。", "primary_collocate": null, "pronunciation": "jiāo lǜ", "ipa": "tɕjaʊ˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "儿子还没回家，妈妈很焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等结果的时候，我特别焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很焦虑，一直在走来走去。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太焦虑，事情会好起来的。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快要考试了，同学们都有点儿焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她焦虑地看着手机，等医生的电话。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到工作，他变得越来越焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人焦虑地等了一个晚上。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你很焦虑，但是先吃点东西吧。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点了，大家都很焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "焦虑不安", "label": "复合"}, {"form": "焦虑症", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：心里着急不安，担心事情会不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦虑", "is_correct": true, "explanation": "正确。「很」后接表示心理状态的形容词，「焦虑」与「儿子还没回家」的担忧语境相合。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：「愉快」表示高兴，与「儿子还没回家」的担心语境相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」说外貌，不能用来描述心情，与「很」后的心理状态不合。"}, {"text": "高深", "is_correct": false, "explanation": "语义：「高深」用于学问或道理，不能用来描述妈妈此刻的心情。"}], "explanations": {"焦虑": "正确。「很」后接表示心理状态的形容词，「焦虑」与「儿子还没回家」的担忧语境相合。", "愉快": "语义：「愉快」表示高兴，与「儿子还没回家」的担心语境相反。", "漂亮": "体貌：「漂亮」说外貌，不能用来描述心情，与「很」后的心理状态不合。", "高深": "语义：「高深」用于学问或道理，不能用来描述妈妈此刻的心情。"}, "sentence_index": 0, "correct_answer": "焦虑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都很焦虑地庆祝这个好消息。", "explanation": "这里应该用〈高兴〉。「焦虑」表示担心不安，与「庆祝好消息」的心情相反。"}, {"text": "孩子们焦虑地在草地上玩耍。", "explanation": "这里应该用〈欢乐〉。「焦虑」表示担心不安，与「玩耍」的轻松心情冲突。"}, {"text": "一朵焦虑的花开在窗前。", "explanation": "这里应该用〈清香〉。「焦虑」表示心里不安，不能用来形容花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦虑", "is_correct": true, "explanation": "正确。「变得越来越」后接心理状态，「焦虑」与「找不到工作」的处境相合。"}, {"text": "清爽", "is_correct": false, "explanation": "语义：「清爽」形容清凉舒适的感觉，与「找不到工作」的处境不合。"}, {"text": "整齐", "is_correct": false, "explanation": "体貌：「整齐」说外观有序，不能形容心理的变化，与语境不合。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」说光线或外貌，不能描述「找不到工作」带来的心理变化。"}], "explanations": {"焦虑": "正确。「变得越来越」后接心理状态，「焦虑」与「找不到工作」的处境相合。", "清爽": "语义：「清爽」形容清凉舒适的感觉，与「找不到工作」的处境不合。", "整齐": "体貌：「整齐」说外观有序，不能形容心理的变化，与语境不合。", "明亮": "语义：「明亮」说光线或外貌，不能描述「找不到工作」带来的心理变化。"}, "sentence_index": 6, "correct_answer": "焦虑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很焦虑，我们去公园吧。", "explanation": "这里应该用〈凉快〉。「焦虑」形容人的心情，不能用来形容天气。"}, {"text": "这间房子很焦虑，大家都喜欢。", "explanation": "这里应该用〈干净〉。「焦虑」形容人的心情，不能用来形容房间。"}, {"text": "这次会议进行得很焦虑。", "explanation": "这里应该用〈圆满〉。「焦虑」形容人的心情，不能用来评价会议的进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他焦虑的等着电话，一直没睡。", "corrected_sentence": "他焦虑地等着电话，一直没睡。", "error_description": "的地误用：「焦虑」修饰动词「等」，状语后应用〈地〉，不用〈的〉。正确形式是「焦虑地等着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她焦虑的很，一直在等消息。", "corrected_sentence": "她焦虑得很，一直在等消息。", "error_description": "错误形式：「焦虑的很」误用「的」。正确形式：「焦虑得很」。原因：形容词后接程度补语「很」时，中间要用「得」，不用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
