INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因担心而烦躁不安的情绪状态。", "primary_collocate": null, "pronunciation": "jiāo lǜ", "ipa": "tɕjaʊ˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "考试前，他心里充满了焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种焦虑让她整夜睡不着。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动可以减轻你的焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的焦虑常常来自大人。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想让家人看到自己的焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力太大，会带来很多焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐帮她缓解了焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，长期的焦虑对身体不好。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对未来，年轻人常有一种焦虑。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把心里的焦虑写在了日记里。", "target_word": "焦虑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "焦虑症", "label": "复合"}, {"form": "焦虑感", "label": "复合"}, {"form": "焦虑不安", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：因担心而产生的烦躁不安的情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦虑", "is_correct": true, "explanation": "正确。「充满了」后接表示情绪的名词，「焦虑」与「心里」「考试前」的语境相合。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土是具体的物质，不能充满人的内心，与情绪语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是具体的物质，与「心里充满」所指的抽象情绪不合。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：「充满」不与「工具」搭配，「心里充满工具」不成话。"}], "explanations": {"焦虑": "正确。「充满了」后接表示情绪的名词，「焦虑」与「心里」「考试前」的语境相合。", "泥土": "语义：泥土是具体的物质，不能充满人的内心，与情绪语境不合。", "空气": "语义：空气是具体的物质，与「心里充满」所指的抽象情绪不合。", "工具": "搭配：「充满」不与「工具」搭配，「心里充满工具」不成话。"}, "sentence_index": 0, "correct_answer": "焦虑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我心里有一把焦虑。", "explanation": "这里不能用〈把〉。「把」用于有柄或能握住的东西；焦虑是情绪，应用〈种〉或〈阵〉。"}, {"text": "我心里有一张焦虑。", "explanation": "这里不能用〈张〉。「张」用于平面的东西；焦虑是情绪，应用〈种〉或〈阵〉。"}, {"text": "我心里有一根焦虑。", "explanation": "这里不能用〈根〉。「根」用于细长的东西；焦虑是情绪，应用〈种〉或〈阵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦虑", "is_correct": true, "explanation": "正确。「缓解」的对象是焦虑这类情绪，与「听音乐」「帮她」的语境相合。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天是季节，不是可以被「缓解」的病痛或情绪。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物件，不能被「缓解」。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：「缓解」后接的应是情绪、病痛或压力，「水泥」搭配不通。"}], "explanations": {"焦虑": "正确。「缓解」的对象是焦虑这类情绪，与「听音乐」「帮她」的语境相合。", "冬天": "语义：冬天是季节，不是可以被「缓解」的病痛或情绪。", "桌子": "语义：桌子是物件，不能被「缓解」。", "水泥": "搭配：「缓解」后接的应是情绪、病痛或压力，「水泥」搭配不通。"}, "sentence_index": 6, "correct_answer": "焦虑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的焦虑很鲜艳。", "explanation": "这里应该用〈颜色〉。「焦虑」指担心不安的情绪，不能用来形容布料的颜色。"}, {"text": "他有一个坚定的焦虑，走进了考场。", "explanation": "这里应该用〈信念〉。「坚定」形容信念、立场，「焦虑」是担心不安的情绪，不能说「坚定的焦虑」。"}, {"text": "这双鞋的焦虑太贵了。", "explanation": "这里应该用〈价格〉。「焦虑」指担心不安的情绪，不能用来说东西的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里涌起了一把焦虑。", "corrected_sentence": "他心里涌起了一阵焦虑。", "error_description": "量词错误：「焦虑」是情绪，应用量词〈阵〉；「把」用于有柄的东西，不能用于情绪。正确形式是「一阵焦虑」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里有两种焦虑着，很难说清。", "corrected_sentence": "他心里有两种焦虑，很难说清。", "error_description": "错误形式：“两种焦虑”后加了“着”。正确形式：说“两种焦虑”。原因：“焦虑”在此作名词，前有数量短语“两种”修饰，不能带动态助词“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
