INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96603, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现在还留着的。", "primary_collocate": null, "pronunciation": "xiàn cún", "ipa": "ɕjɛn˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "这是现存最老的一座桥。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的老房子已经不多了。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是现存最早的版本。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里现存的画有三百多幅。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的树只有那几棵了。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要好好保护现存的古迹。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是现存唯一的一张老照片。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城现存的旧城墙只剩一段了。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的资料都放在这个柜子里。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里现存最大的一座庙已有八百年历史。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現存", "label": "繁体"}], "register": "书面", "sense_fingerprint": "现在还留下来的（旧物、遗迹、资料等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现存", "is_correct": true, "explanation": "目标词，xiàn cún，意思是现在还留着的。"}, {"text": "显存", "is_correct": false, "explanation": "显存（xiǎn cún）与现存（xiàn cún）声调不同，第三声与第四声，意思是显卡上的存储器。"}, {"text": "先存", "is_correct": false, "explanation": "先存（xiān cún）与现存（xiàn cún）声调不同，第一声与第四声，意思是事先存放。"}, {"text": "现成", "is_correct": false, "explanation": "现成（xiàn chéng）与现存（xiàn cún）读音相近，声母 ch 与 c、韵母 eng 与 un 不同，意思是已经准备好的。"}], "explanations": {"现存": "目标词，xiàn cún，意思是现在还留着的。", "显存": "显存（xiǎn cún）与现存（xiàn cún）声调不同，第三声与第四声，意思是显卡上的存储器。", "先存": "先存（xiān cún）与现存（xiàn cún）声调不同，第一声与第四声，意思是事先存放。", "现成": "现成（xiàn chéng）与现存（xiàn cún）读音相近，声母 ch 与 c、韵母 eng 与 un 不同，意思是已经准备好的。"}, "sentence_index": null, "correct_answer": "现存"}, "level_3": {"options": [{"text": "现存", "is_correct": true, "explanation": "「现存」修饰「最老的一座桥」，指现在还留着的桥，符合句意。"}, {"text": "新", "is_correct": false, "explanation": "语义：「新」与「最老」矛盾，桥不可能既新又是最老的。"}, {"text": "现代", "is_correct": false, "explanation": "语义：「现代」指当代，与「最老」的意思相悖。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外貌，不用来说桥的年代。"}], "explanations": {"现存": "「现存」修饰「最老的一座桥」，指现在还留着的桥，符合句意。", "新": "语义：「新」与「最老」矛盾，桥不可能既新又是最老的。", "现代": "语义：「现代」指当代，与「最老」的意思相悖。", "漂亮": "搭配：「漂亮」形容外貌，不用来说桥的年代。"}, "sentence_index": 0, "correct_answer": "现存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现存的年轻人很喜欢运动。", "explanation": "这里应该用〈现在〉。「现在的」指当下的人，「现存」只指留存下来的旧物、遗迹，不用于说人。"}, {"text": "这是去年刚建成的现存大楼。", "explanation": "这里应该用〈现代〉。「现存」指留存下来的旧物、遗迹，刚建成的大楼要说「现代」的。"}, {"text": "公司现存员工两百多人。", "explanation": "这里应该用〈现有〉。「现有」用于人员和数量，「现存」指留存下来的旧物、遗迹等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现存", "is_correct": true, "explanation": "「现存」指现在还留着，修饰「唯一的一张老照片」，符合句意。"}, {"text": "崭新", "is_correct": false, "explanation": "语义：「崭新」指全新的，与「老照片」矛盾。"}, {"text": "最新", "is_correct": false, "explanation": "语义：「最新」指刚出现的，与「老照片」矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」形容体形，不用来修饰照片。"}], "explanations": {"现存": "「现存」指现在还留着，修饰「唯一的一张老照片」，符合句意。", "崭新": "语义：「崭新」指全新的，与「老照片」矛盾。", "最新": "语义：「最新」指刚出现的，与「老照片」矛盾。", "高大": "搭配：「高大」形容体形，不用来修饰照片。"}, "sentence_index": 6, "correct_answer": "现存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现存的形势很复杂。", "explanation": "这里应该用〈当前〉。「当前」指眼下正在发生的情况，「现存」只指留下来的旧物、遗迹等，不用于形势。"}, {"text": "地震后现存的人都很坚强。", "explanation": "这里应该用〈幸存〉。「幸存」指灾难后活下来的人，「现存」不用于指人。"}, {"text": "那家店现存的旧书都已经卖光了。", "explanation": "这里应该用〈以前的〉。「现存」指目前仍然存在，已经卖光的旧书不能说「现存」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里现存了的古戏台很有名。", "corrected_sentence": "村里现存的古戏台很有名。", "error_description": "「现存」是形容词，后面不能加「了」。应说「现存的古戏台」，不能说「现存了的古戏台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物馆里现存地古钟只有三座。", "corrected_sentence": "博物馆里现存的古钟只有三座。", "error_description": "「现存」修饰名词时要用「的」，不能用「地」。「地」用于动词、形容词作状语，这里应说「现存的古钟」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
