INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "目前仍然存在的。", "primary_collocate": null, "pronunciation": "xiàn cún", "ipa": "ɕjɛn˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "我们先解决现存的问题。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的规定已经有点儿旧了。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的办法都不太好用。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动物现存的数量很少。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上现存的语言有几千种。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的困难，我们一起想办法。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的做法需要改一改。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市现存的公园不到十个。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的这些问题，大家都看到了。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现存的几种方法，我都试过。", "target_word": "现存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現存", "label": "繁体"}], "register": "书面", "sense_fingerprint": "目前仍然存在的（问题、办法、物种、规定等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96604, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现存", "is_correct": true, "explanation": "目标词，xiàn cún，意思是目前仍然存在的。"}, {"text": "显存", "is_correct": false, "explanation": "显存（xiǎn cún）与现存（xiàn cún）声调不同，第三声与第四声，意思是显卡上的存储器。"}, {"text": "先存", "is_correct": false, "explanation": "先存（xiān cún）与现存（xiàn cún）声调不同，第一声与第四声，意思是事先存放。"}, {"text": "现成", "is_correct": false, "explanation": "现成（xiàn chéng）与现存（xiàn cún）读音相近，声母 ch 与 c、韵母 eng 与 un 不同，意思是已经准备好的。"}], "explanations": {"现存": "目标词，xiàn cún，意思是目前仍然存在的。", "显存": "显存（xiǎn cún）与现存（xiàn cún）声调不同，第三声与第四声，意思是显卡上的存储器。", "先存": "先存（xiān cún）与现存（xiàn cún）声调不同，第一声与第四声，意思是事先存放。", "现成": "现成（xiàn chéng）与现存（xiàn cún）读音相近，声母 ch 与 c、韵母 eng 与 un 不同，意思是已经准备好的。"}, "sentence_index": null, "correct_answer": "现存"}, "level_3": {"options": [{"text": "现存", "is_correct": true, "explanation": "「现存」修饰「问题」，指目前仍然存在的问题，符合句意。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：「美丽」形容外貌或景色，不用来修饰问题。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：「明亮」形容光线或颜色，不能修饰问题。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容人或物的体形，不用来修饰问题。"}], "explanations": {"现存": "「现存」修饰「问题」，指目前仍然存在的问题，符合句意。", "美丽": "搭配：「美丽」形容外貌或景色，不用来修饰问题。", "明亮": "搭配：「明亮」形容光线或颜色，不能修饰问题。", "高大": "体貌：「高大」形容人或物的体形，不用来修饰问题。"}, "sentence_index": 0, "correct_answer": "现存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那棵现存的老树去年已经死了。", "explanation": "这里应该用〈原来的〉。「现存」指目前仍然存在，已经死了的树不能说「现存」。"}, {"text": "学校现存学生两千多人。", "explanation": "这里应该用〈现有〉。「现有」用于人员和数量，「现存」指目前仍然存在的问题、办法等。"}, {"text": "地震后现存的人都很坚强。", "explanation": "这里应该用〈幸存〉。「幸存」指灾难后活下来的人，「现存」不用于指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现存", "is_correct": true, "explanation": "「现存」修饰「做法」，指现在仍在用的做法，符合句意。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：「鲜艳」形容颜色，不用来修饰做法。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外貌，不用来形容做法。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：「温柔」形容性格或态度，不用来修饰做法。"}], "explanations": {"现存": "「现存」修饰「做法」，指现在仍在用的做法，符合句意。", "鲜艳": "搭配：「鲜艳」形容颜色，不用来修饰做法。", "漂亮": "搭配：「漂亮」形容外貌，不用来形容做法。", "温柔": "搭配：「温柔」形容性格或态度，不用来修饰做法。"}, "sentence_index": 6, "correct_answer": "现存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下个月现存的新产品将会上市。", "explanation": "这里应该用〈将来的〉。「现存」指目前仍然存在，还没出现的东西不能用「现存」。"}, {"text": "现存的时间是下午三点。", "explanation": "这里应该用〈现在〉。「现存」修饰已经存在的事物，不能用来指时间，说时间要用「现在的时间」。"}, {"text": "现存的那家老店去年已经关门了。", "explanation": "这里应该用〈原来的〉。「现存」指目前仍然存在，已经关门的店不能说「现存」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要先找出现存地漏洞。", "corrected_sentence": "我们要先找出现存的漏洞。", "error_description": "「现存」修饰名词时要用「的」，不能用「地」（「地」用于修饰动词）。错误形式是「现存地漏洞」，正确形式是「现存的漏洞」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
