INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "妈妈把宝宝带到这个世界上来。", "primary_collocate": null, "pronunciation": "shēng xià", "ipa": "ʂɤŋ˥ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈十年前生下了我。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶一共生下了四个孩子。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在家里生下了一个胖娃娃。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈生下我的时候才二十岁。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位妈妈生下了一对可爱的双胞胎。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐昨天生下了一个小宝宝。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她生下宝宝以后就不工作了。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说她生下我那天下着大雨。", "target_word": "生下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚生下孩子，每天都很累。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她生下女儿以后，一个人把孩子带大。", "target_word": "生下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生下了", "label": "体标"}, {"form": "生下过", "label": "体标"}, {"form": "生下来", "label": "复合"}], "register": "口语", "sense_fingerprint": "妈妈生下孩子，使其来到世上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生下", "is_correct": true, "explanation": "生下：妈妈生育孩子，使其来到世上，即本词。"}, {"text": "剩下", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是余留、剩余。"}, {"text": "省下", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省后留下。"}, {"text": "身下", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是身体的下面。"}], "explanations": {"生下": "生下：妈妈生育孩子，使其来到世上，即本词。", "剩下": "shèng（第四声）与 shēng（第一声）声调不同，意思是余留、剩余。", "省下": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省后留下。", "身下": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是身体的下面。"}, "sentence_index": null, "correct_answer": "生下"}, "level_3": {"options": [{"text": "生下", "is_correct": true, "explanation": "正确：生下，妈妈生育孩子，与“妈妈”“我”的语境相合。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是物件，不能说“修了我”。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写了我”。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是购买，妈妈不会买人，与句子语境冲突。"}], "explanations": {"生下": "正确：生下，妈妈生育孩子，与“妈妈”“我”的语境相合。", "修": "搭配：“修”的对象是物件，不能说“修了我”。", "写": "搭配：“写”的对象是文字，不能说“写了我”。", "买": "语义：“买”是购买，妈妈不会买人，与句子语境冲突。"}, "sentence_index": 0, "correct_answer": "生下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司每年生下很多利润。", "explanation": "这里应该用〈赚取〉。生下只用于生育后代，利润要用赚取。"}, {"text": "她在花园里生下一朵红花。", "explanation": "这里应该用〈开出〉。生下只用于生育后代，花朵要用开出。"}, {"text": "建筑师生下了一座新房子。", "explanation": "这里应该用〈设计〉。生下指生育，房屋要用设计或建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生下", "is_correct": true, "explanation": "正确：生下，指分娩宝宝，与“宝宝”“不工作”的语境相合。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是出售，与“宝宝”和“不工作”的语境不合。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是书籍或文字，不能说“读宝宝”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是果实或花朵，不能用于宝宝。"}], "explanations": {"生下": "正确：生下，指分娩宝宝，与“宝宝”“不工作”的语境相合。", "卖": "语义：“卖”是出售，与“宝宝”和“不工作”的语境不合。", "读": "搭配：“读”的对象是书籍或文字，不能说“读宝宝”。", "摘": "搭配：“摘”的对象是果实或花朵，不能用于宝宝。"}, "sentence_index": 6, "correct_answer": "生下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生生下了电灯。", "explanation": "这里应该用〈发明〉。生下指生育，电灯要用发明。"}, {"text": "工人们生下了一座大桥。", "explanation": "这里应该用〈修建〉。生下只用于生育后代，桥梁要用修建。"}, {"text": "他生下了这项任务。", "explanation": "这里应该用〈完成〉。生下指生育，任务要用完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个女人去年冬天生下过了一个儿子。", "corrected_sentence": "那个女人去年冬天生下了一个儿子。", "error_description": "体标错误：“过”表示经历，不能与“了”同用，应去掉“过”，说“生下了一个儿子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上个月生下着一个儿子。", "corrected_sentence": "她上个月生下了一个儿子。", "error_description": "体标错误：“生下”是一次性完成的动作，不能用“着”表示持续，应把“着”改为“了”，说“生下了一个儿子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
