INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分娩；产出（婴儿或幼崽）。", "primary_collocate": null, "pronunciation": "shēng xià", "ipa": "ʂɤŋ˥ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "母猫昨晚生下了五只小猫。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在医院生下了一个男孩。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母狗生下三只小狗，都很健康。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头母牛今天早上生下了一只小牛。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说她明天就会生下孩子。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她生下孩子以后，一直在家休息。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只大熊猫去年生下了一对双胞胎。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的妻子昨天在医院生下了一个女儿。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母羊在雪天里生下了两只小羊。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她三十岁时生下了第一个孩子。", "target_word": "生下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生下了", "label": "体标"}, {"form": "生下过", "label": "体标"}, {"form": "生下来", "label": "复合"}], "register": "口语", "sense_fingerprint": "分娩产下婴儿或动物幼崽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v