tion_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生下", "is_correct": true, "explanation": "正确：生下，指大熊猫分娩双胞胎，与“去年”的语境相合。"}, {"text": "卖", "is_correct": false, "explanation": "语义：大熊猫不会卖东西，“卖”与生育的语境不合。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写了一对双胞胎”。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是物件，不能说“修了一对双胞胎”。"}], "explanations": {"生下": "正确：生下，指大熊猫分娩双胞胎，与“去年”的语境相合。", "卖": "语义：大熊猫不会卖东西，“卖”与生育的语境不合。", "写": "搭配：“写”的对象是文字，不能说“写了一对双胞胎”。", "修": "搭配：“修”的对象是物件，不能说“修了一对双胞胎”。"}, "sentence_index": 6, "correct_answer": "生下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个实验终于生下了新的结果。", "explanation": "这里应该用〈得出〉。生下只用于生育后代，实验结论要用得出。"}, {"text": "老板让他生下一个新方案。", "explanation": "这里应该用〈制定〉。生下指生育，方案要用制定。"}, {"text": "这位画家生下了一幅名画。", "explanation": "这里应该用〈创作〉。生下只用于生育后代，画作要用创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
