INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96613, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给钱，借别人的东西或房子来用一段时间。", "primary_collocate": null, "pronunciation": "zū", "ipa": "tsu˥", "syllable_count": 1, "sentences": [{"text": "我没有钱买房子，所以先租一套小房子。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学校旁边租了一间房。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租一辆车去海边玩。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子一个月租多少钱？", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们跟房东说想租三年。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚来北京，先租了一个小房间住。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前租过两年房子。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我们租了船，在湖上玩了一下午。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我们租了一间大办公室。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和朋友一起租了一套房子。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "租了", "label": "体标（了）"}, {"form": "租过", "label": "体标（过）"}, {"form": "租着", "label": "体标（着）"}, {"form": "出租", "label": "复合词"}, {"form": "租金", "label": "复合词"}], "register": "中性", "sense_fingerprint": "付钱向别人借用房子或东西一段时间（承租）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafe1b09-91b9-4c69-99c2-755cd2b95889') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96613, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "租", "is_correct": true, "explanation": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。"}, {"text": "足", "is_correct": false, "explanation": "足（zú，第二声）与 zū（第一声）声调不同，意思是脚。"}, {"text": "猪", "is_correct": false, "explanation": "猪（zhū）与 zū 声母不同（zh 与 z），意思是猪。"}, {"text": "粗", "is_correct": false, "explanation": "粗（cū）与 zū 声母不同（c 与 z），意思是粗细、粗糙。"}, {"text": "组", "is_correct": false, "explanation": "组（zǔ，第三声）与 zū（第一声）声调不同，意思是组合、小组。"}], "explanations": {"租": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。", "足": "足（zú，第二声）与 zū（第一声）声调不同，意思是脚。", "猪": "猪（zhū）与 zū 声母不同（zh 与 z），意思是猪。", "粗": "粗（cū）与 zū 声母不同（c 与 z），意思是粗细、粗糙。", "组": "组（zǔ，第三声）与 zū（第一声）声调不同，意思是组合、小组。"}, "sentence_index": null, "correct_answer": "租"}, "level_3": {"options": [{"text": "租", "is_correct": true, "explanation": "租：付钱暂时使用房子，与“没有钱买房子，所以先租一套小房子”的语境相符。"}, {"text": "买", "is_correct": false, "explanation": "语义：前句说没有钱买房子，“买”会与之矛盾。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修需要花钱，与“没有钱”的前提矛盾。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”指移动东西，不能说“搬一套小房子”。"}], "explanations": {"租": "租：付钱暂时使用房子，与“没有钱买房子，所以先租一套小房子”的语境相符。", "买": "语义：前句说没有钱买房子，“买”会与之矛盾。", "装修": "语义：装修需要花钱，与“没有钱”的前提矛盾。", "搬": "搭配：“搬”指移动东西，不能说“搬一套小房子”。"}, "sentence_index": 0, "correct_answer": "租"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从图书馆租了一本书。", "explanation": "这里应该用〈借〉。图书馆是免费外借，不用付钱，不说“租”。"}, {"text": "我们租了一个司机送我们去机场。", "explanation": "这里应该用〈雇〉。租用于物品或房屋，雇用于人。"}, {"text": "我向银行租了一笔钱。", "explanation": "这里应该用〈贷〉。租用于物品或房屋，向银行借钱要说“贷”，不说“租”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96613, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "租", "is_correct": true, "explanation": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。"}, {"text": "祖", "is_correct": false, "explanation": "祖（zǔ，第三声）与 zū（第一声）声调不同，意思是祖先。"}, {"text": "出", "is_correct": false, "explanation": "出（chū）与 zū 声母不同（ch 与 z），意思是出去。"}, {"text": "族", "is_correct": false, "explanation": "族（zú，第二声）与 zū（第一声）声调不同，意思是家族、民族。"}, {"text": "初", "is_correct": false, "explanation": "初（chū）与 zū 声母不同（ch 与 z），意思是开始、最初。"}], "explanations": {"租": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。", "祖": "祖（zǔ，第三声）与 zū（第一声）声调不同，意思是祖先。", "出": "出（chū）与 zū 声母不同（ch 与 z），意思是出去。", "族": "族（zú，第二声）与 zū（第一声）声调不同，意思是家族、民族。", "初": "初（chū）与 zū 声母不同（ch 与 z），意思是开始、最初。"}, "sentence_index": null, "correct_answer": "租"}, "level_3": {"options": [{"text": "租", "is_correct": true, "explanation": "租：付钱暂时使用房子，与“以前……两年”的使用时段相符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是把东西赠给别人，与“自己使用两年”不符。"}, {"text": "进", "is_correct": false, "explanation": "配价：“进”不能直接带“房子”表示持续使用两年。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“使用过两年”的意思不合。"}], "explanations": {"租": "租：付钱暂时使用房子，与“以前……两年”的使用时段相符。", "送": "语义：“送”是把东西赠给别人，与“自己使用两年”不符。", "进": "配价：“进”不能直接带“房子”表示持续使用两年。", "扔": "语义：“扔”是丢弃，与“使用过两年”的意思不合。"}, "sentence_index": 6, "correct_answer": "租"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我租了一次理发。", "explanation": "这里应该用〈做〉。理发是服务，不是物品或房屋，不能用“租”。"}, {"text": "他租了一顿晚饭请大家吃。", "explanation": "这里应该用〈买〉。饭吃完就没有了，不能归还，“租”只用于可以归还的物品或场所。"}, {"text": "他租了一个好名声。", "explanation": "这里应该用〈获得〉。名声是抽象的，不能像房屋那样暂时使用后归还，“租”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我想租了一辆自行车去公园。", "corrected_sentence": "周末我想租一辆自行车去公园。", "error_description": "错误：“想租了一辆自行车”。正确：“想租一辆自行车”。“想”表示意愿，尚未实现，与表示完成的“了”矛盾，不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于租了到一间房子。", "corrected_sentence": "他终于租到了一间房子。", "error_description": "错误：“租了到”。正确：“租到了”。“到”是结果补语，要紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
