INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付费暂时使用他人的物品或房屋。", "primary_collocate": null, "pronunciation": "zū", "ipa": "tsu˥", "syllable_count": 1, "sentences": [{"text": "我想在公司附近租房子。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们租了一个大教室开会。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租过一台相机，用了三天就还了。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去山上玩，我们租了两辆自行车。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是我租的，明天要还。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想买婚纱，只租一天。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我租的房子离地铁站很近。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租着一间小屋，住了三年。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房子比买房子便宜。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上租了一套西装参加婚礼。", "target_word": "租", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "租了", "label": "体标（了）"}, {"form": "租过", "label": "体标（过）"}, {"form": "租着", "label": "体标（着）"}, {"form": "出租", "label": "复合词"}, {"form": "租金", "label": "复合词"}], "register": "中性", "sense_fingerprint": "付费暂时使用别人的物品或房屋（承租）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafe1b09-91b9-4c69-99c2-755cd2b95889') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUD