INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "租", "is_correct": true, "explanation": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。"}, {"text": "足", "is_correct": false, "explanation": "足（zú，第二声）与 zū（第一声）声调不同，意思是脚。"}, {"text": "猪", "is_correct": false, "explanation": "猪（zhū）与 zū 声母不同（zh 与 z），意思是猪。"}, {"text": "初", "is_correct": false, "explanation": "初（chū）与 zū 声母不同（ch 与 z），意思是开始、最初。"}, {"text": "组", "is_correct": false, "explanation": "组（zǔ，第三声）与 zū（第一声）声调不同，意思是组合、小组。"}], "explanations": {"租": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。", "足": "足（zú，第二声）与 zū（第一声）声调不同，意思是脚。", "猪": "猪（zhū）与 zū 声母不同（zh 与 z），意思是猪。", "初": "初（chū）与 zū 声母不同（ch 与 z），意思是开始、最初。", "组": "组（zǔ，第三声）与 zū（第一声）声调不同，意思是组合、小组。"}, "sentence_index": null, "correct_answer": "租"}, "level_3": {"options": [{"text": "租", "is_correct": true, "explanation": "租：付钱暂时使用房子，与“想在公司附近”要使用房子的意思相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”指移动物品，不能与“房子”搭配表示使用。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“想在公司附近”的意思不合。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是赠给别人，与“想在公司附近使用房子”的意思不合。"}], "explanations": {"租": "租：付钱暂时使用房子，与“想在公司附近”要使用房子的意思相符。", "搬": "搭配：“搬”指移动物品，不能与“房子”搭配表示使用。", "扔": "语义：“扔”是丢弃，与“想在公司附近”的意思不合。", "送": "语义：“送”是赠给别人，与“想在公司附近使用房子”的意思不合。"}, "sentence_index": 0, "correct_answer": "租"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈从邻居那里租了一把伞，不用给钱。", "explanation": "这里应该用〈借〉。租用要付钱，这里说不用给钱，应说“借”。"}, {"text": "我给女儿租了一个书包，当作生日礼物送她。", "explanation": "这里应该用〈买〉。送作礼物要归她所有，不是暂时使用，应说“买”。"}, {"text": "我们租了三个工人搬家。", "explanation": "这里应该用〈雇〉。租用于物品或房屋，雇用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "租", "is_correct": true, "explanation": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。"}, {"text": "祖", "is_correct": false, "explanation": "祖（zǔ，第三声）与 zū（第一声）声调不同，意思是祖先。"}, {"text": "族", "is_correct": false, "explanation": "族（zú，第二声）与 zū（第一声）声调不同，意思是家族、民族。"}, {"text": "出", "is_correct": false, "explanation": "出（chū）与 zū 声母不同（ch 与 z），意思是出去。"}, {"text": "粗", "is_correct": false, "explanation": "粗（cū）与 zū 声母不同（c 与 z），意思是粗细、粗糙。"}], "explanations": {"租": "租（zū，第一声）：付钱暂时使用他人的房屋或物品。", "祖": "祖（zǔ，第三声）与 zū（第一声）声调不同，意思是祖先。", "族": "族（zú，第二声）与 zū（第一声）声调不同，意思是家族、民族。", "出": "出（chū）与 zū 声母不同（ch 与 z），意思是出去。", "粗": "粗（cū）与 zū 声母不同（c 与 z），意思是粗细、粗糙。"}, "sentence_index": null, "correct_answer": "租"}, "level_3": {"options": [{"text": "租", "is_correct": true, "explanation": "租：付钱暂时使用房子，与“离地铁站很近”的房子是暂时使用的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是房子，“吃的房子”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“房子”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声，与房子无关。"}], "explanations": {"租": "租：付钱暂时使用房子，与“离地铁站很近”的房子是暂时使用的语境相符。", "吃": "搭配：“吃”的对象不能是房子，“吃的房子”说不通。", "喝": "搭配：“喝”不能与“房子”搭配。", "唱": "语义：“唱”是发声，与房子无关。"}, "sentence_index": 6, "correct_answer": "租"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我租了一次体检。", "explanation": "这里应该用〈做〉。体检是服务，不是物品或房屋，不能用“租”。"}, {"text": "我租了一瓶水给你喝。", "explanation": "这里应该用〈拿〉。水喝完就没有了，不能归还，“租”只用于可以归还的物品或场所。"}, {"text": "他租了一份好心情去上班。", "explanation": "这里应该用〈保持〉。心情是抽象的，不能像房屋那样暂时使用后归还，“租”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我要租了一辆车去机场。", "corrected_sentence": "明天我要租一辆车去机场。", "error_description": "错误：“要租了一辆车”。正确：“要租一辆车”。“明天”“要”表示还没发生的事，不能用表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于租了到一套好房子。", "corrected_sentence": "我们终于租到了一套好房子。", "error_description": "错误：“租了到”。正确：“租到了”。“到”是结果补语，要紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
