INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96617, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "所有的加在一起。", "primary_collocate": null, "pronunciation": "zǒng gòng", "ipa": "tsʊŋ˨˩ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们班总共有三十个学生。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书总共二百页。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我总共花了五十块钱。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家总共有五口人。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行总共用了三天时间。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上总共放着八个苹果。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我们总共来了十二个人。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买书总共付了八十元。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三个月我们总共看了八部电影。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校总共有五百名学生。", "target_word": "总共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，把所有数量加在一起，说明全部的总数，常放在数量词或动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候、不常发生，与班级人数这种固定的数量状态不符，不能说“我们班偶尔有三十个学生”。"}, {"text": "总共", "is_correct": true, "explanation": "“总共”表示所有人数加在一起的全部数量，与“三十个学生”这一合计数字相符。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是文言副词，与这句口语化的叙述不协调。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能说班级里的学生人数是突然出现的。"}], "explanations": {"偶尔": "语义：“偶尔”表示有时候、不常发生，与班级人数这种固定的数量状态不符，不能说“我们班偶尔有三十个学生”。", "总共": "“总共”表示所有人数加在一起的全部数量，与“三十个学生”这一合计数字相符。", "乃": "语域：“乃”是文言副词，与这句口语化的叙述不协调。", "忽然": "语义：“忽然”表示突然发生，不能说班级里的学生人数是突然出现的。"}, "sentence_index": 0, "correct_answer": "总共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总共考上了大学。", "explanation": "这里应该用〈总算〉。总共表示数量的合计，不能表示经过努力后终于达成某件事。"}, {"text": "他总共五点起床。", "explanation": "这里应该用〈总是〉。总共强调数量的合计，不表示每次都如此、经常如此。"}, {"text": "天气总共冷了起来。", "explanation": "这里应该用〈渐渐〉。总共表示数量的合计，不表示天气逐步发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙地去做某事，不能说大家“连忙来了十二个人”，与人数的统计意思不符。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期以来一直如此，与“今天”这个具体的时间矛盾。"}, {"text": "总共", "is_correct": true, "explanation": "“总共”表示今天来的所有人数加在一起，与“十二个人”这一合计数字相符。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言副词，与这句口语化的叙述不协调。"}], "explanations": {"连忙": "语义：“连忙”表示急忙地去做某事，不能说大家“连忙来了十二个人”，与人数的统计意思不符。", "一向": "语义：“一向”表示长期以来一直如此，与“今天”这个具体的时间矛盾。", "总共": "“总共”表示今天来的所有人数加在一起，与“十二个人”这一合计数字相符。", "遂": "语域：“遂”是文言副词，与这句口语化的叙述不协调。"}, "sentence_index": 6, "correct_answer": "总共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总共给我写信。", "explanation": "这里应该用〈一直〉。总共表示数量的合计，句中没有可以合计的数量，不能表示持续不断地做某事。"}, {"text": "我总共去图书馆。", "explanation": "这里应该用〈偶尔〉。总共表示合计，不表示偶然、不常发生的动作。"}, {"text": "孩子总共哭了起来。", "explanation": "这里应该用〈突然〉。总共表示数量的合计，不表示事情忽然发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书架上总共的有十本书。", "corrected_sentence": "书架上总共有十本书。", "error_description": "错误：“总共”是副词，后面不能直接加“的”，多写了“的”。正确：应删去“的”，说“书架上总共有十本书”。“总共”表示数量的合计，只需修改这一处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班总共地有十门课。", "corrected_sentence": "这个班总共有十门课。", "error_description": "错误：“总共”是副词，直接放在动词“有”前面做状语，后面不能加“地”，句中多写了“地”。正确：删去“地”，说“这个班总共有十门课”。只需修改这一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
