INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96621, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有些人用这个词来说老人，是不太客气的话。", "primary_collocate": null, "pronunciation": "lǎo dōng xi", "ipa": "lau˨˩˦ tʊŋ˥ ɕi", "syllable_count": 3, "sentences": [{"text": "那个老东西总是骂我们小孩。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别叫爷爷老东西，这样很没礼貌。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地说：“你这个老东西！”", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老东西一天到晚坐在门口看人。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居都说隔壁的老东西脾气很坏。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她骂那个老东西偷了她的钱。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你才是老东西，我还年轻呢！", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不该当面叫老人老东西。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老东西又来问我要房租了。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上骂爸爸是老东西，心里却很担心。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老東西", "label": "繁体"}], "register": "口语", "sense_fingerprint": "不客气地称呼老人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96621, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老东西", "is_correct": true, "explanation": "lǎo dōng xi，指带轻视意味地称呼老人。"}, {"text": "好东西", "is_correct": false, "explanation": "lǎo 与 hǎo 只差声母（l/h），hǎo dōng xi 意思是“好东西”，不是“老东西”。"}, {"text": "找东西", "is_correct": false, "explanation": "zhǎo 与 lǎo 只差声母（zh/l），意思是“寻找东西”，不是“老东西”。"}, {"text": "讨东西", "is_correct": false, "explanation": "tǎo 与 lǎo 只差声母（t/l），意思是“向人要东西”，不是“老东西”。"}], "explanations": {"老东西": "lǎo dōng xi，指带轻视意味地称呼老人。", "好东西": "lǎo 与 hǎo 只差声母（l/h），hǎo dōng xi 意思是“好东西”，不是“老东西”。", "找东西": "zhǎo 与 lǎo 只差声母（zh/l），意思是“寻找东西”，不是“老东西”。", "讨东西": "tǎo 与 lǎo 只差声母（t/l），意思是“向人要东西”，不是“老东西”。"}, "sentence_index": null, "correct_answer": "老东西"}, "level_3": {"options": [{"text": "老东西", "is_correct": true, "explanation": "“那个老东西总是骂我们小孩”中，老东西指不太客气地称呼老人，语境吻合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会骂人，与“骂我们小孩”的主语不符。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不会骂人，与句子的语境冲突。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会骂人，与“骂我们小孩”的主语不符。"}], "explanations": {"老东西": "“那个老东西总是骂我们小孩”中，老东西指不太客气地称呼老人，语境吻合。", "冰箱": "语义：冰箱不会骂人，与“骂我们小孩”的主语不符。", "大树": "语义：大树不会骂人，与句子的语境冲突。", "书包": "语义：书包不会骂人，与“骂我们小孩”的主语不符。"}, "sentence_index": 0, "correct_answer": "老东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老东西是刚出生的婴儿，可爱极了。", "explanation": "这里应该用〈宝宝〉。老东西指老人，带轻视意味，不能用于刚出生的婴儿。"}, {"text": "那个老东西刚上小学，每天背着大书包。", "explanation": "这里应该用〈小朋友〉。老东西指老人，带轻视意味，不能用来称呼刚上小学的孩子。"}, {"text": "这个老东西很受欢迎，很多人都喜欢他。", "explanation": "这里应该用〈名人〉。老东西带轻视意味，不能用来称赞受欢迎的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老东西", "is_correct": true, "explanation": "“你才是老东西，我还年轻呢”中，老东西指老人，与“我还年轻”形成对比。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩与“我还年轻”的对比不成立，小孩不是指老人。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿年纪太小，不是指老人，不能与“我还年轻”形成对比。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不是人，无法与“我还年轻”构成对比。"}], "explanations": {"老东西": "“你才是老东西，我还年轻呢”中，老东西指老人，与“我还年轻”形成对比。", "小孩": "语义：小孩与“我还年轻”的对比不成立，小孩不是指老人。", "婴儿": "语义：婴儿年纪太小，不是指老人，不能与“我还年轻”形成对比。", "花瓶": "语义：花瓶不是人，无法与“我还年轻”构成对比。"}, "sentence_index": 6, "correct_answer": "老东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台新电脑是个老东西，我好喜欢它。", "explanation": "这里应该用〈宝贝〉。老东西带轻视意味，不能用来表达喜爱；用〈宝贝〉才符合“我好喜欢它”。"}, {"text": "这位老东西是我最尊敬的长辈，我每周都去看望他。", "explanation": "这里应该用〈前辈〉。老东西带轻视意味，不能用来表示尊敬。"}, {"text": "我的老师是个老东西，每天都教我很多知识。", "explanation": "这里应该用〈恩师〉。老东西带轻视意味，不能用来尊敬地称呼老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本老东西每天都在门口晒太阳。", "corrected_sentence": "那个老东西每天都在门口晒太阳。", "error_description": "量词错误：指人的“老东西”应用“个”，“本”用于书籍，不能用来称呼人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都说那个很烦人老东西。", "corrected_sentence": "他每天都说那个很烦人的老东西。", "error_description": "结构错误：修饰语“很烦人”与“老东西”之间应加“的”，说“那个很烦人的老东西”，不能说“那个很烦人老东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
