INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对旧物（旧机器、旧器具等）的轻视称呼，带有贬义。", "primary_collocate": null, "pronunciation": "lǎo dōng xi", "ipa": "lau˨˩˦ tʊŋ˥ ɕi", "syllable_count": 3, "sentences": [{"text": "这个老东西又坏了，该换新的了。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那台老东西慢得很，我早就想扔了。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边拍着旧收音机，一边说“老东西”。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台老东西又卡住了，真烦人。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老东西占地方，快送人吧。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那台老东西堆在墙角，谁也不用。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的车是个老东西，常常半路停下。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阁楼里放着一堆没人要的老东西。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个老东西，怎么又漏水了？", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我的旧手机是个老东西，该换了。", "target_word": "老东西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老東西", "label": "繁体"}], "register": "口语", "sense_fingerprint": "轻视地称呼旧机器或旧器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老东西", "is_correct": true, "explanation": "lǎo dōng xi，指旧的机器或物件，带轻视意味。"}, {"text": "好东西", "is_correct": false, "explanation": "lǎo 与 hǎo 只差声母（l/h），hǎo dōng xi 意思是“好东西”，不是“老东西”。"}, {"text": "找东西", "is_correct": false, "explanation": "zhǎo 与 lǎo 只差声母（zh/l），意思是“寻找东西”，不是“老东西”。"}, {"text": "讨东西", "is_correct": false, "explanation": "tǎo 与 lǎo 只差声母（t/l），意思是“向人要东西”，不是“老东西”。"}], "explanations": {"老东西": "lǎo dōng xi，指旧的机器或物件，带轻视意味。", "好东西": "lǎo 与 hǎo 只差声母（l/h），hǎo dōng xi 意思是“好东西”，不是“老东西”。", "找东西": "zhǎo 与 lǎo 只差声母（zh/l），意思是“寻找东西”，不是“老东西”。", "讨东西": "tǎo 与 lǎo 只差声母（t/l），意思是“向人要东西”，不是“老东西”。"}, "sentence_index": null, "correct_answer": "老东西"}, "level_3": {"options": [{"text": "老东西", "is_correct": true, "explanation": "“这个老东西又坏了，该换新的了”中，老东西指旧的物件，语境吻合。"}, {"text": "老人", "is_correct": false, "explanation": "语义：人不会“坏了”，也不需要“换新的”，与句子不符。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不会“坏了”要换新的，与句子语境冲突。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不会坏，也不需要换新，与句子语境冲突。"}], "explanations": {"老东西": "“这个老东西又坏了，该换新的了”中，老东西指旧的物件，语境吻合。", "老人": "语义：人不会“坏了”，也不需要“换新的”，与句子不符。", "小孩": "语义：小孩不会“坏了”要换新的，与句子语境冲突。", "蔬菜": "语义：蔬菜不会坏，也不需要换新，与句子语境冲突。"}, "sentence_index": 0, "correct_answer": "老东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个老东西是刚从店里买回来的，还没用过，很崭新。", "explanation": "这里应该用〈新机器〉。老东西指旧物，带轻视意味，不能用来形容刚买回来的崭新东西。"}, {"text": "这个老东西是我们的校长，大家都很尊敬他。", "explanation": "这里应该用〈领导〉。老东西带轻视意味，不能用来尊敬地称呼校长。"}, {"text": "这台老东西真珍贵，我很爱惜它。", "explanation": "这里应该用〈文物〉或〈宝贝〉。老东西带轻视意味，不能用来称赞珍贵的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老东西", "is_correct": true, "explanation": "“我的车是个老东西，常常半路停下”中，老东西指旧车，语境吻合。"}, {"text": "猫", "is_correct": false, "explanation": "语义：车不是猫，不能说“我的车是个猫”。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：车不是老鼠，与“常常半路停下”的语境不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是车，与“常常半路停下”的语境不符。"}], "explanations": {"老东西": "“我的车是个老东西，常常半路停下”中，老东西指旧车，语境吻合。", "猫": "语义：车不是猫，不能说“我的车是个猫”。", "老鼠": "语义：车不是老鼠，与“常常半路停下”的语境不符。", "书包": "语义：书包不是车，与“常常半路停下”的语境不符。"}, "sentence_index": 6, "correct_answer": "老东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆老东西是我们新买的汽车，开起来很稳。", "explanation": "这里应该用〈新车〉。老东西指旧物，带轻视意味，不能用来形容新买的车。"}, {"text": "这部手机是今天刚出的老东西，大家都抢着买。", "explanation": "这里应该用〈新产品〉。老东西指旧物，带轻视意味，不能用来说刚上市的新手机。"}, {"text": "这件老东西价值连城，是爷爷的宝贝。", "explanation": "这里应该用〈古董〉。老东西带轻视意味，不能用来形容价值连城的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本老东西又坏了，我们得换一台。", "corrected_sentence": "那台老东西又坏了，我们得换一台。", "error_description": "量词错误：机器应用“台”，“本”用于书籍，不能用于机器，应说“那台老东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台破旧老东西今天又不转了。", "corrected_sentence": "这台破旧的老东西今天又不转了。", "error_description": "结构错误：修饰语“破旧”与“老东西”之间应加“的”，说“破旧的老东西”，不能说“破旧老东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赚", "is_correct": true, "explanation": "赚：获得利润，与“亏”相对，是反义词。"}, {"text": "花", "is_correct": false, "explanation": "花：花费钱财，与“亏”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读：阅读或朗读，与“亏”的赔钱义没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑：快速移动，与“亏”的赔钱义没有反义关系。"}], "correct_answer": "赚", "explanations": {"赚": "赚：获得利润，与“亏”相对，是反义词。", "花": "花：花费钱财，与“亏”没有反义关系。", "读": "读：阅读或朗读，与“亏”的赔钱义没有反义关系。", "跑": "跑：快速移动，与“亏”的赔钱义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赚", "is_correct": true, "explanation": "赚：获得利润，与“亏”相对，是反义词。"}, {"text": "跳", "is_correct": false, "explanation": "跳：身体向上或向前运动，与“亏”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：发出歌声，与“亏”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗：用水清除污垢，与“亏”没有反义关系。"}], "correct_answer": "赚", "explanations": {"赚": "赚：获得利润，与“亏”相对，是反义词。", "跳": "跳：身体向上或向前运动，与“亏”没有反义关系。", "唱": "唱：发出歌声，与“亏”没有反义关系。", "洗": "洗：用水清除污垢，与“亏”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "本来要赚钱，结果钱反而少了。", "primary_collocate": null, "pronunciation": "kuī", "ipa": "kʰueɪ˥", "syllable_count": 1, "sentences": [{"text": "这个月小店亏了两万块。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他炒股亏了很多钱。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店生意不好，每个月都在亏。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们卖得太便宜，一件衣服要亏十块。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做生意亏了，只好回家种地。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司去年亏了，今年没发奖金。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买这只股票，我亏了一半的钱。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开饭馆亏过一次，再也不敢了。", "target_word": "亏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔生意不会亏，你放心做吧。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "卖这么便宜，老板一定亏了。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "亏了", "label": "体标"}, {"form": "亏过", "label": "体标"}, {"form": "亏损", "label": "复合"}, {"form": "亏本", "label": "复合"}], "register": "口语", "sense_fingerprint": "做生意或投资没赚到钱反而赔钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亏", "is_correct": true, "explanation": "亏：本来要赚钱，结果钱反而少了，即本词。"}, {"text": "归", "is_correct": false, "explanation": "guī 与 kuī 声母不同（送气与否），意思是回、还。"}, {"text": "灰", "is_correct": false, "explanation": "huī 与 kuī 声母不同（h 与 k），意思是灰烬或灰色。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 kuī 声调不同（第四声与第一声），意思是惭愧。"}, {"text": "葵", "is_correct": false, "explanation": "kuí 与 kuī 声调不同（第二声与第一声），意思是向日葵一类的植物。"}], "explanations": {"亏": "亏：本来要赚钱，结果钱反而少了，即本词。", "归": "guī 与 kuī 声母不同（送气与否），意思是回、还。", "灰": "huī 与 kuī 声母不同（h 与 k），意思是灰烬或灰色。", "愧": "kuì 与 kuī 声调不同（第四声与第一声），意思是惭愧。", "葵": "kuí 与 kuī 声调不同（第二声与第一声），意思是向日葵一类的植物。"}, "sentence_index": null, "correct_answer": "亏"}, "level_3": {"options": [{"text": "亏", "is_correct": true, "explanation": "正确：亏，指做生意赔钱，与“小店”“两万块”的语境相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只搭配液体，不能说“喝了两万块”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱了两万块”。"}, {"text": "贪", "is_correct": false, "explanation": "语义：“贪”指贪心，小店不能贪，与句子语境不合。"}], "explanations": {"亏": "正确：亏，指做生意赔钱，与“小店”“两万块”的语境相合。", "喝": "搭配：“喝”只搭配液体，不能说“喝了两万块”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱了两万块”。", "贪": "语义：“贪”指贪心，小店不能贪，与句子语境不合。"}, "sentence_index": 0, "correct_answer": "亏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中亏了三局。", "explanation": "这里应该用〈输〉。亏指做生意或投资赔钱，比赛的胜负要用输。"}, {"text": "他在地震中亏了父母。", "explanation": "这里应该用〈失去〉。亏指钱财或生意上的损失，失去亲人要用失去。"}, {"text": "妈妈每个月亏了两千块买菜。", "explanation": "这里应该用〈花〉。亏指生意或投资赔钱，主动花钱要用花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亏", "is_correct": true, "explanation": "亏：本来要赚钱，结果钱反而少了，即本词。"}, {"text": "规", "is_correct": false, "explanation": "guī 与 kuī 声母不同（送气与否），意思是规矩、规划。"}, {"text": "挥", "is_correct": false, "explanation": "huī 与 kuī 声母不同（h 与 k），意思是挥动。"}, {"text": "溃", "is_correct": false, "explanation": "kuì 与 kuī 声调不同（第四声与第一声），意思是溃散、溃败。"}], "explanations": {"亏": "亏：本来要赚钱，结果钱反而少了，即本词。", "规": "guī 与 kuī 声母不同（送气与否），意思是规矩、规划。", "挥": "huī 与 kuī 声母不同（h 与 k），意思是挥动。", "溃": "kuì 与 kuī 声调不同（第四声与第一声），意思是溃散、溃败。"}, "sentence_index": null, "correct_answer": "亏"}, "level_3": {"options": [{"text": "亏", "is_correct": true, "explanation": "正确：亏，指投资赔钱，与“买这只股票”的语境相合。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说“读了一半的钱”。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是植物或液体，不能说“浇了一半的钱”。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“买这只股票”的语境不合。"}], "explanations": {"亏": "正确：亏，指投资赔钱，与“买这只股票”的语境相合。", "读": "搭配：“读”的对象是文字，不能说“读了一半的钱”。", "浇": "搭配：“浇”的对象是植物或液体，不能说“浇了一半的钱”。", "偷": "语义：“偷”是窃取，与“买这只股票”的语境不合。"}, "sentence_index": 6, "correct_answer": "亏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的开支亏了两千块。", "explanation": "这里应该用〈减少〉。亏指钱财或生意上的损失，开支变少是好事，要用减少。"}, {"text": "他的心情亏了，整天不说话。", "explanation": "这里应该用〈变差〉。亏指钱财或生意上的损失，心情变坏要用变差。"}, {"text": "他在路上亏了钱包。", "explanation": "这里应该用〈丢失〉。亏指做生意或投资赔钱，不能用于丢失物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅上个月了亏五万块。", "corrected_sentence": "这家餐厅上个月亏了五万块。", "error_description": "“了”应放在“亏”之后表示完成，正确说“亏了五万块”，不能说“了亏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年做生意亏来了一大笔钱。", "corrected_sentence": "他去年做生意亏了一大笔钱。", "error_description": "“来”不能作“亏”的补语，“亏来”不成词，应说“亏了一大笔钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
