INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因某人或某事才避免了不好的结果，多用于表示感谢。", "primary_collocate": null, "pronunciation": "kuī", "ipa": "kʰueɪ˥", "syllable_count": 1, "sentences": [{"text": "亏你提醒我，不然我就忘了。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "亏了同事来帮忙，我才做完。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le tóngshì lái bāngmáng, wǒ cái zuò wán", "sentence_source": "generated"}, {"text": "亏了老师帮忙复习，这次考试我才及格。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le lǎoshī bāngmáng fùxí, zhè cì kǎoshì wǒ cái jígé", "sentence_source": "generated"}, {"text": "亏了妹妹带了伞，我们才没淋湿。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le mèimei dài le sǎn, wǒmen cái méi lín shī", "sentence_source": "generated"}, {"text": "亏了弟弟跑得快，我们才没有迟到。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le dìdi pǎo de kuài, wǒmen cái méiyǒu chídào", "sentence_source": "generated"}, {"text": "亏他想得周到，大家都没有忘东西。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "亏了邻居叫醒我，我没有睡过头。", "target_word": "亏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亏了今天的好天气，衣服一天就干了。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le jīntiān de hǎo tiānqì, yīfu yì tiān jiù gān le", "sentence_source": "generated"}, {"text": "亏你记得路，要不我们就走错了。", "target_word": "亏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "亏了朋友借我钱，我才买到车票。", "target_word": "亏", "complexity_tier": "T3", "furigana": "kuī le péngyou jiè wǒ qián, wǒ cái mǎi dào chēpiào", "sentence_source": "generated"}], "morphological_forms": [{"form": "亏得", "label": "复合"}, {"form": "多亏", "label": "复合"}, {"form": "幸亏", "label": "复合"}, {"form": "亏了", "label": "体标"}], "register": "口语", "sense_fingerprint": "幸亏、多亏，因某人或某事才避免了不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亏", "is_correct": true, "explanation": "亏：幸亏、多亏，因某人或某事才避免了不好的结果，即本词。"}, {"text": "归", "is_correct": false, "explanation": "guī 与 kuī 声母不同（送气与否），意思是归还、回来。"}, {"text": "灰", "is_correct": false, "explanation": "huī 与 kuī 声母不同（h 与 k），意思是灰烬。"}, {"text": "溃", "is_correct": false, "explanation": "kuì 与 kuī 声调不同（第四声与第一声），意思是溃散。"}, {"text": "葵", "is_correct": false, "explanation": "kuí 与 kuī 声调不同（第二声与第一声），意思是向日葵一类的植物。"}], "explanations": {"亏": "亏：幸亏、多亏，因某人或某事才避免了不好的结果，即本词。", "归": "guī 与 kuī 声母不同（送气与否），意思是归还、回来。", "灰": "huī 与 kuī 声母不同（h 与 k），意思是灰烬。", "溃": "kuì 与 kuī 声调不同（第四声与第一声），意思是溃散。", "葵": "kuí 与 kuī 声调不同（第二声与第一声），意思是向日葵一类的植物。"}, "sentence_index": null, "correct_answer": "亏"}, "level_3": {"options": [{"text": "亏", "is_correct": true, "explanation": "正确：亏，表示幸亏、多亏，与“提醒我”的感激语境相合。"}, {"text": "怪", "is_correct": false, "explanation": "语义：“怪”是责怪，与“不然我就忘了”的感激语境相反。"}, {"text": "恨", "is_correct": false, "explanation": "语义：“恨”表示怨恨，与感谢提醒的语境不符。"}, {"text": "罚", "is_correct": false, "explanation": "搭配：“罚”需要受罚的对象和原因，不能用于“你提醒我”。"}], "explanations": {"亏": "正确：亏，表示幸亏、多亏，与“提醒我”的感激语境相合。", "怪": "语义：“怪”是责怪，与“不然我就忘了”的感激语境相反。", "恨": "语义：“恨”表示怨恨，与感谢提醒的语境不符。", "罚": "搭配：“罚”需要受罚的对象和原因，不能用于“你提醒我”。"}, "sentence_index": 0, "correct_answer": "亏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "亏你忘了带钥匙，我们才进不了门。", "explanation": "这里应该用〈怪〉。亏表示因某人才避免了坏结果，带有感谢；进不了门是坏结果，要用怪。"}, {"text": "亏了下大雨，比赛被取消了，大家都很失望。", "explanation": "这里应该用〈因为〉。亏用于避免了不好的结果，比赛取消让人失望，只能用因为说明原因。"}, {"text": "亏他迟到，我们没赶上火车。", "explanation": "这里应该用〈怪〉。没赶上火车是坏结果，不能用表示感谢的亏，要用怪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亏", "is_correct": true, "explanation": "亏：幸亏、多亏，因某人或某事才避免了不好的结果，即本词。"}, {"text": "规", "is_correct": false, "explanation": "guī 与 kuī 声母不同（送气与否），意思是规矩、规划。"}, {"text": "挥", "is_correct": false, "explanation": "huī 与 kuī 声母不同（h 与 k），意思是挥动。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 kuī 声调不同（第四声与第一声），意思是惭愧。"}], "explanations": {"亏": "亏：幸亏、多亏，因某人或某事才避免了不好的结果，即本词。", "规": "guī 与 kuī 声母不同（送气与否），意思是规矩、规划。", "挥": "huī 与 kuī 声母不同（h 与 k），意思是挥动。", "愧": "kuì 与 kuī 声调不同（第四声与第一声），意思是惭愧。"}, "sentence_index": null, "correct_answer": "亏"}, "level_3": {"options": [{"text": "亏", "is_correct": true, "explanation": "正确：亏，表示幸亏，此处指邻居叫醒我，使我没有睡过头。"}, {"text": "偷", "is_correct": false, "explanation": "搭配：“偷”是窃取，不能用于“叫醒我”这类行为。"}, {"text": "挡", "is_correct": false, "explanation": "搭配：“挡”指阻拦，与“叫醒我”的动作不搭配。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”表示厌烦，与“没有睡过头”的感激语境冲突。"}], "explanations": {"亏": "正确：亏，表示幸亏，此处指邻居叫醒我，使我没有睡过头。", "偷": "搭配：“偷”是窃取，不能用于“叫醒我”这类行为。", "挡": "搭配：“挡”指阻拦，与“叫醒我”的动作不搭配。", "嫌": "语义：“嫌”表示厌烦，与“没有睡过头”的感激语境冲突。"}, "sentence_index": 6, "correct_answer": "亏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "亏了你没提醒我，我才忘了带伞。", "explanation": "这里应该用〈怪〉。忘了带伞是坏结果，亏只用于因某人帮忙而避免坏结果。"}, {"text": "亏了堵车，我们才迟到了一个小时。", "explanation": "这里应该用〈因为〉。迟到是不好的结果，亏表示感谢，不能用来引出造成坏结果的原因。"}, {"text": "亏他把杯子打碎了，妈妈很生气。", "explanation": "这里应该用〈怪〉。打碎杯子带来坏结果，不能用表示感谢的亏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你亏帮忙，我才找到钥匙。", "corrected_sentence": "亏你帮忙，我才找到钥匙。", "error_description": "语序错误：“亏”要放在人称前面，应说“亏你帮忙”，不能说“你亏帮忙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "亏过妈妈提醒，我才没忘记药。", "corrected_sentence": "亏了妈妈提醒，我才没忘记药。", "error_description": "体标错误：“亏”表示幸亏时用“亏”或“亏了”，不能用“过”，应说“亏了妈妈提醒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "盈利", "is_correct": true, "explanation": "反义：亏损指做买卖时支出多于收入而赔钱，盈利指赚钱，二者在词典中互为反义。"}, {"text": "增长", "is_correct": false, "explanation": "无关：增长指数量或程度变大，与亏损的做买卖赔钱没有反义关系。"}, {"text": "投资", "is_correct": false, "explanation": "无关：投资指把钱用于生产或获利，并不是亏损的反义词。"}, {"text": "维持", "is_correct": false, "explanation": "无关：维持指保持原状，与亏损没有反义关系。"}], "correct_answer": "盈利", "explanations": {"盈利": "反义：亏损指做买卖时支出多于收入而赔钱，盈利指赚钱，二者在词典中互为反义。", "增长": "无关：增长指数量或程度变大，与亏损的做买卖赔钱没有反义关系。", "投资": "无关：投资指把钱用于生产或获利，并不是亏损的反义词。", "维持": "无关：维持指保持原状，与亏损没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "盈利", "is_correct": true, "explanation": "反义：亏损指支出多于收入而赔钱，盈利指赚钱，二者在词典中互为反义。"}, {"text": "上涨", "is_correct": false, "explanation": "无关：上涨指价格或数量升高，与亏损的做买卖赔钱没有反义关系。"}, {"text": "储蓄", "is_correct": false, "explanation": "无关：储蓄指把钱存起来，不是亏损的反义词。"}, {"text": "发展", "is_correct": false, "explanation": "无关：发展指事物向前变化，与亏损没有反义关系。"}], "correct_answer": "盈利", "explanations": {"盈利": "反义：亏损指支出多于收入而赔钱，盈利指赚钱，二者在词典中互为反义。", "上涨": "无关：上涨指价格或数量升高，与亏损的做买卖赔钱没有反义关系。", "储蓄": "无关：储蓄指把钱存起来，不是亏损的反义词。", "发展": "无关：发展指事物向前变化，与亏损没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做买卖，花出去的钱比赚回来的钱多。", "primary_collocate": null, "pronunciation": "kuī sǔn", "ipa": "kʰweɪ˥ swən˨˩", "syllable_count": 2, "sentences": [{"text": "这家小店去年亏损了五万元。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司已经亏损三年了。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开的饭馆一直在亏损。", "target_word": "亏损", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "生意不好，店里每个月都亏损。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂亏损得很厉害。", "target_word": "亏损", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板说，再亏损下去就开不了店了。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他卖菜没有亏损，还赚了一点钱。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上商店刚开始时常常亏损。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为房租太贵，小饭馆亏损了。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司从来没有亏损过。", "target_word": "亏损", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亏损了", "label": "体标：了"}, {"form": "亏损过", "label": "体标：过"}, {"form": "虧損", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做买卖时支出多于收入，赔钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亏损", "is_correct": true, "explanation": "正确：亏损指做买卖时支出超过收入，与“小店去年”的经营语境相符。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：损坏指东西被弄坏，不能带“五万元”这样的钱数作宾语。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是窃取别人的钱，与小店经营上赔钱的意思不符。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞指私吞、吞没，表示据为己有，不用于描述经营上的亏损。"}], "explanations": {"亏损": "正确：亏损指做买卖时支出超过收入，与“小店去年”的经营语境相符。", "损坏": "语义：损坏指东西被弄坏，不能带“五万元”这样的钱数作宾语。", "偷": "语义：偷是窃取别人的钱，与小店经营上赔钱的意思不符。", "吞": "语义：吞指私吞、吞没，表示据为己有，不用于描述经营上的亏损。"}, "sentence_index": 0, "correct_answer": "亏损"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故给他的家庭造成了很大的亏损。", "explanation": "这里应该用〈损失〉。亏损只用于做买卖、经营中支出超过收入，事故造成的人员或财产损失要说损失。"}, {"text": "这次去北京旅游，我亏损了三百元。", "explanation": "这里应该用〈花费〉。亏损指做买卖赔钱，旅游花钱只说花费，不说亏损。"}, {"text": "这台机器用了十年，亏损很严重。", "explanation": "这里应该用〈损耗〉。亏损专指经营中的赔钱，机器的磨损和消耗要说损耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亏损", "is_correct": true, "explanation": "正确：“没有亏损”与“还赚了一点钱”相呼应，表示经营没有赔钱。"}, {"text": "盈利", "is_correct": false, "explanation": "语义：盈利就是赚钱，与“还赚了一点钱”的意思相矛盾。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入也指赚到钱，与后半句重复，句子前后意思矛盾。"}, {"text": "结余", "is_correct": false, "explanation": "搭配：结余多指账目或款项的剩余，不用来说一个人卖菜的得失。"}], "explanations": {"亏损": "正确：“没有亏损”与“还赚了一点钱”相呼应，表示经营没有赔钱。", "盈利": "语义：盈利就是赚钱，与“还赚了一点钱”的意思相矛盾。", "收入": "语义：收入也指赚到钱，与后半句重复，句子前后意思矛盾。", "结余": "搭配：结余多指账目或款项的剩余，不用来说一个人卖菜的得失。"}, "sentence_index": 6, "correct_answer": "亏损"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱包亏损了。", "explanation": "这里应该用〈丢失〉。亏损只指做买卖赔钱，钱包或东西丢了要说丢失。"}, {"text": "他撞坏了邻居的车，要亏损三千元。", "explanation": "这里应该用〈赔偿〉。赔偿是因为损坏别人的东西而付钱，亏损不用于这种情况。"}, {"text": "他白白亏损了一整天的时间。", "explanation": "这里应该用〈浪费〉。亏损指做买卖赔钱，白白耗去时间要说浪费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店今年被亏损了不少钱。", "corrected_sentence": "这家店今年亏损了不少钱。", "error_description": "错误：“被亏损”。正确：“亏损”。亏损是店自身经营赔钱，不是被动发生的，不能加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家网店前年亏损地很厉害。", "corrected_sentence": "那家网店前年亏损得很厉害。", "error_description": "错误：“亏损地很厉害”。正确：“亏损得很厉害”。补语前要用结构助词“得”，“地”只用于状语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "盈余", "is_correct": true, "explanation": "反义：亏损指企业支出超过收入造成的损失，盈余指收入超过支出的余额，二者相对。"}, {"text": "成本", "is_correct": false, "explanation": "无关：成本是生产或经营付出的花费，与亏损不构成反义关系。"}, {"text": "费用", "is_correct": false, "explanation": "无关：费用指为某事支出的钱，本身不与亏损相对。"}, {"text": "资产", "is_correct": false, "explanation": "无关：资产指拥有的财产，不是亏损的反义词。"}], "correct_answer": "盈余", "explanations": {"盈余": "反义：亏损指企业支出超过收入造成的损失，盈余指收入超过支出的余额，二者相对。", "成本": "无关：成本是生产或经营付出的花费，与亏损不构成反义关系。", "费用": "无关：费用指为某事支出的钱，本身不与亏损相对。", "资产": "无关：资产指拥有的财产，不是亏损的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "盈余", "is_correct": true, "explanation": "反义：亏损指企业支出超过收入造成的损失，盈余指收入超过支出的余额，二者相对。"}, {"text": "工资", "is_correct": false, "explanation": "无关：工资指员工的劳动报酬，与亏损没有反义关系。"}, {"text": "预算", "is_correct": false, "explanation": "无关：预算指对收支的事先计划，不是亏损的反义词。"}, {"text": "存款", "is_correct": false, "explanation": "无关：存款指存放在银行的钱，与亏损不构成反义关系。"}], "correct_answer": "盈余", "explanations": {"盈余": "反义：亏损指企业支出超过收入造成的损失，盈余指收入超过支出的余额，二者相对。", "工资": "无关：工资指员工的劳动报酬，与亏损没有反义关系。", "预算": "无关：预算指对收支的事先计划，不是亏损的反义词。", "存款": "无关：存款指存放在银行的钱，与亏损不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "企业支出超过收入而造成的损失。", "primary_collocate": null, "pronunciation": "kuī sǔn", "ipa": "kʰweɪ˥ swən˨˩", "syllable_count": 2, "sentences": [{"text": "这家公司的亏损越来越大。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年的亏损已经补上了。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想办法减少公司的亏损。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行告诉老板，店里的亏损太大了。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的亏损有十万元。", "target_word": "亏损", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂出现了很大的亏损。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年的亏损都写在报告里。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新店第一年的亏损是意料中的事。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用赚的钱补上了亏损。", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司为什么会有这么多亏损？", "target_word": "亏损", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "亏损额", "label": "复合"}, {"form": "亏损企业", "label": "复合"}, {"form": "虧損", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业支出大于收入所形成的损失额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亏损", "is_correct": true, "explanation": "正确：亏损指企业支出超过收入而造成的损失额，与“这家公司的”“越来越大”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高说的是人或物的高矮，不能用来形容公司的赔钱数额。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，不能用来形容公司的赔钱数额。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：学历说的是受教育的程度，一般说“高”，不说公司的学历“越来越大”。"}], "explanations": {"亏损": "正确：亏损指企业支出超过收入而造成的损失额，与“这家公司的”“越来越大”相符。", "身高": "语义：身高说的是人或物的高矮，不能用来形容公司的赔钱数额。", "体重": "语义：体重指人或动物的重量，不能用来形容公司的赔钱数额。", "学历": "搭配：学历说的是受教育的程度，一般说“高”，不说公司的学历“越来越大”。"}, "sentence_index": 0, "correct_answer": "亏损"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店里这一只亏损太大了，老板很着急。", "explanation": "这里应该用〈笔〉。量词“只”多用于动物、船只等，表示亏损的数额要用“笔”。"}, {"text": "这台机器的亏损每年都很高。", "explanation": "这里应该用〈折旧〉。折旧指设备价值逐年减少，是会计上的计算，不说亏损。"}, {"text": "这种零件的亏损很大，要经常更换。", "explanation": "这里应该用〈损耗〉。损耗指零件在使用中的消耗，亏损只指企业经营上的赔钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亏损", "is_correct": true, "explanation": "正确：亏损指企业支出超过收入造成的损失额，每年的账目损失写在报告里，语境相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是个人的纪念日，不会每年都写在企业的报告里。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命说生物的存活期，与企业账目报告无关。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声是欢笑的声音，不能像账目一样写进报告，与“写在报告里”的语境不符。"}], "explanations": {"亏损": "正确：亏损指企业支出超过收入造成的损失额，每年的账目损失写在报告里，语境相符。", "生日": "语义：生日是个人的纪念日，不会每年都写在企业的报告里。", "寿命": "语义：寿命说生物的存活期，与企业账目报告无关。", "笑声": "语义：笑声是欢笑的声音，不能像账目一样写进报告，与“写在报告里”的语境不符。"}, "sentence_index": 6, "correct_answer": "亏损"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长期抽烟会对身体造成很大的亏损。", "explanation": "这里应该用〈损害〉。亏损只用于企业经营上的赔钱，对身体的伤害要说损害。"}, {"text": "这次摔落让电脑出现了很大的亏损。", "explanation": "这里应该用〈损坏〉。亏损不用于器物受损，电脑摔坏了要说损坏。"}, {"text": "他白白亏损了一整个周末。", "explanation": "这里应该用〈浪费〉。亏损是企业经营上的赔钱，白白耗去时间要说浪费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司去年有一只不小的亏损。", "corrected_sentence": "公司去年有一笔不小的亏损。", "error_description": "错误：“一只不小的亏损”。正确：“一笔不小的亏损”。亏损作数额时用量词“笔”，“只”多用于动物、船只等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家厂的亏损了很大。", "corrected_sentence": "这家厂的亏损很大。", "error_description": "错误：“亏损了很大”。正确：“亏损很大”。此处的“亏损”是名词，后面不能加“了”，“了”只能用在动词“亏损”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
