INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96637, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不能肯定，也许会这样。", "primary_collocate": null, "pronunciation": "shuō bu dìng", "ipa": "ʂwo˥ pu tiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "明天说不定会下雨。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说不定已经回家了。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在去，说不定还能买到票。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说不定在图书馆学习。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，说不定他马上就来。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事说不定是真的。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，说不定要下雪。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机关了，说不定在睡觉。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在出发，说不定能赶上火车。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问问老师，说不定她知道。", "target_word": "说不定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "說不定", "label": "繁体"}], "register": "口语", "sense_fingerprint": "副词，对情况不能肯定，表示有可能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说不定", "is_correct": true, "explanation": "“说不定”表示不能肯定的推测，与“明天会下雨”的未定语气相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”指已经发生的事，与“明天”的将来时间矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与“明天”的将来时间矛盾。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，不能直接修饰肯定的推测。"}], "explanations": {"说不定": "“说不定”表示不能肯定的推测，与“明天会下雨”的未定语气相符。", "已经": "语义：“已经”指已经发生的事，与“明天”的将来时间矛盾。", "刚刚": "语义：“刚刚”指刚发生的事，与“明天”的将来时间矛盾。", "根本": "搭配：“根本”通常与否定词连用，不能直接修饰肯定的推测。"}, "sentence_index": 0, "correct_answer": "说不定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说不定是中国人，我们都知道。", "explanation": "这里应该用〈确实〉。说不定表示不能肯定，大家都知道的事实要用确实，与“我们都知道”矛盾。"}, {"text": "地球说不定是圆的。", "explanation": "这里应该用〈确实〉。说不定表示不能肯定，已知的科学事实不能用它。"}, {"text": "她说不定是我的母亲，我很清楚。", "explanation": "这里应该用〈一定〉。说不定表示不能肯定，与“我很清楚”矛盾，确信要用一定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说不定", "is_correct": true, "explanation": "“说不定”表示不能肯定的推测，与“天这么黑”的判断相符。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”指很早以前，与“天这么黑”的当下判断不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过的事，不能用于对将要下雪的推测。"}, {"text": "从没", "is_correct": false, "explanation": "搭配：“从没”需与过去的经历或否定式搭配，不能用于将要发生的下雪。"}], "explanations": {"说不定": "“说不定”表示不能肯定的推测，与“天这么黑”的判断相符。", "早就": "语义：“早就”指很早以前，与“天这么黑”的当下判断不合。", "曾经": "语义：“曾经”指过去发生过的事，不能用于对将要下雪的推测。", "从没": "搭配：“从没”需与过去的经历或否定式搭配，不能用于将要发生的下雪。"}, "sentence_index": 6, "correct_answer": "说不定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我说不定去过北京，记得很清楚。", "explanation": "这里应该用〈肯定〉。说不定表示不能肯定，说记得很清楚的事要用肯定，与“记得很清楚”矛盾。"}, {"text": "我说不定是你哥哥，我们是一个妈妈生的。", "explanation": "这里应该用〈当然〉。说不定表示不能肯定，与“我们是一个妈妈生的”这一确定事实矛盾。"}, {"text": "一加一说不定等于二。", "explanation": "这里应该用〈当然〉。说不定表示不能肯定，数学的事实不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚说不定的会下雨。", "corrected_sentence": "今晚说不定会下雨。", "error_description": "错误在“说不定”后的“的”：“说不定”是副词，后面不能直接加“的”。应写作“今晚说不定会下雨。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事很说不定是假的。", "corrected_sentence": "这件事说不定是假的。", "error_description": "错误在“很”：“说不定”是副词，不能被“很”修饰。应写作“这件事说不定是假的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
