INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "老师或专家给很多人讲一个题目。", "primary_collocate": null, "pronunciation": "jiǎng zuò", "ipa": "tɕjɑŋ˨˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "明天下午学校有一场讲座。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天去听了一个关于健康的讲座。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场讲座在大教室举行，人很多。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲座七点开始，请大家准时到。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王教授的讲座非常有意思。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都想去听那个历史讲座。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲座结束后，同学们问了很多问题。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆每个星期六都有讲座。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了听讲座，特意坐车来到这个城市。", "target_word": "讲座", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次讲座的票已经卖完了。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "公开讲座", "label": "复合"}, {"form": "講座", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一次专家或老师面对听众讲一个题目的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲座", "is_correct": true, "explanation": "正确：讲座指专家或老师面对听众讲一个题目的场合，与“学校有一场”相符。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是睡眠时出现的幻觉，学校不会在明天下午有一场梦，与讲座的活动不符。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争是武装冲突，学校不会有一场战争，与讲座的活动不符。"}, {"text": "空袭", "is_correct": false, "explanation": "语义：空袭是军事袭击，学校不会有一场空袭，与讲座的活动不符。"}], "explanations": {"讲座": "正确：讲座指专家或老师面对听众讲一个题目的场合，与“学校有一场”相符。", "梦": "语义：梦是睡眠时出现的幻觉，学校不会在明天下午有一场梦，与讲座的活动不符。", "战争": "语义：战争是武装冲突，学校不会有一场战争，与讲座的活动不符。", "空袭": "语义：空袭是军事袭击，学校不会有一场空袭，与讲座的活动不符。"}, "sentence_index": 0, "correct_answer": "讲座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我们去听一把讲座。", "explanation": "这里应该用〈场〉。量词“把”多用于有柄的器具，讲座用“场”或“次”。"}, {"text": "他在婚礼上吃了一份讲座。", "explanation": "这里应该用〈蛋糕〉。讲座是活动，不能吃，吃的东西要说蛋糕。"}, {"text": "他站在讲座上，向大家唱了一首歌。", "explanation": "这里应该用〈讲台〉。讲座指一种活动，不指站人的台子，站在台子上要说讲台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲座", "is_correct": true, "explanation": "正确：讲座结束后同学们提问，符合讲座活动的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是活动，不能说“桌子结束后”。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，不会有同学围着提问，语境不合。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：婚礼是喜庆仪式，不说婚礼结束后同学们提问。"}], "explanations": {"讲座": "正确：讲座结束后同学们提问，符合讲座活动的语境。", "桌子": "语义：桌子是家具，不是活动，不能说“桌子结束后”。", "手术": "语义：手术是医疗操作，不会有同学围着提问，语境不合。", "婚礼": "搭配：婚礼是喜庆仪式，不说婚礼结束后同学们提问。"}, "sentence_index": 6, "correct_answer": "讲座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在讲座里吃了午饭。", "explanation": "这里应该用〈食堂〉。讲座是活动，不是可以吃饭的场所。"}, {"text": "他是一位很有名的讲座。", "explanation": "这里应该用〈演员〉。讲座指一种活动，不指人，不能说“是一位讲座”。"}, {"text": "老师把讲座收进了书包里。", "explanation": "这里应该用〈课本〉。讲座是活动，不是实物，不能收进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天请来一位专家，办了一把讲座。", "corrected_sentence": "学校昨天请来一位专家，办了一场讲座。", "error_description": "错误：“一把讲座”。正确：“一场讲座”。量词“把”用于有柄的器具，讲座这类活动用“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天去吃了一场关于历史的讲座，收获很大。", "corrected_sentence": "我昨天去听了一场关于历史的讲座，收获很大。", "error_description": "错误：“吃了一场讲座”。正确：“听了一场讲座”。讲座是讲授知识的活动，动词要用“听”，不能用“吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
