INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "围绕某一专题向听众讲授知识的活动。", "primary_collocate": null, "pronunciation": "jiǎng zuò", "ipa": "tɕjɑŋ˨˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "学校经常办各种讲座，让大家多学知识。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院办的健康讲座很受老人欢迎。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种讲座的目的是教大家学习方法。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听讲座可以学到课本上没有的知识。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个系列讲座一共讲了五个专题。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月都做一次讲座，介绍历史知识。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公开讲座对所有市民免费开放。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场讲座讲的是怎样保护眼睛。", "target_word": "讲座", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区组织讲座，教大家怎么用手机。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位专家专门做科学讲座。", "target_word": "讲座", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "系列讲座", "label": "复合"}, {"form": "讲座课", "label": "复合"}, {"form": "講座", "label": "繁体"}], "register": "中性", "sense_fingerprint": "围绕专题向听众传授知识的一类活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲座", "is_correct": true, "explanation": "正确：讲座是围绕专题讲授知识的活动，与“多学知识”的目的相符。"}, {"text": "饭局", "is_correct": false, "explanation": "语义：饭局是聚餐活动，不以让大家多学知识为目的。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是丧事仪式，不以让大家多学知识为目的。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：宴会以吃喝为主，不以让大家多学知识为目的。"}], "explanations": {"讲座": "正确：讲座是围绕专题讲授知识的活动，与“多学知识”的目的相符。", "饭局": "语义：饭局是聚餐活动，不以让大家多学知识为目的。", "葬礼": "语义：葬礼是丧事仪式，不以让大家多学知识为目的。", "宴会": "语义：宴会以吃喝为主，不以让大家多学知识为目的。"}, "sentence_index": 0, "correct_answer": "讲座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿上了讲座出门。", "explanation": "这里应该用〈衣服〉。讲座是活动，不是可以穿的物品。"}, {"text": "我听了一条讲座。", "explanation": "这里应该用〈场〉。量词“条”多用于细长的东西，讲座用“场”或“次”。"}, {"text": "他是一位著名的讲座。", "explanation": "这里应该用〈学者〉。讲座指活动，不指人，不能说“是一位讲座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲座", "is_correct": true, "explanation": "正确：公开讲座面向所有市民，并且免费开放，符合讲座活动的语境。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是营业场所，不会对所有市民免费开放。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是私人庆典，不会对所有市民免费开放。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验学识的活动，不是对外开放的场所，不会“对所有市民免费开放”。"}], "explanations": {"讲座": "正确：公开讲座面向所有市民，并且免费开放，符合讲座活动的语境。", "饭店": "语义：饭店是营业场所，不会对所有市民免费开放。", "婚礼": "语义：婚礼是私人庆典，不会对所有市民免费开放。", "考试": "语义：考试是测验学识的活动，不是对外开放的场所，不会“对所有市民免费开放”。"}, "sentence_index": 6, "correct_answer": "讲座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人在咖啡馆里进行了一次愉快的讲座。", "explanation": "这里应该用〈对话〉。讲座是一人向听众讲授知识的活动，两人互相交流要说对话。"}, {"text": "孩子们在操场上玩讲座。", "explanation": "这里应该用〈游戏〉。讲座是讲授知识的活动，玩耍要说游戏。"}, {"text": "我们一起喝讲座。", "explanation": "这里应该用〈茶〉。讲座是活动，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校每个月都办一把讲座。", "corrected_sentence": "学校每个月都办一场讲座。", "error_description": "错误：“一把讲座”。正确：“一场讲座”。量词“把”用于有柄的器具，讲座这类活动用“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做过很多条讲座。", "corrected_sentence": "他做过很多次讲座。", "error_description": "错误：“很多条讲座”。正确：“很多次讲座”。量词“条”用于细长的东西，讲座这类活动用“次”或“场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
