INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96657, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个膝盖放在地上，身体直起来。", "primary_collocate": null, "pronunciation": "guì", "ipa": "kweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他在垫子上跪着，背挺得很直。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在佛像前跪了很久。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你跪在这里，不要乱动。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们整齐地跪在地上祈祷。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跪着给花盆浇水。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘在父母面前跪下磕头。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明跪在椅子上，看窗外的雪。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跪了一会儿，腿就麻了。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的人在皇帝面前要跪。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生跪着给地上的病人检查。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跪着", "label": "体标"}, {"form": "跪了", "label": "体标"}, {"form": "跪过", "label": "体标"}], "register": "中性", "sense_fingerprint": "双膝着地、上身挺直", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96657, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跪", "is_correct": true, "explanation": "guì（第四声）：两个膝盖放在地上，身体直起来。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。"}, {"text": "归", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是归还、归于。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 guì 声母不同（h 与 g），意思是会议、会面。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 guì 声母不同（送气与否），意思是惭愧。"}], "explanations": {"跪": "guì（第四声）：两个膝盖放在地上，身体直起来。", "鬼": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。", "归": "guī（第一声）与 guì（第四声）声调不同，意思是归还、归于。", "会": "huì 与 guì 声母不同（h 与 g），意思是会议、会面。", "愧": "kuì 与 guì 声母不同（送气与否），意思是惭愧。"}, "sentence_index": null, "correct_answer": "跪"}, "level_3": {"options": [{"text": "跪", "is_correct": true, "explanation": "跪：双膝着地，与“在垫子上……背挺得很直”的姿势相符。"}, {"text": "躺", "is_correct": false, "explanation": "语义：躺是身体平卧，与“背挺得很直”矛盾。"}, {"text": "趴", "is_correct": false, "explanation": "语义：趴是身体伏卧，不能同时保持“背挺得很直”。"}, {"text": "滚", "is_correct": false, "explanation": "语义：滚是身体翻转，与“背挺得很直”的静止跪姿矛盾。"}], "explanations": {"跪": "跪：双膝着地，与“在垫子上……背挺得很直”的姿势相符。", "躺": "语义：躺是身体平卧，与“背挺得很直”矛盾。", "趴": "语义：趴是身体伏卧，不能同时保持“背挺得很直”。", "滚": "语义：滚是身体翻转，与“背挺得很直”的静止跪姿矛盾。"}, "sentence_index": 0, "correct_answer": "跪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跪在沙发上，翘着二郎腿看电视。", "explanation": "这里应该用〈坐〉。翘二郎腿是坐姿，跪要求双膝着地，两者不能同时成立。"}, {"text": "他跪在床上，身子平躺着。", "explanation": "这里误用了〈跪〉。跪是双膝着地的姿势，与句中身体卧倒的姿态冲突，应该换成表示卧倒的动词。"}, {"text": "他跪在床边，两腿伸直，脚踩在地上。", "explanation": "这里应该用〈站〉。两腿伸直、双脚踩地是站立的姿势，不是双膝着地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96657, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跪", "is_correct": true, "explanation": "guì（第四声）：两个膝盖放在地上，身体直起来。"}, {"text": "溃", "is_correct": false, "explanation": "kuì 与 guì 声母不同（送气与否），意思是溃散。"}, {"text": "规", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是规则。"}, {"text": "汇", "is_correct": false, "explanation": "huì（第四声）与 guì 声母不同（h 与 g），意思是汇集、汇款。"}, {"text": "轨", "is_correct": false, "explanation": "guǐ（第三声）与 guì（第四声）声调不同，意思是轨道。"}], "explanations": {"跪": "guì（第四声）：两个膝盖放在地上，身体直起来。", "溃": "kuì 与 guì 声母不同（送气与否），意思是溃散。", "规": "guī（第一声）与 guì（第四声）声调不同，意思是规则。", "汇": "huì（第四声）与 guì 声母不同（h 与 g），意思是汇集、汇款。", "轨": "guǐ（第三声）与 guì（第四声）声调不同，意思是轨道。"}, "sentence_index": null, "correct_answer": "跪"}, "level_3": {"options": [{"text": "跪", "is_correct": true, "explanation": "跪：双膝着地，适合“小明……在椅子上，看窗外的雪”这种跪在椅子上的姿势。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡着就看不见窗外的雪，与“看窗外的雪”冲突。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”是用牙齿的动作，不能表示身体跪在椅子上。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，不能用于描述身体在椅子上的姿势。"}], "explanations": {"跪": "跪：双膝着地，适合“小明……在椅子上，看窗外的雪”这种跪在椅子上的姿势。", "睡": "语义：睡着就看不见窗外的雪，与“看窗外的雪”冲突。", "咬": "搭配：“咬”是用牙齿的动作，不能表示身体跪在椅子上。", "洗": "搭配：“洗”的对象是物品，不能用于描述身体在椅子上的姿势。"}, "sentence_index": 6, "correct_answer": "跪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跪在台阶上，两只脚板平平地踩着地，等车来。", "explanation": "这里应该用〈蹲〉。蹲时脚掌平踩地面，跪是膝盖着地，脚背朝下，二者姿势不同。"}, {"text": "他跪了三个头，额头碰到地面。", "explanation": "这里应该用〈磕〉。磕头是额头触地，跪只说双膝着地，不能跟“三个头”搭配计数。"}, {"text": "他跪在那里，膝盖却始终没有碰到地面。", "explanation": "这里应该用〈蹲〉。跪要求膝盖着地，句中“膝盖始终没有碰到地面”是蹲的姿势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她跪下了来，给老人磕了头。", "corrected_sentence": "她跪下来，给老人磕了头。", "error_description": "补语错误：“了”插在“下”与“来”之间，应说“跪下来”或“跪下来了”，不能说“跪下了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跪着地上擦桌子。", "corrected_sentence": "她跪在地上擦桌子。", "error_description": "位置错误：“跪着”后缺少“在”，应为“跪在地上”，表示跪的处所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
