INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96658, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "屈膝使膝盖着地。", "primary_collocate": null, "pronunciation": "guì", "ipa": "kweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他的腿一软，一下子跪在了地上。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着跪在妈妈面前道歉。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骆驼慢慢跪下来，让人爬上去。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他双膝一跪，哭了起来。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员跪在地上，亲了亲草地。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跪地求婚，戒指拿在手里。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跪了一下，把掉在床下的笔捡起来。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别跪在我面前，有话站着说。", "target_word": "跪", "complexity_tier": "T3", "furigana": "nǐ bié guì zài wǒ miànqián, yǒu huà zhàn zhe shuō", "sentence_source": "generated"}, {"text": "小孩累得跪在沙发前睡着了。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在雨里跪了一个晚上。", "target_word": "跪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跪着", "label": "体标"}, {"form": "跪了", "label": "体标"}, {"form": "跪过", "label": "体标"}], "register": "中性", "sense_fingerprint": "弯曲膝盖让膝盖碰地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跪", "is_correct": true, "explanation": "guì（第四声）：屈膝使膝盖着地。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。"}, {"text": "归", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是归还、归于。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 guì 声母不同（送气与否），意思是惭愧。"}, {"text": "溃", "is_correct": false, "explanation": "kuì 与 guì 声母不同（送气与否），意思是溃散。"}], "explanations": {"跪": "guì（第四声）：屈膝使膝盖着地。", "鬼": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。", "归": "guī（第一声）与 guì（第四声）声调不同，意思是归还、归于。", "愧": "kuì 与 guì 声母不同（送气与否），意思是惭愧。", "溃": "kuì 与 guì 声母不同（送气与否），意思是溃散。"}, "sentence_index": null, "correct_answer": "跪"}, "level_3": {"options": [{"text": "跪", "is_correct": true, "explanation": "跪：屈膝使膝盖着地，符合“腿一软，一下子……在了地上”的动作。"}, {"text": "站", "is_correct": false, "explanation": "语义：腿一软站不住，与“一下子……站在地上”矛盾。"}, {"text": "爬", "is_correct": false, "explanation": "搭配：爬指缓慢地用手脚移动，与“一下子”的瞬间动作不搭。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：跳指离地腾起，“跳在地上”不是常见说法，与“一下子”后落地的动作不合。"}], "explanations": {"跪": "跪：屈膝使膝盖着地，符合“腿一软，一下子……在了地上”的动作。", "站": "语义：腿一软站不住，与“一下子……站在地上”矛盾。", "爬": "搭配：爬指缓慢地用手脚移动，与“一下子”的瞬间动作不搭。", "跳": "搭配：跳指离地腾起，“跳在地上”不是常见说法，与“一下子”后落地的动作不合。"}, "sentence_index": 0, "correct_answer": "跪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛输了，他一屁股跪在地上，哭了起来。", "explanation": "这里应该用〈坐〉。“一屁股”是臀部着地，跪是双膝着地，二者不能同时描述。"}, {"text": "比赛输了，他跪在草地上，双膝却悬在半空，哭了起来。", "explanation": "这里应该用〈蹲〉。跪要求膝盖着地，句中“双膝悬在半空”说明膝盖没有着地，是蹲的姿势。"}, {"text": "比赛输了，他的双脚跪在草地上，哭了起来。", "explanation": "这里误用了〈跪〉。跪要求双膝着地，主语“双脚”不能跪，双脚着地应该用〈站〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96658, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跪", "is_correct": true, "explanation": "guì（第四声）：屈膝使膝盖着地。"}, {"text": "规", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是规则。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 guì 声母不同（h 与 g），意思是会议、会面。"}, {"text": "汇", "is_correct": false, "explanation": "huì（第四声）与 guì 声母不同（h 与 g），意思是汇集、汇款。"}, {"text": "轨", "is_correct": false, "explanation": "guǐ（第三声）与 guì（第四声）声调不同，意思是轨道。"}], "explanations": {"跪": "guì（第四声）：屈膝使膝盖着地。", "规": "guī（第一声）与 guì（第四声）声调不同，意思是规则。", "会": "huì 与 guì 声母不同（h 与 g），意思是会议、会面。", "汇": "huì（第四声）与 guì 声母不同（h 与 g），意思是汇集、汇款。", "轨": "guǐ（第三声）与 guì（第四声）声调不同，意思是轨道。"}, "sentence_index": null, "correct_answer": "跪"}, "level_3": {"options": [{"text": "跪", "is_correct": true, "explanation": "跪：膝盖着地，符合“我……了一下，把掉在床下的笔捡起来”的低身动作。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉与“把掉在床下的笔捡起来”的动作无关，无法完成捡笔。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是发声动作，不能用来完成“把笔捡起来”。"}, {"text": "站", "is_correct": false, "explanation": "语义：站着够不到床下的笔，与“掉在床下”的情境冲突。"}], "explanations": {"跪": "跪：膝盖着地，符合“我……了一下，把掉在床下的笔捡起来”的低身动作。", "睡": "语义：睡觉与“把掉在床下的笔捡起来”的动作无关，无法完成捡笔。", "咳嗽": "语义：咳嗽是发声动作，不能用来完成“把笔捡起来”。", "站": "语义：站着够不到床下的笔，与“掉在床下”的情境冲突。"}, "sentence_index": 6, "correct_answer": "跪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在雨里跪了三次头，额头都肿了。", "explanation": "这里应该用〈磕〉。磕头是额头触地，跪只说双膝着地，不能跟“三次头”搭配计数。"}, {"text": "他在雨里跪了一个晚上，腿伸得笔直，两脚踩在泥水里。", "explanation": "这里误用了〈跪〉。跪要求膝盖着地，句中“腿伸得笔直、两脚踩在泥水里”是站立的姿势，应该用〈站〉。"}, {"text": "他在雨里跪了一个晚上，膝盖却始终悬在半空。", "explanation": "这里应该用〈蹲〉。跪要求膝盖着地，句中“膝盖始终悬在半空”是蹲的姿势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的腿一软，一下子跪下了来。", "corrected_sentence": "他的腿一软，一下子跪下了。", "error_description": "补语错误：“了”插在“下”与“来”之间，应说“跪下来了”或“跪下了”，不能说“跪下了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在雨里了跪一整夜。", "corrected_sentence": "他在雨里跪了一整夜。", "error_description": "位置错误：“了”应放在动词之后表示完成（跪了一整夜），不能放在“跪”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
