INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96665, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "和这个一样的这一种。", "primary_collocate": null, "pronunciation": "zhè lèi", "ipa": "ʈʂɤ˥˩ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这类书我最爱看，里面有很多故事。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类问题很难，你要想一想。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢这类电影，太吵了。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类水果又甜又便宜，妈妈常买。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类衣服夏天穿最舒服。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就见过这类人，所以不怕。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类工作需要很多耐心。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这类题考试时常常出现。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类鸟冬天会飞到南方去。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类歌我已经听了很多遍。", "target_word": "这类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指代与刚才提到的事物同一种类的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这类", "is_correct": true, "explanation": "正确。“这类书”指这一类书，作主语，与“里面有很多故事”的语境相符。"}, {"text": "哪类", "is_correct": false, "explanation": "语义：“哪类”是疑问代词，询问哪一类，与“我最爱看”的陈述语气不符。"}, {"text": "这张", "is_correct": false, "explanation": "量词：“张”不能用于“书”，应说“这本书”。"}, {"text": "何类", "is_correct": false, "explanation": "语义：“何类”同样表示询问，句子是在陈述自己的喜好，放进去语义不通。"}], "explanations": {"这类": "正确。“这类书”指这一类书，作主语，与“里面有很多故事”的语境相符。", "哪类": "语义：“哪类”是疑问代词，询问哪一类，与“我最爱看”的陈述语气不符。", "这张": "量词：“张”不能用于“书”，应说“这本书”。", "何类": "语义：“何类”同样表示询问，句子是在陈述自己的喜好，放进去语义不通。"}, "sentence_index": 0, "correct_answer": "这类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这类书是我刚买的那一本，我还没看过。", "explanation": "这里指眼前刚买的某一本，应该用〈这本〉。〈这类〉指一类书，不能只指单独一本。"}, {"text": "这类裙子是妈妈昨天给我买的那一条，我很喜欢。", "explanation": "这里指一条具体的裙子，应该用〈这条〉。〈这类〉指同一类裙子，不能只指某一条。"}, {"text": "这类苹果就是我今天摘的那一个，很甜。", "explanation": "这里指一个具体的苹果，应该用〈这个〉。〈这类〉指同一类苹果，不能等同于其中某一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这类", "is_correct": true, "explanation": "正确。“这类工作”指这一类工作，作主语，与“需要很多耐心”的描述相符。"}, {"text": "哪种", "is_correct": false, "explanation": "语义：“哪种”是疑问，询问是哪一种工作，与陈述“需要很多耐心”的语境不合。"}, {"text": "何种", "is_correct": false, "explanation": "语义：“何种”同样表示询问，句子是在陈述一个事实，放进去语义不通。"}, {"text": "这张", "is_correct": false, "explanation": "量词：“张”不能修饰“工作”。"}], "explanations": {"这类": "正确。“这类工作”指这一类工作，作主语，与“需要很多耐心”的描述相符。", "哪种": "语义：“哪种”是疑问，询问是哪一种工作，与陈述“需要很多耐心”的语境不合。", "何种": "语义：“何种”同样表示询问，句子是在陈述一个事实，放进去语义不通。", "这张": "量词：“张”不能修饰“工作”。"}, "sentence_index": 6, "correct_answer": "这类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这类事情是上个月发生在我家的那一件，很有意思。", "explanation": "这里指一件具体的事，应该用〈这件〉。〈这类〉指同一类事情，不指某一件。"}, {"text": "这类教室是我们学校的那一间，窗户很大。", "explanation": "这里指一间具体的教室，应该用〈这间〉。〈这类〉指一类教室，不能指某一间。"}, {"text": "这类狗是我家的，它每天陪我玩。", "explanation": "这里指家里养的一只具体的狗，应该用〈这只〉。〈这类〉指一类动物，不指单独一只。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周都会借这类一本小说来读。", "corrected_sentence": "我每周都会借这类小说来读。", "error_description": "错误在“这类一本”。“这类”是限定词，后面直接接名词，不能再加数量短语“一本”，应说“这类小说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这类一台手机的价格越来越便宜了。", "corrected_sentence": "这类手机的价格越来越便宜了。", "error_description": "错误在“这类一台”。“这类”是限定词，后面直接接名词，不能再加数量短语“一台”，应说“这类手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
