INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96669, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一直在发展，越来越重。", "primary_collocate": null, "pronunciation": "jìn xíng xìng", "ipa": "t͡ɕin˥˩ ɕiŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "医生说他的病是进行性的，会越来越重。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病是进行性的，要早点治疗。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的听力问题是进行性的，一年比一年差。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的视力下降是进行性的，不会自己好起来。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进行性的疾病，越早发现越好。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的腿越来越没力气，医生说是进行性的。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病是进行性的，不是休息几天就能好。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的记忆变差是进行性的，现在更严重了。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为病是进行性的，他每个月都要检查。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生为什么说这种病是进行性的？", "target_word": "进行性", "complexity_tier": "T3", "furigana": "jìn xíng xìng", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "病情不断发展越来越严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfc67122-5602-4672-be92-b592090b5833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进行性", "is_correct": true, "explanation": "正确：“进行性”指病情持续加重，与“会越来越重”一致。"}, {"text": "稳定", "is_correct": false, "explanation": "语义：“稳定”指不再变化，与后文“会越来越重”矛盾。"}, {"text": "暂时", "is_correct": false, "explanation": "语义：“暂时”指持续时间短、会结束的状态，与“会越来越重”的持续变化冲突。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”形容物体不动，不用来描述病情的变化。"}], "explanations": {"进行性": "正确：“进行性”指病情持续加重，与“会越来越重”一致。", "稳定": "语义：“稳定”指不再变化，与后文“会越来越重”矛盾。", "暂时": "语义：“暂时”指持续时间短、会结束的状态，与“会越来越重”的持续变化冲突。", "静止": "搭配：“静止”形容物体不动，不用来描述病情的变化。"}, "sentence_index": 0, "correct_answer": "进行性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病的好转是进行性的，每周都有改善。", "explanation": "这里应该用〈渐进性〉。进行性指病情不断加重，不能用来说病情在好转。"}, {"text": "他的哮喘是进行性的，病情十年没有加重了。", "explanation": "这里应该用〈稳定〉。进行性指病情不断加重，与“病情十年没有加重”矛盾。"}, {"text": "这次手术是进行性的，只用了一个小时。", "explanation": "这里误把“进行性”当成了“正在进行、尚未结束”的意思。进行性专指病情持续加重，不能用来形容一次完成的手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进行性", "is_correct": true, "explanation": "正确：“进行性”指病情逐渐加重，与“不是休息几天就能好”相符。"}, {"text": "一过性", "is_correct": false, "explanation": "语义：“一过性”指暂时出现、很快消失，与“不是休息几天就能好”的持续状况矛盾。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指持续时间很短，与“不是休息几天就能好”冲突。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容人的身体状态，不能用来形容病的性质。"}], "explanations": {"进行性": "正确：“进行性”指病情逐渐加重，与“不是休息几天就能好”相符。", "一过性": "语义：“一过性”指暂时出现、很快消失，与“不是休息几天就能好”的持续状况矛盾。", "短暂": "语义：“短暂”指持续时间很短，与“不是休息几天就能好”冲突。", "健康": "搭配：“健康”形容人的身体状态，不能用来形容病的性质。"}, "sentence_index": 6, "correct_answer": "进行性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种病是进行性的，每隔三个月发作一次。", "explanation": "这里应该用〈周期性〉。进行性指病情不断加重，不指间歇发作。"}, {"text": "他的病情是进行性的，多年没有变化。", "explanation": "这里应该用〈稳定〉。进行性指病情不断加重，与“多年没有变化”矛盾。"}, {"text": "这位老师是进行性的，一直很有耐心。", "explanation": "这里误把“进行性”当成了“持续不变的状态”的意思。进行性专指病症逐渐加重，不能用来形容老师的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一种进行性地疾病，需要长期随访。", "corrected_sentence": "这是一种进行性的疾病，需要长期随访。", "error_description": "“进行性”修饰名词“疾病”时要用“的”，不能用“地”（“地”用于修饰动词、形容词）。正确句为“进行性的疾病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病曾经是进行性过的，后来逐渐缓和了。", "corrected_sentence": "这种病曾经是进行性的，后来逐渐缓和了。", "error_description": "“进行性”是形容词，后面不能加“过”；“过”表示经历过的动作，不能接在形容词后。正确句为“曾经是进行性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
