INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入并拜见（地位高的人）。", "primary_collocate": null, "pronunciation": "jìn jiàn", "ipa": "tɕin˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "外国使臣到京城后，先进见了皇帝。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的官员要先进见知府大人。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上官服，去进见太后。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们排好队，恭敬地进见老校长。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军回到京城，立刻进见皇上汇报战况。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在宫门外跪着，请求进见皇上。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，百姓很难有机会进见皇帝。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使递上国书，进见了总统。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照规矩，臣子进见君王时要行大礼。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着礼物去进见那位有名的老先生。", "target_word": "进见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进见了", "label": "完成体"}, {"form": "进见过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "进入后恭敬地拜见地位高的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶走", "is_correct": false, "explanation": "语义：外国使臣不会把皇帝赶走，与恭敬拜见的语境不符。"}, {"text": "进见", "is_correct": true, "explanation": "进见：进入后拜见皇帝，与外国使臣到京城的语境相符。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”的宾语是活动或仪式，不能直接带“皇帝”。"}, {"text": "修建", "is_correct": false, "explanation": "配价：“修建”的宾语应是建筑物，不能带“皇帝”。"}], "explanations": {"赶走": "语义：外国使臣不会把皇帝赶走，与恭敬拜见的语境不符。", "进见": "进见：进入后拜见皇帝，与外国使臣到京城的语境相符。", "举办": "配价：“举办”的宾语是活动或仪式，不能直接带“皇帝”。", "修建": "配价：“修建”的宾语应是建筑物，不能带“皇帝”。"}, "sentence_index": 0, "correct_answer": "进见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长进见了学生代表。", "explanation": "这里应该用〈接见〉。进见是地位低的人拜见地位高的人，校长接见学生不能说进见。"}, {"text": "他进见了那座古老的寺庙。", "explanation": "这里应该用〈参观〉。进见是拜见地位高的人，宾语必须是人；古寺是景点，去看要说参观。"}, {"text": "他带着礼物去进见病人。", "explanation": "这里应该用〈探望〉。进见是地位低的人拜见地位高的人，病人不是地位高的人，探望病人要说探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的宾语应是场所或物品，不能直接带“皇帝”。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”的宾语是器物，不能说修理皇帝。"}, {"text": "进见", "is_correct": true, "explanation": "进见：进入后拜见皇帝，与“百姓很难有机会”的语境相符。"}, {"text": "雇佣", "is_correct": false, "explanation": "语义：皇帝不能被雇佣，与百姓很难接近皇帝的语境不符。"}], "explanations": {"打扫": "配价：“打扫”的宾语应是场所或物品，不能直接带“皇帝”。", "修理": "配价：“修理”的宾语是器物，不能说修理皇帝。", "进见": "进见：进入后拜见皇帝，与“百姓很难有机会”的语境相符。", "雇佣": "语义：皇帝不能被雇佣，与百姓很难接近皇帝的语境不符。"}, "sentence_index": 6, "correct_answer": "进见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皇帝在殿上进见了大臣，询问边关战况。", "explanation": "这里应该用〈召见〉。皇帝是地位高的人，叫大臣来见要说召见，进见只用于地位低的人拜见地位高的人。"}, {"text": "两国代表在会场进见，互相握手致意。", "explanation": "这里应该用〈会见〉。两国代表地位平等，应说会见，不能用进见。"}, {"text": "他常去进见老朋友，一起喝茶聊天。", "explanation": "这里应该用〈拜访〉。朋友之间是平等关系，进见只用于地位低的人拜见地位高的人，应说拜访。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿上朝服，把进见县令。", "corrected_sentence": "他穿上朝服，去进见县令。", "error_description": "把字句错误：“进见”不能用在“把”字句中，应说「去进见县令」，不能说「把进见县令」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大使被进见了总统。", "corrected_sentence": "大使进见了总统。", "error_description": "被字句错误：“进见”是主动的动作，不能用“被”构成被动句，应为“大使进见了总统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
