INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96677, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到了自己出生的那天，大家一起庆祝。", "primary_collocate": null, "pronunciation": "guò shēng", "ipa": "kuo˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "今天是爷爷的生日，全家人一起给他过生。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天奶奶过生，我们要去她家吃蛋糕。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在饭店给妈妈过生，大家都唱了歌。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友过生那天，我们送了他一本书。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明下个星期过生，同学们都要去他家。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王今年六十岁，儿女们回家给他过生。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过生的时候，朋友们送来了很多花和蛋糕。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有个习惯，谁过生，大家就一起吃面条。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天公司的同事小李过生，大家买了蛋糕。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子过生，爸爸特意请了一天假。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过生日", "label": "复合"}], "register": "口语", "sense_fingerprint": "过生：生日那天，大家聚在一起为某人庆祝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过生", "is_correct": true, "explanation": "正确：“过生”指生日当天大家一起庆祝，与“爷爷的生日”相合。"}, {"text": "送行", "is_correct": false, "explanation": "语义：“送行”指送别远行的人，与生日庆祝的场合不符。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”表达悲伤，与“生日”的喜庆氛围相矛盾。"}, {"text": "搬家", "is_correct": false, "explanation": "搭配：“给他搬家”指帮他搬迁，与“今天是爷爷的生日”这一庆祝场景不搭配。"}], "explanations": {"过生": "正确：“过生”指生日当天大家一起庆祝，与“爷爷的生日”相合。", "送行": "语义：“送行”指送别远行的人，与生日庆祝的场合不符。", "哭泣": "语义：“哭泣”表达悲伤，与“生日”的喜庆氛围相矛盾。", "搬家": "搭配：“给他搬家”指帮他搬迁，与“今天是爷爷的生日”这一庆祝场景不搭配。"}, "sentence_index": 0, "correct_answer": "过生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节我们全家一起过生，吃了饺子。", "explanation": "这里应该用〈过节〉。春节是节日，“过生”只用于个人的生日。"}, {"text": "我们在饭店为刚回国的朋友过生，席间没有人提到生日。", "explanation": "这里应该用〈接风〉。为远道归来的朋友设宴接风，“过生”只用于庆祝生日。"}, {"text": "为了过生，大家都穿上了黑衣服。", "explanation": "这里应该用〈悼念〉。穿黑衣服是为逝者哀悼的做法，“过生”只用于庆祝生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过生", "is_correct": true, "explanation": "正确：“过生”指过生日，与“她过生的时候朋友送花”的情境相合。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公外出，与朋友们送来很多花的生日情境不合。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”不是值得送花送蛋糕庆祝的事，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”与“朋友们送来很多花”的庆祝场景不搭配。"}], "explanations": {"过生": "正确：“过生”指过生日，与“她过生的时候朋友送花”的情境相合。", "出差": "语义：“出差”指因公外出，与朋友们送来很多花的生日情境不合。", "迟到": "语义：“迟到”不是值得送花送蛋糕庆祝的事，句意不通。", "散步": "搭配：“散步”与“朋友们送来很多花”的庆祝场景不搭配。"}, "sentence_index": 6, "correct_answer": "过生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们为新店开业过生了一整天。", "explanation": "这里应该用〈庆祝〉。开业不是人的生日，“过生”只用于生日。"}, {"text": "开学典礼那天，校长为全校师生过生。", "explanation": "这里应该用〈举行庆典〉。开学仪式是全校的庆典，“过生”只用于个人的生日。"}, {"text": "今天是他们的婚礼，大家都来给他们过生。", "explanation": "这里应该用〈办喜事〉。婚礼是结婚的喜事，“过生”只用于个人的生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天是妈妈的生日，我们想把她过生。", "corrected_sentence": "明天是妈妈的生日，我们想给她过生。", "error_description": "错误：“过生”本身是动宾结构，后面不能再带宾语，也不能用“把”字句。为某人庆祝要用“给”引出对象：应说“想给她过生”，不说“想把她过生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个星期六我们给他过生了吧。", "corrected_sentence": "下个星期六我们给他过生吧。", "error_description": "错误：句中已有“下个星期六”，“过生”指将来要进行的事，不能在“生”后加“了”。应说“给他过生”，不说“过生了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
