INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过生日；庆祝生日。", "primary_collocate": null, "pronunciation": "guò shēng", "ipa": "kuo˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "我哥哥今天过生，晚上要请朋友吃饭。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打算怎么过生？去饭店还是在家？", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我想在公园里过生，不想去饭店。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过生那天正好下大雨，客人都没来。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢热闹，每年都是一个人过生。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月你过生，想要什么礼物？", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司每个月给过生的同事发一个蛋糕。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候家里穷，我们很少过生。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外过生，他有点想家。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明天过生，你别忘了给她打电话。", "target_word": "过生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过生日", "label": "复合"}], "register": "口语", "sense_fingerprint": "过生：过生日，安排或进行生日的庆祝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过生", "is_correct": true, "explanation": "正确：“过生”指过生日，与“晚上要请朋友吃饭”的庆祝安排相合。"}, {"text": "下葬", "is_correct": false, "explanation": "语义：“下葬”是丧葬仪式，与“请朋友吃饭”的喜庆安排相矛盾。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”表达悲伤，与“请朋友吃饭”的安排不符。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”是身体状况，不能与“晚上要请朋友吃饭”这种活动安排搭配。"}], "explanations": {"过生": "正确：“过生”指过生日，与“晚上要请朋友吃饭”的庆祝安排相合。", "下葬": "语义：“下葬”是丧葬仪式，与“请朋友吃饭”的喜庆安排相矛盾。", "哭泣": "语义：“哭泣”表达悲伤，与“请朋友吃饭”的安排不符。", "生病": "搭配：“生病”是身体状况，不能与“晚上要请朋友吃饭”这种活动安排搭配。"}, "sentence_index": 0, "correct_answer": "过生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中秋节我们全家一起过生，吃了月饼。", "explanation": "这里应该用〈过节〉。中秋是节日，“过生”只用于个人的生日。"}, {"text": "市长来访那天，学校在门口为他过生，大家列队欢迎。", "explanation": "这里应该用〈欢迎〉。列队迎接来宾是欢迎仪式，“过生”只用于庆祝个人的生日。"}, {"text": "运动员赢得比赛后，教练为他们过生。", "explanation": "这里应该用〈庆功〉。为比赛胜利而庆祝要说“庆功”，“过生”只指过生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过生", "is_correct": true, "explanation": "正确：“过生的同事”指过生日的同事，与“发一个蛋糕”相合。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是患病，与“发一个蛋糕”的庆祝之意不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与发蛋糕的庆祝场景无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不是可以用蛋糕来庆祝的事件，二者不搭配。"}], "explanations": {"过生": "正确：“过生的同事”指过生日的同事，与“发一个蛋糕”相合。", "感冒": "语义：“感冒”是患病，与“发一个蛋糕”的庆祝之意不合。", "考试": "语义：“考试”与发蛋糕的庆祝场景无关，句意不通。", "散步": "搭配：“散步”不是可以用蛋糕来庆祝的事件，二者不搭配。"}, "sentence_index": 6, "correct_answer": "过生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校为运动会的成功过生了三天。", "explanation": "这里应该用〈庆祝〉。运动会的成功不是人的生日，“过生”只用于生日。"}, {"text": "夏令营结束那天，我们在湖边给营地过生，大家玩得很开心。", "explanation": "这里应该用〈举行结营仪式〉。营地没有生日，“过生”只用于为人庆祝生日。"}, {"text": "领奖台上，主持人为比赛的胜利过生，全场一起鼓掌。", "explanation": "这里应该用〈庆祝〉。比赛胜利不是生日，“过生”只用于庆祝个人的生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今年想在家里把爸爸过生。", "corrected_sentence": "我们今年想在家里给爸爸过生。", "error_description": "错误：“过生”本身是动宾结构，后面不能再带宾语，也不能用“把”字句。为某人庆祝要用“给”引出对象：应说“给爸爸过生”，不说“把爸爸过生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年夏天我们给她过生了吧，就在海边。", "corrected_sentence": "明年夏天我们给她过生吧，就在海边。", "error_description": "错误：句中已有“明年夏天”，“过生”指将来要进行的事，不能在“生”后加“了”。应说“给她过生”，不说“过生了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
