INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选举时划分的以便选出代表的区域。", "primary_collocate": null, "pronunciation": "xuǎn qū", "ipa": "ɕɥɛn˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "政府按人口重新划分了选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选区要选出一名议员。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选区的边界改了，很多人不满意。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员要为自己选区的人说话。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市一共有八个选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上登了新选区的地图。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个选区第一次当选议员。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选前，候选人跑遍了整个选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选区划得不公平，大家都在讨论。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选区的投票率特别高。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "選區", "label": "繁体"}], "register": "正式", "sense_fingerprint": "选举时划分的、用来选出代表或议员的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfc67122-5602-4672-be92-b592090b5833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选区", "is_correct": true, "explanation": "正确：“划分”可以作用于选区，选区指选举时划分的区域，与“按人口”一致。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是按人口划分的对象，与“按人口”矛盾。"}, {"text": "利息", "is_correct": false, "explanation": "搭配：“划分”可以搭配区域，不能搭配“利息”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是按人口划分的对象，与“按人口”冲突。"}], "explanations": {"选区": "正确：“划分”可以作用于选区，选区指选举时划分的区域，与“按人口”一致。", "课本": "语义：课本不是按人口划分的对象，与“按人口”矛盾。", "利息": "搭配：“划分”可以搭配区域，不能搭配“利息”。", "作业": "语义：作业是学习任务，不是按人口划分的对象，与“按人口”冲突。"}, "sentence_index": 0, "correct_answer": "选区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个选区的降雨量很大。", "explanation": "这里应该用〈地区〉。选区指选举时划分的区域，不指自然地理上的范围。"}, {"text": "这个选区有三十层，很高。", "explanation": "选区是选举时划分的区域，不是有楼层的建筑，不能说有几层。"}, {"text": "我把选区装进了箱子里。", "explanation": "选区是划分出来的区域，不是有形的东西，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选区", "is_correct": true, "explanation": "正确：“在选区当选”指在选举区域中当选，与“当选议员”一致。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是选举划分的区域，不能在医院当选议员。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是选举划分的区域，与“当选议员”冲突。"}, {"text": "方案", "is_correct": false, "explanation": "搭配：“在…当选”需要表示区域的名词，“方案”不能与之搭配。"}], "explanations": {"选区": "正确：“在选区当选”指在选举区域中当选，与“当选议员”一致。", "医院": "语义：医院不是选举划分的区域，不能在医院当选议员。", "厨房": "语义：厨房不是选举划分的区域，与“当选议员”冲突。", "方案": "搭配：“在…当选”需要表示区域的名词，“方案”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "选区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个派出所的选区每天都有人来报案。", "explanation": "这里应该用〈辖区〉。选区是选举时划分的区域，派出所等机构管的是辖区，不能说派出所的选区。"}, {"text": "这个选区的身高有一米八。", "explanation": "这里误把“选区”当成了一个有身高的人，比如候选人。选区是选举时划分的区域，没有身高，不能这样描述。"}, {"text": "我一口吃掉了这个选区。", "explanation": "选区是抽象的划分，不是可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调整改变了选区地范围，居民们很关心。", "corrected_sentence": "这次调整改变了选区的范围，居民们很关心。", "error_description": "“选区”修饰名词“范围”时要用“的”，不能用“地”。正确句为“选区的范围”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这只选区有八万名选民。", "corrected_sentence": "我们这个选区有八万名选民。", "error_description": "“选区”的量词应为“个”，“只”用于动物等，不能用于选区。正确为“这个选区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
