INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从很多人里挑出最好的几个人。", "primary_collocate": null, "pronunciation": "xuǎn bá", "ipa": "ɕɥɛn˨˩˦ pa˧˥", "syllable_count": 2, "sentences": [{"text": "学校要选拔几名学生参加比赛。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从我们班选拔了两个人。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年都选拔新的经理。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是从一百人中选拔出来的。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队正在选拔新队员。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校选拔过很多好学生。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用考试来选拔最好的人。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天学校要选拔唱歌好的孩子。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院想选拔一位年轻的医生去学习。", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师怎么选拔班长？", "target_word": "选拔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选拔了", "label": "体标"}, {"form": "选拔过", "label": "体标"}, {"form": "选拔赛", "label": "复合"}, {"form": "选拔人才", "label": "复合"}], "register": "书面", "sense_fingerprint": "从很多人里挑出最好的几个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选拔", "is_correct": true, "explanation": "语境：“选拔”指从众人中挑出优秀的人，符合“学校要……几名学生参加比赛”的句意。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能用于学生，与“学校要……几名学生参加比赛”不合。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：“淘汰”是除去不合格者，与“参加比赛”的意思相反。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，与让学生去参加比赛的句意相反。"}], "explanations": {"选拔": "语境：“选拔”指从众人中挑出优秀的人，符合“学校要……几名学生参加比赛”的句意。", "收割": "搭配：“收割”用于庄稼，不能用于学生，与“学校要……几名学生参加比赛”不合。", "淘汰": "语义：“淘汰”是除去不合格者，与“参加比赛”的意思相反。", "驱逐": "语义：“驱逐”是赶走，与让学生去参加比赛的句意相反。"}, "sentence_index": 0, "correct_answer": "选拔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市选拔了一瓶牛奶。", "explanation": "这里应该用〈挑选〉。选拔指从众人中挑出优秀的人，不能用来挑商品。"}, {"text": "妈妈选拔了一件毛衣。", "explanation": "这里应该用〈挑〉。选拔的对象是优秀的人，不能用来挑衣服。"}, {"text": "工厂选拔了一批次品。", "explanation": "这里应该用〈筛选〉。选拔挑的是优秀的人，不能用来剔除次品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选拔", "is_correct": true, "explanation": "语境：“用考试来……最好的人”，指通过考试挑出最好的人，句意通顺。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：“淘汰”是去掉差的，与“最好的人”的语境矛盾。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：用考试去惩罚最好的人，与常理相反。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是果实、花等，不能用于人。"}], "explanations": {"选拔": "语境：“用考试来……最好的人”，指通过考试挑出最好的人，句意通顺。", "淘汰": "语义：“淘汰”是去掉差的，与“最好的人”的语境矛盾。", "惩罚": "语义：用考试去惩罚最好的人，与常理相反。", "摘": "搭配：“摘”的对象是果实、花等，不能用于人。"}, "sentence_index": 6, "correct_answer": "选拔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这学期选拔了一门日语课。", "explanation": "这里应该用〈选修〉。选拔的对象是人，不能用于课程。"}, {"text": "我在网上选拔了一台电脑。", "explanation": "这里应该用〈选购〉。选拔选的是人，不能用于买东西。"}, {"text": "我在水果店选拔了几个苹果。", "explanation": "这里应该用〈挑选〉。选拔的对象是人，不能用来挑水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是从十个人里选拔出来得。", "corrected_sentence": "她是从十个人里选拔出来的。", "error_description": "“是……的”句式的结尾应用结构助词“的”，不能用“得”。错误句“选拔出来得”，应改为“选拔出来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
