INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选拔", "is_correct": true, "explanation": "语境：“学校每年……一次优秀学生”，指每年挑选一次优秀的学生，句意通顺。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”针对犯错的人，不能用来对待优秀学生。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能说收割学生。"}, {"text": "抓", "is_correct": false, "explanation": "语义：“抓”指捉拿，与“优秀学生”的语境不合。"}], "explanations": {"选拔": "语境：“学校每年……一次优秀学生”，指每年挑选一次优秀的学生，句意通顺。", "惩罚": "语义：“惩罚”针对犯错的人，不能用来对待优秀学生。", "收割": "搭配：“收割”用于庄稼，不能说收割学生。", "抓": "语义：“抓”指捉拿，与“优秀学生”的语境不合。"}, "sentence_index": 6, "correct_answer": "选拔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下学期选拔了一门摄影课。", "explanation": "这里应该用〈选修〉。选拔的对象是人，不能用于课程。"}, {"text": "我在超市选拔了一箱苹果。", "explanation": "这里应该用〈选购〉。选拔选的是人，不能用于买水果。"}, {"text": "老板选拔了每个人的工作。", "explanation": "这里应该用〈分配〉。选拔的对象是人，不能用来派发工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司选拔的出来了三名好员工。", "corrected_sentence": "这家公司选拔出了三名好员工。", "error_description": "结果补语“出”应紧接动词，写作“选拔出了”，中间不能插入“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年学校选拔了过两名学生去北京。", "corrected_sentence": "去年学校选拔过两名学生去北京。", "error_description": "“选拔”后的“了”与“过”不能同时出现。表示曾经发生时只说“选拔过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "甜与酸是味道上的反义，正对应“像没熟橘子或醋的味道”。"}, {"text": "咸", "is_correct": false, "explanation": "咸是另一种味道，与酸不构成反义关系。"}, {"text": "辣", "is_correct": false, "explanation": "辣是另一种刺激性的味道，与酸不构成反义关系。"}, {"text": "硬", "is_correct": false, "explanation": "硬描述质地，与酸的味道无反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "甜与酸是味道上的反义，正对应“像没熟橘子或醋的味道”。", "咸": "咸是另一种味道，与酸不构成反义关系。", "辣": "辣是另一种刺激性的味道，与酸不构成反义关系。", "硬": "硬描述质地，与酸的味道无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "甜与酸是味道上的反义，正对应“像没熟橘子或醋的味道”。"}, {"text": "慢", "is_correct": false, "explanation": "慢描述速度，与酸的味道无反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻描述重量，与酸的味道无反义关系。"}, {"text": "高", "is_correct": false, "explanation": "高描述高度，与酸的味道无反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "甜与酸是味道上的反义，正对应“像没熟橘子或醋的味道”。", "慢": "慢描述速度，与酸的味道无反义关系。", "轻": "轻描述重量，与酸的味道无反义关系。", "高": "高描述高度，与酸的味道无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像没熟的橘子或醋一样的味道。", "primary_collocate": null, "pronunciation": "suān", "ipa": "swan˥", "syllable_count": 1, "sentences": [{"text": "这个橘子还没熟，很酸。", "target_word": "酸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "醋太酸了，我不想喝。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没熟的橘子吃起来又酸又涩。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他咬了一口青橘子，酸得皱起了眉头。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这碗汤里放了太多醋，喝起来很酸。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不爱吃酸的，请少放一点醋。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没熟的橘子比熟的酸得多。", "target_word": "酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的菜里放了醋，有点酸。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯柠檬水太酸，要加点糖。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青苹果又脆又酸，我很喜欢吃。", "target_word": "酸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸酸的", "label": "重叠"}, {"form": "酸味", "label": "复合"}, {"form": "酸甜", "label": "复合"}], "register": "中性", "sense_fingerprint": "味道像没熟的橘子或醋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酸", "is_correct": true, "explanation": "这是目标词，suān（第一声），意思是像没熟的橘子或醋的味道。"}, {"text": "蒜", "is_correct": false, "explanation": "suàn（第四声）与 suān（第一声）声调不同，意思是大蒜。"}, {"text": "三", "is_correct": false, "explanation": "sān 与 suān 少了介音 u，声调相同，意思是数字三。"}, {"text": "栓", "is_correct": false, "explanation": "shuān 与 suān 声母不同（sh/s），声调相同，意思是塞子、门栓。"}], "explanations": {"酸": "这是目标词，suān（第一声），意思是像没熟的橘子或醋的味道。", "蒜": "suàn（第四声）与 suān（第一声）声调不同，意思是大蒜。", "三": "sān 与 suān 少了介音 u，声调相同，意思是数字三。", "栓": "shuān 与 suān 声母不同（sh/s），声调相同，意思是塞子、门栓。"}, "sentence_index": null, "correct_answer": "酸"}, "level_3": {"options": [{"text": "酸", "is_correct": true, "explanation": "这是目标词，是没熟橘子的味道，与“还没熟”相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：没熟的橘子通常不甜，与“还没熟”冲突。"}, {"text": "美", "is_correct": false, "explanation": "搭配：形容水果一般不用“美”，说“很美”多指景色或人。"}, {"text": "香", "is_correct": false, "explanation": "语义：没熟的橘子一般不香，与“还没熟”冲突。"}], "explanations": {"酸": "这是目标词，是没熟橘子的味道，与“还没熟”相符。", "甜": "语义：没熟的橘子通常不甜，与“还没熟”冲突。", "美": "搭配：形容水果一般不用“美”，说“很美”多指景色或人。", "香": "语义：没熟的橘子一般不香，与“还没熟”冲突。"}, "sentence_index": 0, "correct_answer": "酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海水很酸，不能直接喝。", "explanation": "这里应该用〈咸〉。海水的味道是咸的，“酸”指醋或未熟果子的味道，不用来形容海水。"}, {"text": "这瓶蜂蜜很酸，我每天加一点到水里。", "explanation": "这里应该用〈甜〉。蜂蜜的味道是甜的，“酸”不用来形容蜂蜜。"}, {"text": "这点芥末很酸，他一下子咳了起来。", "explanation": "这里应该用〈辣〉。芥末的味道是辣的，“酸”不用来形容芥末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酸", "is_correct": true, "explanation": "这是目标词，suān（第一声），意思是像没熟的橘子或醋的味道。"}, {"text": "算", "is_correct": false, "explanation": "suàn（第四声）与 suān（第一声）声调不同，意思是计算。"}, {"text": "拴", "is_correct": false, "explanation": "shuān 与 suān 声母不同（sh/s），声调相同，意思是用绳子系住。"}, {"text": "孙", "is_correct": false, "explanation": "sūn 与 suān 少了元音 a，声调相同，意思是孙子。"}], "explanations": {"酸": "这是目标词，suān（第一声），意思是像没熟的橘子或醋的味道。", "算": "suàn（第四声）与 suān（第一声）声调不同，意思是计算。", "拴": "shuān 与 suān 声母不同（sh/s），声调相同，意思是用绳子系住。", "孙": "sūn 与 suān 少了元音 a，声调相同，意思是孙子。"}, "sentence_index": null, "correct_answer": "酸"}, "level_3": {"options": [{"text": "酸", "is_correct": true, "explanation": "这是目标词，与“比熟的……得多”的比较相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：橘子的味道不用“高”来比较，这里不成立。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：形容味道不用“冷”，“冷”描述的是温度。"}, {"text": "咸", "is_correct": false, "explanation": "语义：没熟的橘子比熟的咸，与橘子的味道常识不符。"}], "explanations": {"酸": "这是目标词，与“比熟的……得多”的比较相符。", "高": "搭配：橘子的味道不用“高”来比较，这里不成立。", "冷": "搭配：形容味道不用“冷”，“冷”描述的是温度。", "咸": "语义：没熟的橘子比熟的咸，与橘子的味道常识不符。"}, "sentence_index": 6, "correct_answer": "酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗药太酸了，我喝不下去。", "explanation": "这里应该用〈苦〉。药的味道一般说苦，“酸”用于醋或未熟果子等的味道。"}, {"text": "这块蛋糕很酸，他一口就吐了出来。", "explanation": "这里应该用〈甜〉。蛋糕通常是甜的，“酸”指醋或未熟果子的味道，不用来形容蛋糕。"}, {"text": "这罐盐很酸，不能放进汤里。", "explanation": "这里应该用〈咸〉。盐的味道是咸的，“酸”不用来形容盐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个橘子得酸我直皱眉头。", "corrected_sentence": "这个橘子酸得我直皱眉头。", "error_description": "补语结构应为“酸得……”，不能说“得酸”。“得”要放在形容词后，引出程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种橘子酸酸地，很开胃。", "corrected_sentence": "这种橘子酸酸的，很开胃。", "error_description": "“酸酸”作谓语要用“的”，“地”用于修饰动词，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
