INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品在一定时期内售出的数量。", "primary_collocate": null, "pronunciation": "xiāo liàng", "ipa": "ɕjɑʊ˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个月手机的销量比上个月高了很多。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车上市第一周，销量就超过了一千辆。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷以后，冰淇淋的销量下降了。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每个月的销量都排在第一名。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为价格便宜，这种牛奶的销量很好。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店长每天都要记录各种饮料的销量。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的销量比去年多了一倍。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，水果的销量总是特别大。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的销量已经超过了十万本。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告做得好，这个牌子的销量增长得很快。", "target_word": "销量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "月销量", "label": "复合"}, {"form": "总销量", "label": "复合"}, {"form": "銷量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商品在一段时间内卖出的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄只用于人或动物，手机没有年龄，不能说“年龄比上个月高了很多”。"}, {"text": "销量", "is_correct": true, "explanation": "正确：销量指商品卖出的数量，“手机的销量比上个月高了很多”语义通顺。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：说体积的大小用“大”“小”，不说“高了很多”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体态特征，不能用来描述手机。"}], "explanations": {"年龄": "语义：年龄只用于人或动物，手机没有年龄，不能说“年龄比上个月高了很多”。", "销量": "正确：销量指商品卖出的数量，“手机的销量比上个月高了很多”语义通顺。", "体积": "搭配：说体积的大小用“大”“小”，不说“高了很多”。", "身高": "体貌：身高是人的体态特征，不能用来描述手机。"}, "sentence_index": 0, "correct_answer": "销量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这个月的销量增加了三公斤。", "explanation": "这里应该用〈体重〉。人的重量要说体重，销量指卖出的商品数量。"}, {"text": "这家店仓库里的销量是一千件。", "explanation": "这里应该用〈库存〉。销量指已经卖出的数量，仓库里还没卖出的货要用库存。"}, {"text": "这家店每天的销量是三百人次。", "explanation": "这里应该用〈客流量〉。人次计算的是进店的人，销量计算的是卖出的商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体态，不能用来比较一个牌子的销量。"}, {"text": "视力", "is_correct": false, "explanation": "语义：视力指人或动物的视觉能力，与“今年的……比去年多了一倍”不相符。"}, {"text": "销量", "is_correct": true, "explanation": "正确：“今年的销量比去年多了一倍”表示卖出的数量翻倍，语义通顺。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指人受教育的经历，不能用来说商品的卖出数量。"}], "explanations": {"身材": "体貌：身材是人的体态，不能用来比较一个牌子的销量。", "视力": "语义：视力指人或动物的视觉能力，与“今年的……比去年多了一倍”不相符。", "销量": "正确：“今年的销量比去年多了一倍”表示卖出的数量翻倍，语义通顺。", "学历": "语义：学历指人受教育的经历，不能用来说商品的卖出数量。"}, "sentence_index": 6, "correct_answer": "销量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖的销量上涨得很快。", "explanation": "这里应该用〈水位〉。湖的高低要说水位，销量指卖出的商品数量。"}, {"text": "这篇文章的销量增长得很快。", "explanation": "这里应该用〈阅读量〉。文章被阅读的次数要说阅读量，文章不是售出的商品。"}, {"text": "这个学生的销量提高得很快。", "explanation": "这里应该用〈成绩〉。学生的学习结果要说成绩，销量不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个季度的销量增长的很快。", "corrected_sentence": "这个季度的销量增长得很快。", "error_description": "补语标记错误：“增长”后表示程度的补语要用“得”，不能用“的”。应说「增长得很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个牌子的销量了提高了不少。", "corrected_sentence": "这个牌子的销量提高了不少。", "error_description": "“了”位置错误：“了”不能放在名词“销量”后面，应只放在动词“提高”后面，应说「销量提高了不少」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
