INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很硬很亮、很贵的透明小石头。", "primary_collocate": null, "pronunciation": "zuàn shí", "ipa": "tswan˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "钻石很硬，也很亮，所以很贵。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈有一颗钻石，是外婆给她的。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在商店里看那些钻石看了很久。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这颗钻石像一块小冰，在太阳下很亮。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一颗小钻石就要好几万块钱。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钻石很硬，用刀也划不坏它。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把钻石放在盒子里，不让别人看。", "target_word": "钻石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这颗透明的钻石多亮啊！", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送给她一颗钻石，她高兴极了。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友以为钻石是普通的玻璃。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "钻石戒指", "label": "复合"}, {"form": "钻石项链", "label": "复合"}, {"form": "鑽石", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很硬很亮很贵的透明小石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钻石", "is_correct": true, "explanation": "正确：钻石既硬又亮，价格高，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头通常不贵，「所以很贵」与语境不符。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁一般不因为亮而昂贵，「所以很贵」与铁的性质不符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：「很亮」形容有光泽的物体，面包一般不用「很亮」来形容。"}], "explanations": {"钻石": "正确：钻石既硬又亮，价格高，符合句意。", "石头": "语义：石头通常不贵，「所以很贵」与语境不符。", "铁": "语义：铁一般不因为亮而昂贵，「所以很贵」与铁的性质不符。", "面包": "搭配：「很亮」形容有光泽的物体，面包一般不用「很亮」来形容。"}, "sentence_index": 0, "correct_answer": "钻石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗户上结了一层钻石。", "explanation": "这里应该用〈冰〉。钻石是矿物宝石，不会像冰一样在窗户上结成一层。"}, {"text": "妈妈在蛋糕上撒了一层钻石。", "explanation": "这里应该用〈糖〉。钻石是贵重的宝石，不能撒在蛋糕上当甜味，应该说撒了一层糖。"}, {"text": "院子里堆着一堆钻石，是准备盖房子用的。", "explanation": "这里应该用〈木头〉。钻石是贵重的宝石，不能用来盖房子，堆在院子里备用的应该是木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钻石", "is_correct": true, "explanation": "正确：钻石体积小、价值高，适合藏在盒子里不让别人看，符合句意。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜太大，一般放不进小盒子，也没有必要藏起来。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不值得特意藏起来不让别人看。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「放在盒子里」的宾语必须是有形的东西，空气不能放进盒子。"}], "explanations": {"钻石": "正确：钻石体积小、价值高，适合藏在盒子里不让别人看，符合句意。", "西瓜": "语义：西瓜太大，一般放不进小盒子，也没有必要藏起来。", "白菜": "语义：白菜不值得特意藏起来不让别人看。", "空气": "搭配：「放在盒子里」的宾语必须是有形的东西，空气不能放进盒子。"}, "sentence_index": 6, "correct_answer": "钻石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子是钻石做的，很容易碎。", "explanation": "这里应该用〈玻璃〉。钻石极硬，不容易碎；很容易碎的杯子通常是玻璃做的。"}, {"text": "冬天到了，他穿上了一件厚厚的钻石。", "explanation": "这里应该用〈棉衣〉。钻石是宝石，不能穿在身上保暖。"}, {"text": "他口渴了，喝了一大杯钻石。", "explanation": "这里应该用〈水〉。钻石是坚硬的宝石，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷留给我一根钻石。", "corrected_sentence": "爷爷留给我一颗钻石。", "error_description": "量词错误：「根」用于细长的东西，钻石应用量词「颗」或「块」，应把「一根钻石」改为「一颗钻石」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗很透明钻石在灯下闪闪发光。", "corrected_sentence": "这颗很透明的钻石在灯下闪闪发光。", "error_description": "结构助词错误：「很透明」修饰名词时，中间要加结构助词「的」，应把「很透明钻石」改为「很透明的钻石」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
