INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由碳构成的、极硬而透亮的宝石。", "primary_collocate": null, "pronunciation": "zuàn shí", "ipa": "tswan˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "钻石是世界上最硬的东西。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这颗钻石又大又亮，价格很高。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钻石由碳构成，所以非常硬。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用钻石切割很硬的玻璃。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的手上戴着一颗小钻石。", "target_word": "钻石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买一颗钻石，送给女朋友。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在灯光下，钻石发出了很亮的光。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钻石和铅笔里的石墨都是由碳构成的。", "target_word": "钻石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂可以用人工方法做出钻石。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块钻石很透明，里面没有一点黑色。", "target_word": "钻石", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "钻石戒指", "label": "复合"}, {"form": "钻石项链", "label": "复合"}, {"form": "鑽石", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由碳构成、极硬而透亮的宝石", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钻石", "is_correct": true, "explanation": "正确：钻石是由碳构成的极硬宝石，符合「世界上最硬的东西」的说法。"}, {"text": "石墨", "is_correct": false, "explanation": "语义：石墨质地柔软，不可能是世界上最硬的东西。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁虽然坚硬，但远不及钻石，不能说是世界上最硬的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「最硬」形容固体的硬度，不能用来形容空气。"}], "explanations": {"钻石": "正确：钻石是由碳构成的极硬宝石，符合「世界上最硬的东西」的说法。", "石墨": "语义：石墨质地柔软，不可能是世界上最硬的东西。", "铁": "语义：铁虽然坚硬，但远不及钻石，不能说是世界上最硬的东西。", "空气": "搭配：「最硬」形容固体的硬度，不能用来形容空气。"}, "sentence_index": 0, "correct_answer": "钻石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小摆件是钻石做的，几块钱就能买到。", "explanation": "这里应该用〈塑料〉。钻石是很贵的宝石，几块钱买不到；这么便宜的小摆件通常是塑料做的。"}, {"text": "汤里放了一小勺钻石，味道很好。", "explanation": "这里应该用〈盐〉。钻石是贵重的宝石，不是调料，做汤时应该放盐。"}, {"text": "路边的钻石很多，随便捡一块就行。", "explanation": "这里应该用〈石头〉。钻石很稀少，也很贵，不会像石头一样随处可见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钻石", "is_correct": true, "explanation": "正确：钻石在灯光下会反射出很亮的光，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：句中的语境是「在灯光下」，太阳不是灯光，不能出现在这个语境中。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花不会发光，也不能反射出很亮的光，与句意不符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头本身不会发亮，也不能反射出很亮的光，与句意不符。"}], "explanations": {"钻石": "正确：钻石在灯光下会反射出很亮的光，符合句意。", "太阳": "语义：句中的语境是「在灯光下」，太阳不是灯光，不能出现在这个语境中。", "棉花": "语义：棉花不会发光，也不能反射出很亮的光，与句意不符。", "木头": "语义：木头本身不会发亮，也不能反射出很亮的光，与句意不符。"}, "sentence_index": 6, "correct_answer": "钻石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块钻石很软，用手一捏就扁了。", "explanation": "这里应该用〈面团〉。钻石是最硬的宝石，捏不扁；一捏就扁的是面团。"}, {"text": "他口渴了，喝了一大杯钻石。", "explanation": "这里应该用〈水〉。钻石是坚硬的宝石，不能喝。"}, {"text": "钻石是黑色的，铅笔芯就是用它做的。", "explanation": "这里应该用〈石墨〉。钻石透明发亮，铅笔芯是用黑色的石墨做的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的戒指上镶着一根钻石。", "corrected_sentence": "妈妈的戒指上镶着一颗钻石。", "error_description": "量词错误：「根」用于细长的东西，钻石应用量词「颗」或「块」，应把「一根钻石」改为「一颗钻石」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她戴着一颗很亮钻石。", "corrected_sentence": "她戴着一颗很亮的钻石。", "error_description": "结构助词错误：「很亮」修饰名词时，中间要加结构助词「的」，应把「很亮钻石」改为「很亮的钻石」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
