INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地位比你高、管着你的人。", "primary_collocate": null, "pronunciation": "zhǎng guān", "ipa": "ʈʂɑŋ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "长官让我们明天早点到。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的长官对工作要求很严。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢在长官面前说错话。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长官今天心情不好，大家小心点。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把文件交给了长官。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的长官很年轻，也很客气。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都听长官的安排。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对长官说：“这件事我来做。”", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长官批评了他，他一句话也没说。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的长官知道这件事吗？", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "長官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地位高于自己、管着自己的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长官", "is_correct": true, "explanation": "长官：地位比“你”高、管着你的人，符合“让我们明天早点到”的指令关系。"}, {"text": "下属", "is_correct": false, "explanation": "语义：下属不能向“我们”下达指令，要求早到不合逻辑。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生无权安排“我们”的到达时间，与发出指令的人身份不合。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“让我们……早点到”的主语通常是有管理权的人，病人不搭配这类指令。"}], "explanations": {"长官": "长官：地位比“你”高、管着你的人，符合“让我们明天早点到”的指令关系。", "下属": "语义：下属不能向“我们”下达指令，要求早到不合逻辑。", "学生": "语义：学生无权安排“我们”的到达时间，与发出指令的人身份不合。", "病人": "搭配：“让我们……早点到”的主语通常是有管理权的人，病人不搭配这类指令。"}, "sentence_index": 0, "correct_answer": "长官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只长官一直在办公室里看报纸。", "explanation": "这里应该用〈位〉。长官指人，量词用“位”，不用“只”。"}, {"text": "他是我手下的长官，什么事都听我的。", "explanation": "这里误用了〈长官〉。长官地位比你高，“手下的人”地位比你低，应该用〈下属〉。"}, {"text": "我家的小狗是我的长官，每天管着我。", "explanation": "这里误用了〈长官〉。长官指地位高于你的人，不能指宠物，这里应该用〈主人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长官", "is_correct": true, "explanation": "长官：地位较高、管理下属的人，符合“我们都听……的安排”。"}, {"text": "顾客", "is_correct": false, "explanation": "搭配：顾客是购买服务的人，不会为“我们”做安排，不能与“听……的安排”搭配。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客无权为“我们”做安排，与“听……的安排”的权威关系不合。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人与我们没有管理关系，不会为我们做安排。"}], "explanations": {"长官": "长官：地位较高、管理下属的人，符合“我们都听……的安排”。", "顾客": "搭配：顾客是购买服务的人，不会为“我们”做安排，不能与“听……的安排”搭配。", "游客": "语义：游客无权为“我们”做安排，与“听……的安排”的权威关系不合。", "路人": "语义：路人与我们没有管理关系，不会为我们做安排。"}, "sentence_index": 6, "correct_answer": "长官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那头长官一直在办公室里批文件。", "explanation": "这里应该用〈位〉。长官指人，“头”只用于大型牲畜，不能修饰长官。"}, {"text": "我管着他，每天给他安排工作，所以他是我的长官。", "explanation": "这里误用了〈长官〉。长官是管着你的人，句中是你管着他，应该用〈下属〉。"}, {"text": "这条长官不肯说话，只顾看书。", "explanation": "这里应该用〈位〉。长官指人，“条”用于细长的物体，不能用来修饰人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我见了一只长官。", "corrected_sentence": "我见了一位长官。", "error_description": "量词错误：长官指人，应用量词“位”，不用“只”。“只”多用于动物或成对物品之一。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都听那只长官的安排。", "corrected_sentence": "我们都听那位长官的安排。", "error_description": "量词错误：长官指人，应用量词“位”，不用“只”。“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
