INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "行政或军队中职位较高的人员。", "primary_collocate": null, "pronunciation": "zhǎng guān", "ipa": "ʈʂɑŋ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "军队的长官检查了士兵的房间。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位长官在政府工作了三十年。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长官们在会议室讨论明天的计划。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有名的军队长官。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，长官要带士兵上前线。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府的长官来学校参观了。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一位长官都要遵守这个规定。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小兵一步步成了长官。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位长官穿着军装，站得很直。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告请交给长官。", "target_word": "长官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "長官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "行政或军队中的高级官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长官", "is_correct": true, "explanation": "长官：军队或行政中职位较高的人员，符合“军队的……检查了士兵的房间”。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不在军队中任职，不会检查军队士兵的房间。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不属于军队的管理层，不会检查士兵的房间。"}, {"text": "顾客", "is_correct": false, "explanation": "搭配：“军队的顾客”不是常见搭配，顾客也不负责检查房间。"}], "explanations": {"长官": "长官：军队或行政中职位较高的人员，符合“军队的……检查了士兵的房间”。", "农民": "语义：农民不在军队中任职，不会检查军队士兵的房间。", "学生": "语义：学生不属于军队的管理层，不会检查士兵的房间。", "顾客": "搭配：“军队的顾客”不是常见搭配，顾客也不负责检查房间。"}, "sentence_index": 0, "correct_answer": "长官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一只很有名的军队长官。", "explanation": "这里应该用〈位〉。长官指人，量词用“位”，不用“只”。"}, {"text": "他是我的长官，每天听我的安排。", "explanation": "这里应该用〈下属〉。长官职位高于你，而句中“听我的安排”说明对方接受你的指挥、职位较低，应该用〈下属〉。"}, {"text": "长官是军队里职位最低的人。", "explanation": "这里误用了〈长官〉。长官指职位较高的人员，职位最低的应该是〈士兵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长官", "is_correct": true, "explanation": "长官：指人，符合“每一位……都要遵守这个规定”的规定对象。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：量词“位”用于人，不能用于植物，“每一位植物”不成立。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不是人，不能用量词“位”修饰，也无法遵守规定。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不会遵守规定，与句意冲突。"}], "explanations": {"长官": "长官：指人，符合“每一位……都要遵守这个规定”的规定对象。", "植物": "搭配：量词“位”用于人，不能用于植物，“每一位植物”不成立。", "石头": "搭配：石头不是人，不能用量词“位”修饰，也无法遵守规定。", "窗户": "语义：窗户是无生命的物体，不会遵守规定，与句意冲突。"}, "sentence_index": 6, "correct_answer": "长官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报告请交给那只长官。", "explanation": "这里应该用〈位〉。长官指人，量词用“位”，不用“只”。"}, {"text": "报告请交给长官，他是昨天刚来的小兵。", "explanation": "这里误用了〈长官〉。长官职位较高，刚来的小兵职位最低，应该用〈士兵〉。"}, {"text": "报告请交给这棵树，它是长官。", "explanation": "这里误用了〈长官〉。长官指地位较高的人，不能用来指植物，这里的对象应换成〈人〉的称谓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几只长官来了。", "corrected_sentence": "几位长官来了。", "error_description": "量词错误：长官指人，应用量词“位”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都服从一只长官的命令。", "corrected_sentence": "我们都服从一位长官的命令。", "error_description": "量词错误：长官指人，应用量词“位”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闭市", "is_correct": true, "explanation": "闭市指商店或市场停止营业，与“开市”构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“开市”没有反义关系，与营业无关。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“开市”没有反义关系，不在同一语义范围内。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“开市”没有反义关系，不能作为其反义词。"}], "correct_answer": "闭市", "explanations": {"闭市": "闭市指商店或市场停止营业，与“开市”构成反义关系。", "唱歌": "“唱歌”与“开市”没有反义关系，与营业无关。", "游泳": "“游泳”与“开市”没有反义关系，不在同一语义范围内。", "写字": "“写字”与“开市”没有反义关系，不能作为其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
