INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "店铺或市场这一天开始做买卖。", "primary_collocate": null, "pronunciation": "kāi shì", "ipa": "kʰaɪ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "超市每天早上八点开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜市晚上六点才开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，早市比平时晚开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店中午十二点开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场还没开市，门口已经有人在等了。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末商店九点开市，平时八点。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说明天早点开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花市一开市，来买花的人就很多。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的店天一亮就开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼市几点开市？", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "店铺或市场每天开始营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开市", "is_correct": true, "explanation": "“开市”指超市每天开始营业，符合句意。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校或学期，超市不能开学。"}, {"text": "放学", "is_correct": false, "explanation": "语义：“放学”指学生放学，超市不能放学。"}, {"text": "退房", "is_correct": false, "explanation": "搭配：“退房”只用于住宿场所，超市不说退房。"}], "explanations": {"开市": "“开市”指超市每天开始营业，符合句意。", "开学": "搭配：“开学”只用于学校或学期，超市不能开学。", "放学": "语义：“放学”指学生放学，超市不能放学。", "退房": "搭配：“退房”只用于住宿场所，超市不说退房。"}, "sentence_index": 0, "correct_answer": "开市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议每天上午九点开市，参加的人都很准时。", "explanation": "这里应该用〈开会〉。开市只用于商店或市场，会议开始要说开会。"}, {"text": "学校每天早上七点开市，同学们都到了。", "explanation": "这里应该用〈开课〉。开市用于商店或市场的营业，学校上课开始要说开课。"}, {"text": "我每天早上八点开市，然后去上班。", "explanation": "这里应该用〈开工〉。开市的主语只能是商店或市场，个人每天开始上班要说开工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开市", "is_correct": true, "explanation": "“开市”指店铺开始营业，句中“明天早点”说明营业时间，符合句意。"}, {"text": "散场", "is_correct": false, "explanation": "语义：“散场”指演出或比赛结束，不能用于店铺。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指学生或老师结束课程，老板不能下课。"}, {"text": "开课", "is_correct": false, "explanation": "搭配：“开课”只用于学校或培训课程，不说店铺开课。"}], "explanations": {"开市": "“开市”指店铺开始营业，句中“明天早点”说明营业时间，符合句意。", "散场": "语义：“散场”指演出或比赛结束，不能用于店铺。", "下课": "语义：“下课”指学生或老师结束课程，老板不能下课。", "开课": "搭配：“开课”只用于学校或培训课程，不说店铺开课。"}, "sentence_index": 6, "correct_answer": "开市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台每天早上六点开市，播放新闻。", "explanation": "这里应该用〈开播〉。开市用于商店或市场，节目开始播出要说开播。"}, {"text": "法庭每天上午九点开市，法官准时到场。", "explanation": "这里应该用〈开庭〉。开市用于商店或市场的营业，法庭开始审理要说开庭。"}, {"text": "电影每天晚上七点开市，观众已经入场。", "explanation": "这里应该用〈开演〉。开市用于商店或市场，电影开始放映要说开演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店每天早上九点被开市，很多人都来买东西。", "corrected_sentence": "这家店每天早上九点开市，很多人都来买东西。", "error_description": "被字句误用：“开市”是不及物动词，不能加“被”，应说“每天早上九点开市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个鱼市每天早上五点就把开市。", "corrected_sentence": "这个鱼市每天早上五点就开市。", "error_description": "「开市」是不及物动词，不能用「把」字句，应说「就开市」，不能说「就把开市」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
