INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商店或市场开始营业；一年中首次开张。", "primary_collocate": null, "pronunciation": "kāi shì", "ipa": "kʰaɪ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "春节过后，这家商店今天开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节假期结束，市场明天开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年第一天，很多店铺都开市了。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正月初八，老街的店铺都开市了。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，年后店明天上午九点开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了元宵节，这条街的店铺才开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年期间商店不开市，要等到初六。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年第一天开市，店里来了很多客人。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过完年，市场还没有开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家老店初六就开市。", "target_word": "开市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "新年后商店或市场第一次开张营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开市", "is_correct": true, "explanation": "“开市”指商店或市场开始营业，符合句意。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校或学期，不能说商店开学。"}, {"text": "起床", "is_correct": false, "explanation": "语义：“起床”的主语只能是人，商店不能起床。"}, {"text": "下班", "is_correct": false, "explanation": "语义：商店没有“下班”，句中指营业开始，而不是结束工作。"}], "explanations": {"开市": "“开市”指商店或市场开始营业，符合句意。", "开学": "搭配：“开学”只用于学校或学期，不能说商店开学。", "起床": "语义：“起床”的主语只能是人，商店不能起床。", "下班": "语义：商店没有“下班”，句中指营业开始，而不是结束工作。"}, "sentence_index": 0, "correct_answer": "开市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这门新课下周一开市，欢迎大家来听。", "explanation": "这里应该用〈开课〉。开市只用于商店或市场，课程开始要说开课。"}, {"text": "这个画展明天开市，请大家准时参加。", "explanation": "这里应该用〈开幕〉。开市只用于商店或市场，画展开始要说开幕。"}, {"text": "这座图书馆每天早上九点开市，欢迎大家来看书。", "explanation": "这里应该用〈开馆〉。开市只用于商店或市场，图书馆开门要说开馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开市", "is_correct": true, "explanation": "“开市”指商店开始营业，句中“要等到初六”说明营业要延后，符合句意。"}, {"text": "放学", "is_correct": false, "explanation": "语义：“放学”指学生放学回家，商店不能放学。"}, {"text": "退房", "is_correct": false, "explanation": "搭配：“退房”只用于酒店等住宿场所，不说商店退房。"}, {"text": "散场", "is_correct": false, "explanation": "语义：“散场”指演出或比赛结束后人群离开，不能用于商店。"}], "explanations": {"开市": "“开市”指商店开始营业，句中“要等到初六”说明营业要延后，符合句意。", "放学": "语义：“放学”指学生放学回家，商店不能放学。", "退房": "搭配：“退房”只用于酒店等住宿场所，不说商店退房。", "散场": "语义：“散场”指演出或比赛结束后人群离开，不能用于商店。"}, "sentence_index": 6, "correct_answer": "开市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出下周一开市，欢迎大家来看。", "explanation": "这里应该用〈开演〉。开市只用于商店或市场，演出开始要说开演。"}, {"text": "这座博物馆下个月开市，欢迎大家参观。", "explanation": "这里应该用〈开馆〉。开市只用于商店或市场，博物馆开放要说开馆。"}, {"text": "这所小学下学期开市，新生已经报名了。", "explanation": "这里应该用〈开学〉。开市只用于商店或市场，学校开学要说开学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年后，这家店铺今天才把开市。", "corrected_sentence": "年后，这家店铺今天才开市。", "error_description": "「开市」是不及物动词，不能用「把」字句，应说「才开市」，不能说「才把开市」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节假期过后，这个市场今天就被开市了。", "corrected_sentence": "春节假期过后，这个市场今天就开市了。", "error_description": "被字句误用：“开市”是不及物动词，不能加“被”，应说“就开市了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
