INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96713, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "属于某个更大的地方或团体。", "primary_collocate": null, "pronunciation": "lì shǔ", "ipa": "li˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小镇隶属于北京市。", "target_word": "隶属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家医院隶属于市政府。", "target_word": "隶属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个研究所隶属中国科学院。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支球队隶属于一家大公司。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校隶属教育局。", "target_word": "隶属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个县隶属于四川省。", "target_word": "隶属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他工作的部门隶属财政部。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小岛隶属海南省。", "target_word": "隶属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家博物馆隶属于文化局。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小公司隶属于一个大集团。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隸屬", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "属于某个更大的地方或团体（归属）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属（lì shǔ）指从属于某个更大的地方或团体。"}, {"text": "隶书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同。隶书是一种汉字字体，意思不同。"}, {"text": "栗树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同。栗树指结栗子的树。"}, {"text": "梨树", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）、shù 与 shǔ 声调都不同。梨树指结梨的树。"}, {"text": "礼数", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。礼数指礼节和规矩。"}], "explanations": {"隶属": "正确。隶属（lì shǔ）指从属于某个更大的地方或团体。", "隶书": "shū（第一声）与 shǔ（第三声）声调不同。隶书是一种汉字字体，意思不同。", "栗树": "shù（第四声）与 shǔ（第三声）声调不同。栗树指结栗子的树。", "梨树": "lí（第二声）与 lì（第四声）、shù 与 shǔ 声调都不同。梨树指结梨的树。", "礼数": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。礼数指礼节和规矩。"}, "sentence_index": null, "correct_answer": "隶属"}, "level_3": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属表示小镇归北京市管辖，与“属于北京市”的意思一致。"}, {"text": "取决", "is_correct": false, "explanation": "语义：“取决于”表示由某事决定，小镇不能取决于北京市。"}, {"text": "致力", "is_correct": false, "explanation": "搭配：“致力于”后接事业、工作，不能接地名“北京市”。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业于”只用于人和学校，小镇不能毕业。"}], "explanations": {"隶属": "正确。隶属表示小镇归北京市管辖，与“属于北京市”的意思一致。", "取决": "语义：“取决于”表示由某事决定，小镇不能取决于北京市。", "致力": "搭配：“致力于”后接事业、工作，不能接地名“北京市”。", "毕业": "语义：“毕业于”只用于人和学校，小镇不能毕业。"}, "sentence_index": 0, "correct_answer": "隶属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份荣誉隶属于全体队员。", "explanation": "这里应该用〈属于〉。隶属只用于部门、机构等组织之间的管辖关系，荣誉是抽象的东西，不能说隶属。"}, {"text": "这套房子隶属于我父亲。", "explanation": "这里应该用〈属于〉。说房子归谁所有要用属于，隶属只用于组织之间的管辖关系。"}, {"text": "这座城市隶属于河边。", "explanation": "这里应该用〈位于〉。隶属表示管辖关系，说明地理位置要用位于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96713, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属（lì shǔ）指从属于某个更大的地方或团体。"}, {"text": "历书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同。历书指记载历法的书，意思不同。"}, {"text": "李树", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。李树指结李子的树。"}, {"text": "例数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同。例数指病例等的数量。"}], "explanations": {"隶属": "正确。隶属（lì shǔ）指从属于某个更大的地方或团体。", "历书": "shū（第一声）与 shǔ（第三声）声调不同。历书指记载历法的书，意思不同。", "李树": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。李树指结李子的树。", "例数": "shù（第四声）与 shǔ（第三声）声调不同。例数指病例等的数量。"}, "sentence_index": null, "correct_answer": "隶属"}, "level_3": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属表示他工作的部门归财政部管辖。"}, {"text": "领导", "is_correct": false, "explanation": "语义：“领导”是带领、指挥，部门不能领导财政部，与隶属关系的方向相反。"}, {"text": "担任", "is_correct": false, "explanation": "配价：“担任”后接的是职务，不能直接接“财政部”这样的机构名称。"}, {"text": "热爱", "is_correct": false, "explanation": "搭配：“热爱”的对象是事业、人或事物，不能说部门热爱财政部。"}], "explanations": {"隶属": "正确。隶属表示他工作的部门归财政部管辖。", "领导": "语义：“领导”是带领、指挥，部门不能领导财政部，与隶属关系的方向相反。", "担任": "配价：“担任”后接的是职务，不能直接接“财政部”这样的机构名称。", "热爱": "搭配：“热爱”的对象是事业、人或事物，不能说部门热爱财政部。"}, "sentence_index": 6, "correct_answer": "隶属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批货隶属于上海。", "explanation": "这里应该用〈来自〉。货物说明产地要用来自，隶属只用于组织之间的管辖关系。"}, {"text": "这只小狗隶属于主人。", "explanation": "这里应该用〈属于〉。说宠物归谁所有用属于，隶属只用于组织之间的管辖关系。"}, {"text": "这篇文章隶属于鲁迅。", "explanation": "这里应该用〈出自〉。说文章的作者要用出自，隶属只用于部门、机构等组织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个乡被隶属于云南省。", "corrected_sentence": "这个乡隶属于云南省。", "error_description": "“隶属”不能用“被”构成被动句，前面加“被”不通顺。应直接说“这个乡隶属于云南省”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家银行隶属给中国人民银行。", "corrected_sentence": "这家银行隶属于中国人民银行。", "error_description": "“隶属”后面应接介词“于”，写成“给”是误用，应说“隶属于中国人民银行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
