INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "从属；受管辖。", "primary_collocate": null, "pronunciation": "lì shǔ", "ipa": "li˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个机构直接隶属国务院，受它管理。", "target_word": "隶属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局隶属市政府，受市长领导。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个部门隶属总公司，不能自己做决定。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的队伍隶属第三军，由军长指挥。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂以前隶属于国家，现在是私人的了。", "target_word": "隶属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司隶属集团，重大事情都要报告集团。", "target_word": "隶属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关隶属中央，不受地方管理。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学院隶属教育部，由教育部管理。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "分公司隶属总部，每个月都要交报告。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小组隶属办公室，组长要听主任的。", "target_word": "隶属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隸屬", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "从属并受上级管辖（隶属关系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属（lì shǔ）指从属并受上级管辖。"}, {"text": "隶书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同。隶书是一种汉字字体，意思不同。"}, {"text": "栗树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同。栗树指结栗子的树。"}, {"text": "李树", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。李树指结李子的树。"}, {"text": "梨树", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）、shù 与 shǔ 声调都不同。梨树指结梨的树。"}], "explanations": {"隶属": "正确。隶属（lì shǔ）指从属并受上级管辖。", "隶书": "shū（第一声）与 shǔ（第三声）声调不同。隶书是一种汉字字体，意思不同。", "栗树": "shù（第四声）与 shǔ（第三声）声调不同。栗树指结栗子的树。", "李树": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。李树指结李子的树。", "梨树": "lí（第二声）与 lì（第四声）、shù 与 shǔ 声调都不同。梨树指结梨的树。"}, "sentence_index": null, "correct_answer": "隶属"}, "level_3": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属表示机构直接归国务院管辖，与后文“受它管理”一致。"}, {"text": "管理", "is_correct": false, "explanation": "语义：“管理”是管辖者对被管理者的行为，与后文“受它管理”相矛盾。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”与“受它管理”自相矛盾，机构不能既监督国务院又受它管理。"}, {"text": "设立", "is_correct": false, "explanation": "搭配：“设立”接的是新建的机构或制度，国务院是既有的最高国家机关，不能说“设立国务院”。"}], "explanations": {"隶属": "正确。隶属表示机构直接归国务院管辖，与后文“受它管理”一致。", "管理": "语义：“管理”是管辖者对被管理者的行为，与后文“受它管理”相矛盾。", "监督": "语义：“监督”与“受它管理”自相矛盾，机构不能既监督国务院又受它管理。", "设立": "搭配：“设立”接的是新建的机构或制度，国务院是既有的最高国家机关，不能说“设立国务院”。"}, "sentence_index": 0, "correct_answer": "隶属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长隶属于全校的老师。", "explanation": "这里应该用〈管理〉。隶属说的是下级归上级管辖，校长管理老师是管理与被管理的关系，不能说隶属。"}, {"text": "这家公司隶属于三座工厂。", "explanation": "这里应该用〈拥有〉。隶属表示下级归上级管辖，这里主语和宾语的关系颠倒了，应说“这家公司拥有三座工厂”。"}, {"text": "这颗星星隶属于科学家。", "explanation": "这里应该用〈属于〉。隶属只用于下级归上级管辖的组织关系，星星与科学家之间没有这种关系；说某物为谁所有可以用属于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96714, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属（lì shǔ）指从属并受上级管辖。"}, {"text": "历书", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同。历书指记载历法的书，意思不同。"}, {"text": "例数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同。例数指病例等的数量。"}, {"text": "礼数", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。礼数指礼节和规矩。"}], "explanations": {"隶属": "正确。隶属（lì shǔ）指从属并受上级管辖。", "历书": "shū（第一声）与 shǔ（第三声）声调不同。历书指记载历法的书，意思不同。", "例数": "shù（第四声）与 shǔ（第三声）声调不同。例数指病例等的数量。", "礼数": "lǐ（第三声）与 lì（第四声）、shù 与 shǔ 声调都不同。礼数指礼节和规矩。"}, "sentence_index": null, "correct_answer": "隶属"}, "level_3": {"options": [{"text": "隶属", "is_correct": true, "explanation": "正确。隶属表示海关归中央管辖，“不受地方管理”正是这一关系的体现。"}, {"text": "领导", "is_correct": false, "explanation": "语义：海关不能领导中央，“领导”表示带领、指挥，与隶属关系的方向相反。"}, {"text": "违抗", "is_correct": false, "explanation": "语义：“违抗”表示拒绝服从，海关隶属中央时不会违抗中央，与隶属关系相矛盾。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象通常是人的言行或工作，不能说海关批评中央。"}], "explanations": {"隶属": "正确。隶属表示海关归中央管辖，“不受地方管理”正是这一关系的体现。", "领导": "语义：海关不能领导中央，“领导”表示带领、指挥，与隶属关系的方向相反。", "违抗": "语义：“违抗”表示拒绝服从，海关隶属中央时不会违抗中央，与隶属关系相矛盾。", "批评": "搭配：“批评”的对象通常是人的言行或工作，不能说海关批评中央。"}, "sentence_index": 6, "correct_answer": "隶属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个病人隶属于那位护士。", "explanation": "这里应该用〈照顾〉。护士照顾病人是护理关系，不是组织之间的管辖，不能说隶属。"}, {"text": "这个孩子隶属于那对夫妇。", "explanation": "这里应该用〈是〉。亲子关系说“这个孩子是那对夫妇的”，隶属只用于组织之间的从属关系。"}, {"text": "他的画隶属于我。", "explanation": "这里应该用〈归〉。说画归谁所有可以说“他的画归我”，隶属只用于组织之间的管辖关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学院隶属与医科大学。", "corrected_sentence": "这个学院隶属于医科大学。", "error_description": "“隶属”后面的介词应为“于”，写成“与”是误用，应说“隶属于医科大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个分厂被隶属于总厂。", "corrected_sentence": "这个分厂隶属于总厂。", "error_description": "“隶属”前面加“被”不通顺，“隶属”不用于被动句。应说“这个分厂隶属于总厂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗俗", "is_correct": true, "explanation": "正确：粗俗与“雅”构成反义，指举止言谈粗野庸俗。"}, {"text": "结实", "is_correct": false, "explanation": "结实形容身体强壮或东西牢固，与“雅”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与“雅”的举止义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“雅”没有反义关系。"}], "correct_answer": "粗俗", "explanations": {"粗俗": "正确：粗俗与“雅”构成反义，指举止言谈粗野庸俗。", "结实": "结实形容身体强壮或东西牢固，与“雅”没有反义关系。", "迟钝": "迟钝形容反应慢，与“雅”的举止义没有反义关系。", "明亮": "明亮形容光线或颜色，与“雅”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗鲁", "is_correct": true, "explanation": "正确：粗鲁与“雅”构成反义，指言行举止野蛮、不文明。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重形容重量或心情，与“雅”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔形容空间面积，与“雅”没有反义关系。"}, {"text": "冰冷", "is_correct": false, "explanation": "冰冷形容温度或态度，与“雅”的举止义没有反义关系。"}], "correct_answer": "粗鲁", "explanations": {"粗鲁": "正确：粗鲁与“雅”构成反义，指言行举止野蛮、不文明。", "沉重": "沉重形容重量或心情，与“雅”没有反义关系。", "宽阔": "宽阔形容空间面积，与“雅”没有反义关系。", "冰冷": "冰冷形容温度或态度，与“雅”的举止义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "样子好看，有礼貌，不粗俗。", "primary_collocate": null, "pronunciation": "yǎ", "ipa": "ja˨˩˦", "syllable_count": 1, "sentences": [{"text": "她今天的站姿很雅，大家都夸她好看。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭时的样子很雅，一点声音也没有。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在客人面前，你坐着的样子要雅一点。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老先生说话轻声细语，举止很雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在饭桌上大声吵闹，一点也不雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走路的样子很雅，像跳舞一样。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当着老师的面，这样说话不太雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倒茶的动作很雅，手一点也不抖。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起大声笑，轻轻地笑更雅一些。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩走进教室时的样子很雅，动作很轻。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文雅", "label": "复合"}, {"form": "优雅", "label": "复合"}], "register": "书面", "sense_fingerprint": "举止样子好看有礼貌不粗俗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfc67122-5602-4672-be92-b592090b5833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：雅（yǎ），指样子好看、有礼貌、不粗俗。"}, {"text": "压", "is_correct": false, "explanation": "压（yā，第一声）与雅（yǎ，第三声）声调不同，意思是用力向下按。"}, {"text": "牙", "is_correct": false, "explanation": "牙（yá，第二声）与雅（yǎ，第三声）声调不同，意思是牙齿。"}, {"text": "眼", "is_correct": false, "explanation": "眼（yǎn）与雅（yǎ）韵母不同，雅是 a，眼是 an，意思是眼睛。"}, {"text": "鸭", "is_correct": false, "explanation": "鸭（yā，第一声）与雅（yǎ，第三声）声调不同，意思是鸭子。"}], "explanations": {"雅": "正确：雅（yǎ），指样子好看、有礼貌、不粗俗。", "压": "压（yā，第一声）与雅（yǎ，第三声）声调不同，意思是用力向下按。", "牙": "牙（yá，第二声）与雅（yǎ，第三声）声调不同，意思是牙齿。", "眼": "眼（yǎn）与雅（yǎ）韵母不同，雅是 a，眼是 an，意思是眼睛。", "鸭": "鸭（yā，第一声）与雅（yǎ，第三声）声调不同，意思是鸭子。"}, "sentence_index": null, "correct_answer": "雅"}, "level_3": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：“雅”形容站姿好看、有礼貌，与后句“大家都夸她好看”一致。"}, {"text": "难看", "is_correct": false, "explanation": "语义：“难看”与后句“大家都夸她好看”矛盾。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”形容身体或体型，不用来形容站姿。"}, {"text": "土", "is_correct": false, "explanation": "语域：“土”是口语，与书面语体的“雅”不一致，且与“夸她好看”矛盾。"}], "explanations": {"雅": "正确：“雅”形容站姿好看、有礼貌，与后句“大家都夸她好看”一致。", "难看": "语义：“难看”与后句“大家都夸她好看”矛盾。", "粗壮": "搭配：“粗壮”形容身体或体型，不用来形容站姿。", "土": "语域：“土”是口语，与书面语体的“雅”不一致，且与“夸她好看”矛盾。"}, "sentence_index": 0, "correct_answer": "雅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在街上对着路人大声吼叫，样子很雅。", "explanation": "这里应该用〈粗俗〉。“雅”指样子好看、不粗俗，对路人大声吼叫的样子要用“粗俗”来形容。"}, {"text": "他吃饭时吧唧嘴，还把骨头吐在地上，样子很雅。", "explanation": "这里应该用〈难看〉。“雅”指举止好看、有礼貌，吃饭吧唧嘴、乱吐骨头的样子要用“难看”来形容。"}, {"text": "他说话很雅，张口就是脏话。", "explanation": "这里应该用〈粗鲁〉。“雅”形容举止文明、不粗俗，张口就说脏话要用“粗鲁”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：雅（yǎ），指样子好看、有礼貌、不粗俗。"}, {"text": "亚", "is_correct": false, "explanation": "亚（yà，第四声）与雅（yǎ，第三声）声调不同，意思是次一等、亚洲。"}, {"text": "演", "is_correct": false, "explanation": "演（yǎn）与雅（yǎ）韵母不同，雅是 a，演是 an，意思是表演。"}, {"text": "押", "is_correct": false, "explanation": "押（yā，第一声）与雅（yǎ，第三声）声调不同，意思是抵押、按压。"}, {"text": "养", "is_correct": false, "explanation": "养（yǎng）与雅（yǎ）韵母不同，雅是 a，养是 ang，意思是饲养。"}], "explanations": {"雅": "正确：雅（yǎ），指样子好看、有礼貌、不粗俗。", "亚": "亚（yà，第四声）与雅（yǎ，第三声）声调不同，意思是次一等、亚洲。", "演": "演（yǎn）与雅（yǎ）韵母不同，雅是 a，演是 an，意思是表演。", "押": "押（yā，第一声）与雅（yǎ，第三声）声调不同，意思是抵押、按压。", "养": "养（yǎng）与雅（yǎ）韵母不同，雅是 a，养是 ang，意思是饲养。"}, "sentence_index": null, "correct_answer": "雅"}, "level_3": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：“雅”形容说话的样子文雅，与“当着老师的面”的语境相符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人的体型，不能用来形容说话。"}, {"text": "方", "is_correct": false, "explanation": "搭配：“方”形容形状，不能用来形容说话。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容宽度或空间，不用来形容说话的样子。"}], "explanations": {"雅": "正确：“雅”形容说话的样子文雅，与“当着老师的面”的语境相符。", "胖": "体貌：“胖”形容人的体型，不能用来形容说话。", "方": "搭配：“方”形容形状，不能用来形容说话。", "窄": "搭配：“窄”形容宽度或空间，不用来形容说话的样子。"}, "sentence_index": 6, "correct_answer": "雅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他进门后把脚往桌上一搭，样子很雅。", "explanation": "这里应该用〈失礼〉。“雅”形容举止文明、有礼貌，把脚搭在桌上的样子要用“失礼”来形容。"}, {"text": "他穿着破旧的衣服，满脸油污，样子很雅。", "explanation": "这里应该用〈邋遢〉。“雅”形容样子好看、有礼貌，衣衫破旧、满脸油污要用“邋遢”来形容。"}, {"text": "那个女孩大声喊叫着走进教室，样子很雅。", "explanation": "这里应该用〈吵闹〉。“雅”形容举止文明，大声喊叫着走进教室的样子要用“吵闹”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她吃饭的样子雅很，从不出声。", "corrected_sentence": "她吃饭的样子很雅，从不出声。", "error_description": "语序错误：程度副词“很”应放在“雅”前面，说“很雅”，不能说“雅很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话说很雅，大家都夸她。", "corrected_sentence": "她说话说得很雅，大家都夸她。", "error_description": "“得”脱落：“说话”之后的补语“很雅”需要用“得”连接，应说“说得很雅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
