INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个茶馆的名字雅很，大家都记得住。", "corrected_sentence": "这个茶馆的名字很雅，大家都记得住。", "error_description": "语序错误：程度副词“很”应放在“雅”前面，说“很雅”，不能说“雅很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
