INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96722, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "趁做某事的方便做另一件事。", "primary_collocate": null, "pronunciation": "shùn biàn", "ipa": "ʂuən˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我去超市，顺便买了一瓶水。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你回家的时候，顺便把信寄了吧。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去北京开会，顺便看了看老朋友。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门时请顺便关灯。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去银行取钱，顺便问了问利率。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班回家，我顺便去了菜市场。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去图书馆的话，顺便帮我还本书。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来我家玩，顺便带了一些水果。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去邮局寄信，顺便买了几张邮票。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师去教室，顺便把窗户打开了。", "target_word": "顺便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "順便", "label": "繁体"}], "register": "口语", "sense_fingerprint": "副词；趁着做某事方便，捎带做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顺便", "is_correct": true, "explanation": "正确答案。顺便（shùn biàn）：趁做某事的方便做另一件事。"}, {"text": "善变", "is_correct": false, "explanation": "shàn 与 shùn 只差元音（a 与 u），声调相同；意思是性情或想法变化快，不是顺便。"}, {"text": "身边", "is_correct": false, "explanation": "shēn（第一声）与 shùn（第四声）元音不同，biān（第一声）与 biàn（第四声）声调不同；意思是身旁、身边。"}, {"text": "水边", "is_correct": false, "explanation": "shuǐ（第三声）与 shùn（第四声）只差韵尾（ei 与 en）和声调，biān 与 biàn 声调不同；意思是水的旁边。"}, {"text": "山边", "is_correct": false, "explanation": "shān（第一声）与 shùn（第四声）元音和声调不同，biān 与 biàn 声调不同；意思是山的旁边。"}], "explanations": {"顺便": "正确答案。顺便（shùn biàn）：趁做某事的方便做另一件事。", "善变": "shàn 与 shùn 只差元音（a 与 u），声调相同；意思是性情或想法变化快，不是顺便。", "身边": "shēn（第一声）与 shùn（第四声）元音不同，biān（第一声）与 biàn（第四声）声调不同；意思是身旁、身边。", "水边": "shuǐ（第三声）与 shùn（第四声）只差韵尾（ei 与 en）和声调，biān 与 biàn 声调不同；意思是水的旁边。", "山边": "shān（第一声）与 shùn（第四声）元音和声调不同，biān 与 biàn 声调不同；意思是山的旁边。"}, "sentence_index": null, "correct_answer": "顺便"}, "level_3": {"options": [{"text": "顺便", "is_correct": true, "explanation": "正确答案。“顺便”表示趁去超市的方便，顺带买了一瓶水。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，句中去超市买水并不意外，用“竟然”语义不通。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文没有需要转折的预期，句子不需要这个转折。"}, {"text": "何必", "is_correct": false, "explanation": "语法：“何必”用于反问，表示没有必要，“我去超市，何必买了一瓶水”不成句。"}], "explanations": {"顺便": "正确答案。“顺便”表示趁去超市的方便，顺带买了一瓶水。", "竟然": "语义：“竟然”表示出乎意料，句中去超市买水并不意外，用“竟然”语义不通。", "却": "语义：“却”表示转折，前文没有需要转折的预期，句子不需要这个转折。", "何必": "语法：“何必”用于反问，表示没有必要，“我去超市，何必买了一瓶水”不成句。"}, "sentence_index": 0, "correct_answer": "顺便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去超市，顺便盖了一座房子。", "explanation": "这里应该用〈专门〉。顺便只用于顺带做的小事，盖房子是大事，要专门去做。"}, {"text": "他顺便爱上了我。", "explanation": "这里应该用〈慢慢〉。顺便表示有意顺带做的小事，爱上一个人是慢慢形成的，不能说顺便。"}, {"text": "我顺便把杯子打碎了。", "explanation": "这里应该用〈不小心〉。顺便表示有意顺带做的小事，不能用来说意外发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺便", "is_correct": true, "explanation": "正确答案。“顺便”表示顺带帮忙还书，与“你去图书馆的话”这个条件搭配。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“你去图书馆的话”这个将来的条件冲突。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示再次发生，句中没有再次的前提，用“又”说“帮我还书”不通。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与期望相反或出人意料，句中没有这样的对比，用它不合语境。"}], "explanations": {"顺便": "正确答案。“顺便”表示顺带帮忙还书，与“你去图书馆的话”这个条件搭配。", "已经": "体貌：“已经”表示动作已经完成，与“你去图书馆的话”这个将来的条件冲突。", "又": "语义：“又”表示再次发生，句中没有再次的前提，用“又”说“帮我还书”不通。", "偏偏": "语义：“偏偏”表示与期望相反或出人意料，句中没有这样的对比，用它不合语境。"}, "sentence_index": 6, "correct_answer": "顺便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他顺便迟到了。", "explanation": "这里应该用〈又〉。顺便表示有意趁便做另一件事，迟到不是趁便去做的事，不能用顺便。"}, {"text": "我顺便从上海飞来看你。", "explanation": "这里应该用〈特地〉。从上海飞来看你是主要目的，不是顺带做的小事，所以不能用顺便。"}, {"text": "他顺便考上了大学。", "explanation": "这里应该用〈终于〉。顺便只表示趁便做的小事，考上大学要经过长期努力，不能说顺便。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去书店，顺便的买了一本杂志。", "corrected_sentence": "我去书店，顺便买了一本杂志。", "error_description": "错误在“顺便”后多出了“的”。“顺便”是副词，直接修饰后面的动词，不能加“的”，应说“顺便买了一本杂志”；加上“的”后“顺便的买了”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下楼取快递，顺便的带了一杯咖啡上来。", "corrected_sentence": "我下楼取快递，顺便带了一杯咖啡上来。", "error_description": "错误在“顺便”后多出了“的”。“顺便”是副词，直接修饰“带”，不能加“的”，应说“顺便带了一杯咖啡上来”；“顺便的带了”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
