INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "账户中扣除支出后剩余的金额。", "primary_collocate": null, "pronunciation": "yú é", "ipa": "y˧˥ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我的银行卡余额不多了。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先查一下账户余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上可以看到卡里的余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的账户余额不足，不能付款。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买完东西以后，账户余额只有五十元。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张公交卡的余额是二十块。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都看一下支付宝余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的账户余额有一万多元。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "余额不足时，手机会提醒你充钱。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这个月银行账户的余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "账户余额", "label": "复合词"}, {"form": "余额不足", "label": "复合词"}, {"form": "餘額", "label": "繁体"}], "register": "中性", "sense_fingerprint": "银行卡、账户等扣除支出后剩下的金额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafe1b09-91b9-4c69-99c2-755cd2b95889') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余额", "is_correct": true, "explanation": "余额：账户里扣除支出后剩下的钱，与“银行卡余额不多了”相符。"}, {"text": "密码", "is_correct": false, "explanation": "搭配：“密码”不是可以多少的东西，不能说“不多了”。"}, {"text": "利率", "is_correct": false, "explanation": "搭配：“利率”只能说高低，不能说“不多了”。"}, {"text": "卡号", "is_correct": false, "explanation": "语义：卡号是一串数字，不表示钱的数量，与“不多了”不符。"}], "explanations": {"余额": "余额：账户里扣除支出后剩下的钱，与“银行卡余额不多了”相符。", "密码": "搭配：“密码”不是可以多少的东西，不能说“不多了”。", "利率": "搭配：“利率”只能说高低，不能说“不多了”。", "卡号": "语义：卡号是一串数字，不表示钱的数量，与“不多了”不符。"}, "sentence_index": 0, "correct_answer": "余额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的余额是五百元。", "explanation": "这里应该用〈价格〉。余额是钱用了以后剩下的钱，商品的标价要说价格。"}, {"text": "我还没有付款，这笔转账的余额就是五百元。", "explanation": "这里应该用〈金额〉。余额指扣除后剩下的钱，转账的数目要用金额。"}, {"text": "我给了司机两百元余额。", "explanation": "这里应该用〈小费〉。余额是钱用了以后剩下的钱，额外给司机的赏钱要说小费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余额", "is_correct": true, "explanation": "余额：账户里的剩余金额，可以在支付宝上查看，与“看一下支付宝”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体高度，不是能在支付宝上看的内容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的重量，支付宝上查不到。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不是可以在支付宝里“看一下”的数据。"}], "explanations": {"余额": "余额：账户里的剩余金额，可以在支付宝上查看，与“看一下支付宝”相符。", "身高": "语义：身高是人的身体高度，不是能在支付宝上看的内容。", "体重": "语义：体重是人的重量，支付宝上查不到。", "年龄": "搭配：“年龄”不是可以在支付宝里“看一下”的数据。"}, "sentence_index": 6, "correct_answer": "余额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "余额请我们吃了一顿饭。", "explanation": "这里应该用〈他〉作主语。余额是账户里剩下的钱，不是人，不能做“请客”的动作。"}, {"text": "这场比赛的余额是两分。", "explanation": "这里应该用〈分差〉。余额只指扣除后剩下的钱，比赛的分数差距要用分差。"}, {"text": "我去余额买了一顶帽子。", "explanation": "这里应该用〈商场〉。余额是数额，不是地方，不能用“去”连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的银行卡余额已经不多钱了。", "corrected_sentence": "我的银行卡余额已经不多了。", "error_description": "错误：“余额不多钱了”。正确：“余额不多了”。“余额”本身就是钱数，直接说“不多”，不能再加“钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我的账户余额只花三百元。", "corrected_sentence": "这个月我的账户余额只剩三百元。", "error_description": "错误：“余额只花三百元”。正确：“余额只剩三百元”。余额是扣除支出后剩下的钱，要说“剩”，不能说“花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
