INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96741, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指按一下手机，或者用鼠标按一下。", "primary_collocate": null, "pronunciation": "diǎn jī", "ipa": "tjɛn˨˩˦ tɕi˥˥", "syllable_count": 2, "sentences": [{"text": "请点击这个红色的按钮。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指点击了手机屏幕。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你点击一下这里就可以了。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心点击了那个广告。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先点击鼠标左键，再往下看。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈点击了屏幕上的小图片。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击这个小图片可以看大的。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子点击过电脑上的这个游戏。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用鼠标点击了“下一页”。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击屏幕，手机就会亮。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点击了", "label": "体标"}, {"form": "点击过", "label": "体标"}, {"form": "点击着", "label": "体标"}, {"form": "点击量", "label": "复合"}, {"form": "点击率", "label": "复合"}, {"form": "點擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手指或鼠标按一下屏幕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点击", "is_correct": true, "explanation": "点击：用手指或鼠标按一下屏幕，选中某个对象。"}, {"text": "电击", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，意思是电击，指电流的打击。"}, {"text": "典籍", "is_correct": false, "explanation": "diǎn jí（典籍）与 diǎn jī 只有第二个字声调不同（第二声与第一声），意思是古代的书籍。"}, {"text": "电机", "is_correct": false, "explanation": "diàn jī（电机）与 diǎn jī 只有第一个字声调不同（第四声与第三声），意思是电动机。"}], "explanations": {"点击": "点击：用手指或鼠标按一下屏幕，选中某个对象。", "电击": "diàn（第四声）与 diǎn（第三声）声调不同，意思是电击，指电流的打击。", "典籍": "diǎn jí（典籍）与 diǎn jī 只有第二个字声调不同（第二声与第一声），意思是古代的书籍。", "电机": "diàn jī（电机）与 diǎn jī 只有第一个字声调不同（第四声与第三声），意思是电动机。"}, "sentence_index": null, "correct_answer": "点击"}, "level_3": {"options": [{"text": "点击", "is_correct": true, "explanation": "语境：“请……这个红色的按钮”，要求用手指或鼠标按一下按钮，符合点击的意思。"}, {"text": "拨打", "is_correct": false, "explanation": "搭配：“拨打”用于电话号码，不能用于按钮。"}, {"text": "摇晃", "is_correct": false, "explanation": "语义：“摇晃”是来回晃动，与按按钮的动作不符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是用力打碎，请人去砸红色按钮，句意不合。"}], "explanations": {"点击": "语境：“请……这个红色的按钮”，要求用手指或鼠标按一下按钮，符合点击的意思。", "拨打": "搭配：“拨打”用于电话号码，不能用于按钮。", "摇晃": "语义：“摇晃”是来回晃动，与按按钮的动作不符。", "砸": "语义：“砸”是用力打碎，请人去砸红色按钮，句意不合。"}, "sentence_index": 0, "correct_answer": "点击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子轻轻点击了小猫的背。", "explanation": "这里应该用〈触摸〉。点击指按屏幕或按键来选中对象，不能用来碰小猫。"}, {"text": "他点击了三下桌子。", "explanation": "这里应该用〈敲〉。点击用于屏幕或按键，不能用来敲桌子。"}, {"text": "妈妈点击了我的肩膀。", "explanation": "这里应该用〈拍〉。点击用于屏幕或按键，不能用来拍肩膀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点击", "is_correct": true, "explanation": "语境：“……这个小图片可以看大的”，点击图片才能打开大图，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去污渍，不能用来看大图，句意不合。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是把东西扯破，撕掉小图片不能看大图。"}, {"text": "眨", "is_correct": false, "explanation": "搭配：“眨”的动作对象是眼睛，不能用于图片。"}], "explanations": {"点击": "语境：“……这个小图片可以看大的”，点击图片才能打开大图，符合句意。", "擦": "语义：擦是抹去污渍，不能用来看大图，句意不合。", "撕": "语义：撕是把东西扯破，撕掉小图片不能看大图。", "眨": "搭配：“眨”的动作对象是眼睛，不能用于图片。"}, "sentence_index": 6, "correct_answer": "点击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈轻轻点击了孩子的脸。", "explanation": "这里应该用〈摸〉。点击只用于屏幕或按键选中对象，不能用来摸孩子的脸。"}, {"text": "他点击了发红的眼睛。", "explanation": "这里应该用〈揉〉。点击不能用于眼睛，揉眼睛是用手轻轻搓。"}, {"text": "他点击了一下自己的脚趾，疼得叫了起来。", "explanation": "这里应该用〈碰〉。点击用于屏幕或按键选中对象，不能用来碰脚趾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用鼠标点击起了那个文件夹。", "corrected_sentence": "妈妈用鼠标点击了那个文件夹。", "error_description": "“点击”后不能接“起”作补语。直接说“点击了”即可，“点击起”不是常用说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前点击了过那个按钮。", "corrected_sentence": "我以前点击过那个按钮。", "error_description": "“点击”后的“了”与“过”不能同时出现。表示曾经做过时只说“点击过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
