INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用鼠标或手指轻按屏幕或按键，选中某个对象。", "primary_collocate": null, "pronunciation": "diǎn jī", "ipa": "tjɛn˨˩˦ tɕi˥˥", "syllable_count": 2, "sentences": [{"text": "点击你要用的名字，然后再发送。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先点击文件，再点击“打开”。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点击了第一个选项。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里点击你喜欢的照片。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手指点击要买的东西，再付钱。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你点击过那个链接吗？", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点击了“取消”，文件没有发出去。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击一个图标，手机里的游戏就开了。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用鼠标点击了那个图标。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想选这张图，请点击它。", "target_word": "点击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点击了", "label": "体标"}, {"form": "点击过", "label": "体标"}, {"form": "点击着", "label": "体标"}, {"form": "点击量", "label": "复合"}, {"form": "点击率", "label": "复合"}, {"form": "點擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按一下选中屏幕上的某个对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点击", "is_correct": true, "explanation": "语境：“……你要用的名字，然后再发送”，按一下名字才能选中它，符合点击的意思。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象是人或物的表面，不能拍名字。"}, {"text": "吃", "is_correct": false, "explanation": "语义：名字不能被吃，与“然后再发送”的语境不合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是扔到地上，与选中名字的操作不符。"}], "explanations": {"点击": "语境：“……你要用的名字，然后再发送”，按一下名字才能选中它，符合点击的意思。", "拍": "搭配：“拍”的对象是人或物的表面，不能拍名字。", "吃": "语义：名字不能被吃，与“然后再发送”的语境不合。", "摔": "语义：摔是扔到地上，与选中名字的操作不符。"}, "sentence_index": 0, "correct_answer": "点击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手点击了一下墙，手都红了。", "explanation": "这里应该用〈敲〉。点击用于屏幕或按键，不能用来敲墙。"}, {"text": "他用布点击了桌子。", "explanation": "这里应该用〈擦〉。点击只用于按屏幕或按键选中对象，不能用来擦桌子。"}, {"text": "他用勺子点击了碗里的汤。", "explanation": "这里应该用〈搅〉。点击用于屏幕或按键选中对象，不能用来搅汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点击", "is_correct": true, "explanation": "语境：“我……了“取消”，文件没有发出去”，按一下“取消”按钮，符合句意。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”后接的是文件或文字，不能接按钮名称“取消”。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是扯破，不能用来操作按钮。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是讥讽别人，与操作按钮的语境完全不合。"}], "explanations": {"点击": "语境：“我……了“取消”，文件没有发出去”，按一下“取消”按钮，符合句意。", "删除": "搭配：“删除”后接的是文件或文字，不能接按钮名称“取消”。", "撕": "语义：撕是扯破，不能用来操作按钮。", "嘲笑": "语义：嘲笑是讥讽别人，与操作按钮的语境完全不合。"}, "sentence_index": 6, "correct_answer": "点击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他点击了那只蚊子，它却没死。", "explanation": "这里应该用〈拍〉。点击用于屏幕或按键选中对象，不能用来拍蚊子。"}, {"text": "他点击了一下那箱子，箱子却纹丝不动。", "explanation": "这里应该用〈推〉。点击用于屏幕或按键，不能用来推箱子。"}, {"text": "他点击了那只球，它就滚到了桌子底下。", "explanation": "这里应该用〈踢〉。点击只用于屏幕或按键选中对象，不能用来踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用手指点击得那张照片。", "corrected_sentence": "我用手指点击了那张照片。", "error_description": "“点击”后面要用“了”表示动作已经完成，不能用结构助词“得”。错误句是“点击得那张照片”，正确句是“点击了那张照片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我点击的了那个按钮。", "corrected_sentence": "我点击了那个按钮。", "error_description": "“点击”后不能直接加结构助词“的”，“点击的了”不成立，应说“点击了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
