INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "慢慢地往下去，变少或者变差。", "primary_collocate": null, "pronunciation": "xià huá", "ipa": "ɕja˥˩ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "今年他的成绩一直在下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的生意慢慢下滑了。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近银行的利率在下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后，球队的水平开始下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月公司的收入明显下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体状况一年比一年下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，我的睡眠质量下滑了。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机销量连续三个月下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的服务质量下滑得很快。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的价格从去年开始下滑。", "target_word": "下滑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下滑了", "label": "完成体"}, {"form": "下滑过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词；成绩、销量、水平等逐渐变差或减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下滑", "is_correct": true, "explanation": "正确答案。下滑（xià huá）：慢慢地往下去，变少或变差。"}, {"text": "虾滑", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，huá 相同；意思是用虾肉做的丸子，常见于火锅。"}, {"text": "瞎话", "is_correct": false, "explanation": "xiā（第一声）与 xià 声调不同，huà（第四声）与 huá（第二声）声调不同；意思是假话、谎话。"}, {"text": "夏花", "is_correct": false, "explanation": "xià 相同，huā（第一声）与 huá（第二声）声调不同；意思是夏天开的花。"}], "explanations": {"下滑": "正确答案。下滑（xià huá）：慢慢地往下去，变少或变差。", "虾滑": "xiā（第一声）与 xià（第四声）声调不同，huá 相同；意思是用虾肉做的丸子，常见于火锅。", "瞎话": "xiā（第一声）与 xià 声调不同，huà（第四声）与 huá（第二声）声调不同；意思是假话、谎话。", "夏花": "xià 相同，huā（第一声）与 huá（第二声）声调不同；意思是夏天开的花。"}, "sentence_index": null, "correct_answer": "下滑"}, "level_3": {"options": [{"text": "下滑", "is_correct": true, "explanation": "正确答案。“下滑”表示成绩逐渐变差，与“一直在”搭配。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”指温度下降，不用于形容成绩变差。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指飞机、伞等从高处落到地面，不能形容成绩的逐渐变差。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人离开工作岗位，不能说成绩退休。"}], "explanations": {"下滑": "正确答案。“下滑”表示成绩逐渐变差，与“一直在”搭配。", "降温": "搭配：“降温”指温度下降，不用于形容成绩变差。", "降落": "语义：“降落”指飞机、伞等从高处落到地面，不能形容成绩的逐渐变差。", "退休": "语义：“退休”指人离开工作岗位，不能说成绩退休。"}, "sentence_index": 0, "correct_answer": "下滑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的生意慢慢下滑，最近越来越红火。", "explanation": "这里应该用〈上升〉。下滑指逐渐变少或变差，与“越来越红火”的意思相反，说生意逐渐变好要用上升。"}, {"text": "球队的排名下滑到了第一名。", "explanation": "这里应该用〈升至〉。下滑指逐渐变差，排名升到第一名是变好，不能用下滑。"}, {"text": "他的身体状况一年比一年下滑，现在比以前结实多了。", "explanation": "这里应该用〈好转〉。下滑指逐渐变差，与“结实多了”的意思相反，说身体逐渐变好要用好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下滑", "is_correct": true, "explanation": "正确答案。“下滑”表示睡眠质量变差，与“工作太忙”的原因相符。"}, {"text": "上升", "is_correct": false, "explanation": "语义：“上升”与“工作太忙”的语境相反，句子会说成睡眠质量变好，前后不一致。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”用于数量，“睡眠质量”是质量，不能说增加。"}, {"text": "上涨", "is_correct": false, "explanation": "搭配：“上涨”多用于价格、水位，不说睡眠质量上涨。"}], "explanations": {"下滑": "正确答案。“下滑”表示睡眠质量变差，与“工作太忙”的原因相符。", "上升": "语义：“上升”与“工作太忙”的语境相反，句子会说成睡眠质量变好，前后不一致。", "增加": "搭配：“增加”用于数量，“睡眠质量”是质量，不能说增加。", "上涨": "搭配：“上涨”多用于价格、水位，不说睡眠质量上涨。"}, "sentence_index": 6, "correct_answer": "下滑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩一直下滑，这次考了全班第一。", "explanation": "这里应该用〈提高〉。下滑指逐渐变差，考第一说明成绩变好，不能用下滑。"}, {"text": "公司的收入下滑了，大家都很高兴赚了更多钱。", "explanation": "这里应该用〈增加〉。下滑指变少，赚了更多钱是收入增加，与下滑相反。"}, {"text": "经过努力，他的汉语水平下滑了很多，说得越来越流利。", "explanation": "这里应该用〈提高〉。下滑指水平变差，说得越来越流利是变好，不能用下滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的生意下滑地很快。", "corrected_sentence": "这家店的生意下滑得很快。", "error_description": "错误在补语的结构助词。“下滑”后面接补语，要用“得”连接，应说“下滑得很快”；用“地”（用于状语后）不对，“下滑地很快”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店的客流量最近很下滑了。", "corrected_sentence": "这家饭店的客流量最近下滑了。", "error_description": "错误在程度副词“很”。“很”不能直接修饰动词“下滑”，“很下滑了”不通，应去掉“很”，说“最近下滑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”与“不如别人”相反，是反义词。"}, {"text": "研究", "is_correct": false, "explanation": "无关系：“研究”表示探讨，与“不及”的反义词无关。"}, {"text": "讨论", "is_correct": false, "explanation": "无关系：“讨论”表示交换意见，与“不及”没有反义关系。"}, {"text": "模仿", "is_correct": false, "explanation": "无关系：“模仿”表示照样做，与“不及”没有反义关系。"}], "correct_answer": "超过", "explanations": {"超过": "正确：“超过”与“不如别人”相反，是反义词。", "研究": "无关系：“研究”表示探讨，与“不及”的反义词无关。", "讨论": "无关系：“讨论”表示交换意见，与“不及”没有反义关系。", "模仿": "无关系：“模仿”表示照样做，与“不及”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”与“不如别人”相反，是反义词。"}, {"text": "观察", "is_correct": false, "explanation": "无关系：“观察”表示仔细看，与“不及”没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "无关系：“批评”表示指出错误，与“不及”没有反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "无关系：“提醒”表示让人注意，与“不及”没有反义关系。"}], "correct_answer": "超过", "explanations": {"超过": "正确：“超过”与“不如别人”相反，是反义词。", "观察": "无关系：“观察”表示仔细看，与“不及”没有反义关系。", "批评": "无关系：“批评”表示指出错误，与“不及”没有反义关系。", "提醒": "无关系：“提醒”表示让人注意，与“不及”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有别人那样好，或者比不上。", "primary_collocate": null, "pronunciation": "bù jí", "ipa": "pu˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我的英语不及同学，要多努力。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论经验，我们都不及老王。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌不及妹妹，但跳舞很好。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的成绩不及上次，我有点难过。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自己觉得不及别人，所以不爱说话。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小城的热闹不及大城市，但是更安静。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我做饭不及妈妈，只会做简单的菜。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台旧电脑不及新电脑，速度慢多了。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法的效果不及那个办法，我们换一个吧。", "target_word": "不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的服务不及以前，客人越来越少。", "target_word": "不及", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "水平、程度等没有别人或以前那样好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不及", "is_correct": true, "explanation": "正确答案：不及（bù jí），听到的就是这个词。"}, {"text": "不计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，“不计”意思是不把……放在心上。"}, {"text": "不齐", "is_correct": false, "explanation": "qí 与 jí 只差声母（q/j），声调相同，“不齐”意思是参差不齐。"}, {"text": "布局", "is_correct": false, "explanation": "jú 与 jí 只差韵母（u/i），声调相同，“布局”意思是安排布置。"}], "explanations": {"不及": "正确答案：不及（bù jí），听到的就是这个词。", "不计": "jì（第四声）与 jí（第二声）声调不同，“不计”意思是不把……放在心上。", "不齐": "qí 与 jí 只差声母（q/j），声调相同，“不齐”意思是参差不齐。", "布局": "jú 与 jí 只差韵母（u/i），声调相同，“布局”意思是安排布置。"}, "sentence_index": null, "correct_answer": "不及"}, "level_3": {"options": [{"text": "不及", "is_correct": true, "explanation": "正确：“不及”表示水平不如别人，符合“同学”的比较。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示忘掉，与“英语不如同学”的评价不符。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”不能用来表示“英语”和“同学”的水平比较。"}, {"text": "担心", "is_correct": false, "explanation": "语义：“担心”表示忧虑，与“要多努力”的勉励语气不合。"}], "explanations": {"不及": "正确：“不及”表示水平不如别人，符合“同学”的比较。", "忘记": "语义：“忘记”表示忘掉，与“英语不如同学”的评价不符。", "讲": "搭配：“讲”不能用来表示“英语”和“同学”的水平比较。", "担心": "语义：“担心”表示忧虑，与“要多努力”的勉励语气不合。"}, "sentence_index": 0, "correct_answer": "不及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这么热，我们不及休息吧。", "explanation": "这里应该用〈不如〉。“不如……吧”表示提建议，“不及”不能用来提建议。"}, {"text": "他跑步不及我，比我快多了。", "explanation": "这里应该用〈胜过〉。“不及”表示比不上，与“比我快多了”意思相反，应说“胜过”。"}, {"text": "我的作业还不及写完，老师就来收了。", "explanation": "这里应该用〈没来得及〉。时间不够要说“没来得及写完”，“不及”在这里表示比不上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不及", "is_correct": true, "explanation": "正确答案：不及（bù jí），听到的就是这个词。"}, {"text": "不挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，“不挤”意思是不拥挤、不推挤。"}, {"text": "簿记", "is_correct": false, "explanation": "bù jì 与 bù jí 只差声调（第四声/第二声），“簿记”意思是记账。"}, {"text": "不济", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，“不济”意思是不行、不济事。"}], "explanations": {"不及": "正确答案：不及（bù jí），听到的就是这个词。", "不挤": "jǐ（第三声）与 jí（第二声）声调不同，“不挤”意思是不拥挤、不推挤。", "簿记": "bù jì 与 bù jí 只差声调（第四声/第二声），“簿记”意思是记账。", "不济": "jì（第四声）与 jí（第二声）声调不同，“不济”意思是不行、不济事。"}, "sentence_index": null, "correct_answer": "不及"}, "level_3": {"options": [{"text": "不及", "is_correct": true, "explanation": "正确：“不及”表示水平不如别人，符合“做饭”的比较。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要“送给＋人”的结构，不能直接带比较对象。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出缺点，与“做饭不如妈妈”的比较不符。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”不能直接带比较对象，应说“对……生气”。"}], "explanations": {"不及": "正确：“不及”表示水平不如别人，符合“做饭”的比较。", "送": "配价：“送”需要“送给＋人”的结构，不能直接带比较对象。", "批评": "语义：“批评”指指出缺点，与“做饭不如妈妈”的比较不符。", "生气": "配价：“生气”不能直接带比较对象，应说“对……生气”。"}, "sentence_index": 6, "correct_answer": "不及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天这么冷，你不及多穿点衣服吧。", "explanation": "这里应该用〈不如〉。“不如……吧”表示提建议，“不及”只表示比不上，不能用来提建议。"}, {"text": "他对这个问题不及关心。", "explanation": "这里应该用〈不太〉。“不及”用于比较，后面要带比较对象，不能当程度副词修饰“关心”，应说“不太关心”。"}, {"text": "第一次做这件事，不及会出错。", "explanation": "这里应该用〈难免〉。“不及”表示比不上，不能表示免不了，应说“难免会出错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小店的生意很不及从前。", "corrected_sentence": "这个小店的生意不及从前。", "error_description": "副词错误：“不及”表示比较，前面不能加“很”。应说“这个小店的生意不及从前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的管理不及以前更规范。", "corrected_sentence": "这家公司的管理不及以前规范。", "error_description": "副词错误：“不及”已表示比不上，后面不能再加“更”。应说“这家公司的管理不及以前规范”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
