INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你想出来的好办法。", "primary_collocate": null, "pronunciation": "zhǔ yi", "ipa": "ʈʂu˨˩˦ i", "syllable_count": 2, "sentences": [{"text": "这个主意真不错，我们就这么办。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有好主意，快告诉大家。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总能想出很多好主意。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我出了个主意，问题解决了。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个主意是小李想出来的。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，我们一起想个主意吧。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的主意太好了，我怎么没想到？", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出的主意很有用。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨不能出去，我有个主意：在家做饭。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个主意听起来简单，做起来很难。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "想出来解决问题的办法或点子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96749, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主意", "is_correct": true, "explanation": "正确答案。主意 zhǔ yi，意思是你想出来的好办法。"}, {"text": "注意", "is_correct": false, "explanation": "第一个音节声调不同：zhù（第四声）与 zhǔ（第三声），意思是留心、留神，与“好办法”无关。"}, {"text": "竹椅", "is_correct": false, "explanation": "两个音节的声调都不同：zhú（第二声）、yǐ（第三声），意思是竹子做的椅子。"}, {"text": "主力", "is_correct": false, "explanation": "第二个音节声母由 y 变为 l，声调也变了：lì（第四声），意思是主要的力量。"}, {"text": "主业", "is_correct": false, "explanation": "第二个音节韵母由 i 变为 e，声调也变了：yè（第四声），意思是主要的职业或业务。"}], "explanations": {"主意": "正确答案。主意 zhǔ yi，意思是你想出来的好办法。", "注意": "第一个音节声调不同：zhù（第四声）与 zhǔ（第三声），意思是留心、留神，与“好办法”无关。", "竹椅": "两个音节的声调都不同：zhú（第二声）、yǐ（第三声），意思是竹子做的椅子。", "主力": "第二个音节声母由 y 变为 l，声调也变了：lì（第四声），意思是主要的力量。", "主业": "第二个音节韵母由 i 变为 e，声调也变了：yè（第四声），意思是主要的职业或业务。"}, "sentence_index": null, "correct_answer": "主意"}, "level_3": {"options": [{"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指生命的长短，与“真不错，就这么办”不相干。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“不错”多用来评价做法或结果，不用来评价“脚步”。"}, {"text": "主意", "is_correct": true, "explanation": "正确答案。“这个主意”指想出来的好办法，与句意相符。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：肚子不是可以拿来“办”的事物，“这个肚子真不错，我们就这么办”说不通。"}], "explanations": {"寿命": "语义：“寿命”指生命的长短，与“真不错，就这么办”不相干。", "脚步": "搭配：“不错”多用来评价做法或结果，不用来评价“脚步”。", "主意": "正确答案。“这个主意”指想出来的好办法，与句意相符。", "肚子": "语义：肚子不是可以拿来“办”的事物，“这个肚子真不错，我们就这么办”说不通。"}, "sentence_index": 0, "correct_answer": "主意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想出了一根好主意，大家都很佩服。", "explanation": "这里应该用〈个〉。“主意”用“个”计数；“根”多用于细长的东西，不能用来数“主意”。"}, {"text": "我们一起制定了一个主意，下周开始执行。", "explanation": "这里应该用〈方案〉。“制定”搭配“方案、计划”，“主意”是想法，不能被“制定”。"}, {"text": "这只狗很听主意的话。", "explanation": "这里应该用〈主人〉。“听话”的对象是主人，“主意”指想法，不能说“听主意的话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96749, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主意", "is_correct": true, "explanation": "正确答案。主意 zhǔ yi，意思是你想出来的好办法。"}, {"text": "主义", "is_correct": false, "explanation": "第二个音节声调不同：yì（第四声）与 yi（轻声），意思是主张、学说，如“马克思主义”。"}, {"text": "主席", "is_correct": false, "explanation": "第二个音节声母由 y 变为 x，声调也变了：xí（第二声），意思是会议或组织的负责人。"}, {"text": "逐一", "is_correct": false, "explanation": "两个音节的声调都不同：zhú（第二声）、yī（第一声），意思是一个一个地。"}], "explanations": {"主意": "正确答案。主意 zhǔ yi，意思是你想出来的好办法。", "主义": "第二个音节声调不同：yì（第四声）与 yi（轻声），意思是主张、学说，如“马克思主义”。", "主席": "第二个音节声母由 y 变为 x，声调也变了：xí（第二声），意思是会议或组织的负责人。", "逐一": "两个音节的声调都不同：zhú（第二声）、yī（第一声），意思是一个一个地。"}, "sentence_index": null, "correct_answer": "主意"}, "level_3": {"options": [{"text": "地址", "is_correct": false, "explanation": "搭配：“好”多用来评价做法、想法，“地址太好了”说不通，句意也不成立。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指年龄，与“我怎么没想到”之间没有关系，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，与“我怎么没想到”之间没有关系，句子说不通。"}, {"text": "主意", "is_correct": true, "explanation": "正确答案。“你的主意太好了”是说你想出的办法很好，与句意相符。"}], "explanations": {"地址": "搭配：“好”多用来评价做法、想法，“地址太好了”说不通，句意也不成立。", "年纪": "语义：“年纪”指年龄，与“我怎么没想到”之间没有关系，句子说不通。", "脾气": "语义：“脾气”指性情，与“我怎么没想到”之间没有关系，句子说不通。", "主意": "正确答案。“你的主意太好了”是说你想出的办法很好，与句意相符。"}, "sentence_index": 6, "correct_answer": "主意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章引起了大家的主意。", "explanation": "这里应该用〈注意〉。“引起注意”是固定说法，“主意”是想法，不能表示大家的关注。"}, {"text": "他编写了一个主意，明天就去做。", "explanation": "这里应该用〈程序〉。“编写”通常搭配“程序、文章”，“主意”是想法，不能被“编写”。"}, {"text": "这个主意的颜色很红。", "explanation": "这里不能用〈主意〉。“主意”是想法，没有颜色；描述颜色应换成具体的事物，如“这朵花的颜色很红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸给我出了一块好主意。", "corrected_sentence": "爸爸给我出了一个好主意。", "error_description": "错误：“主意”前用了量词“块”。“块”用于块状的东西，“主意”应该用“个”，应说“一个好主意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我出个了主意。", "corrected_sentence": "妈妈给我出了个主意。", "error_description": "错误：“了”位置不对。“出主意”是离合结构，“了”应放在“出”之后，应说“出了个主意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
