INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对事情的主张和办法；打算。", "primary_collocate": null, "pronunciation": "zhǔ yi", "ipa": "ʈʂu˨˩˦ i", "syllable_count": 2, "sentences": [{"text": "这件事你自己拿主意吧。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改变了主意，不去北京了。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经打定主意，明年去学中文。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子大了，有自己的主意。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买哪个好，我还拿不定主意。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管别人怎么说，她都不改主意。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快拿个主意，大家都在等你。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心里没主意，想先问问老师。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，他又变了主意。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里早有主意，只是没说出来。", "target_word": "主意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "对事情的看法、决定或打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主意", "is_correct": true, "explanation": "正确答案。主意 zhǔ yi，意思是对事情的主张、办法或打算。"}, {"text": "注意", "is_correct": false, "explanation": "第一个音节声调不同：zhù（第四声）与 zhǔ（第三声），意思是留心、留神，与“主意”不同。"}, {"text": "主义", "is_correct": false, "explanation": "第二个音节声调不同：yì（第四声）与 yi（轻声），意思是主张、学说，如“马克思主义”。"}, {"text": "竹椅", "is_correct": false, "explanation": "两个音节的声调都不同：zhú（第二声）、yǐ（第三声），意思是竹子做的椅子。"}, {"text": "主席", "is_correct": false, "explanation": "第二个音节声母由 y 变为 x，声调也变了：xí（第二声），意思是会议或组织的负责人。"}], "explanations": {"主意": "正确答案。主意 zhǔ yi，意思是对事情的主张、办法或打算。", "注意": "第一个音节声调不同：zhù（第四声）与 zhǔ（第三声），意思是留心、留神，与“主意”不同。", "主义": "第二个音节声调不同：yì（第四声）与 yi（轻声），意思是主张、学说，如“马克思主义”。", "竹椅": "两个音节的声调都不同：zhú（第二声）、yǐ（第三声），意思是竹子做的椅子。", "主席": "第二个音节声母由 y 变为 x，声调也变了：xí（第二声），意思是会议或组织的负责人。"}, "sentence_index": null, "correct_answer": "主意"}, "level_3": {"options": [{"text": "力气", "is_correct": false, "explanation": "搭配：“拿”可以接“主意”，但不能说“拿力气”，这里说不通。"}, {"text": "主意", "is_correct": true, "explanation": "正确答案。“拿主意”意思是做决定，与句意相符。"}, {"text": "卷子", "is_correct": false, "explanation": "语义：“卷子”指考试用的纸，与“这件事”的决定无关，句子说不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子与“这件事”没有关系，句子说不通。"}], "explanations": {"力气": "搭配：“拿”可以接“主意”，但不能说“拿力气”，这里说不通。", "主意": "正确答案。“拿主意”意思是做决定，与句意相符。", "卷子": "语义：“卷子”指考试用的纸，与“这件事”的决定无关，句子说不通。", "影子": "语义：影子与“这件事”没有关系，句子说不通。"}, "sentence_index": 0, "correct_answer": "主意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我心里已经有了一只主意，想先问问老师。", "explanation": "这里应该用〈个〉。“主意”是抽象名词，用“个”计量；“只”多用于动物或成对的东西，不能用来数“主意”。"}, {"text": "他终于做出了主意，明年去学中文。", "explanation": "这里应该用〈决定〉。“做出决定”是常用说法；“主意”一般说“拿主意”“有主意”“打定主意”，不能说“做出主意”。"}, {"text": "这份报告的主意很厚，大家都翻不完。", "explanation": "这里不能用〈主意〉。“主意”是想法，没有厚薄；说报告的厚薄应说“这份报告很厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主意", "is_correct": true, "explanation": "正确答案。主意 zhǔ yi，意思是对事情的主张、办法或打算。"}, {"text": "逐一", "is_correct": false, "explanation": "两个音节的声调都不同：zhú（第二声）、yī（第一声），意思是一个一个地。"}, {"text": "主业", "is_correct": false, "explanation": "第二个音节韵母由 i 变为 e，声调也变了：yè（第四声），意思是主要的职业或业务。"}, {"text": "主力", "is_correct": false, "explanation": "第二个音节声母由 y 变为 l，声调也变了：lì（第四声），意思是主要的力量。"}], "explanations": {"主意": "正确答案。主意 zhǔ yi，意思是对事情的主张、办法或打算。", "逐一": "两个音节的声调都不同：zhú（第二声）、yī（第一声），意思是一个一个地。", "主业": "第二个音节韵母由 i 变为 e，声调也变了：yè（第四声），意思是主要的职业或业务。", "主力": "第二个音节声母由 y 变为 l，声调也变了：lì（第四声），意思是主要的力量。"}, "sentence_index": null, "correct_answer": "主意"}, "level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "搭配：“拿”不能与“感冒”搭配，“拿个感冒”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以“拿”去做的东西，“快拿个年龄”与“大家都在等你”不相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“拿个”不能用于“眼睛”，句子不通。"}, {"text": "主意", "is_correct": true, "explanation": "正确答案。“拿个主意”意思是做出决定，与句意相符。"}], "explanations": {"感冒": "搭配：“拿”不能与“感冒”搭配，“拿个感冒”说不通。", "年龄": "语义：年龄不是可以“拿”去做的东西，“快拿个年龄”与“大家都在等你”不相合。", "眼睛": "搭配：“拿个”不能用于“眼睛”，句子不通。", "主意": "正确答案。“拿个主意”意思是做出决定，与句意相符。"}, "sentence_index": 6, "correct_answer": "主意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事引起了大家的主意。", "explanation": "这里应该用〈注意〉。“引起注意”是固定说法，“主意”是想法，不能表示别人的关注。"}, {"text": "他制定了一个学习主意，每天读书两小时。", "explanation": "这里应该用〈计划〉。“制定”通常搭配“计划、规则”，“主意”不能被“制定”。"}, {"text": "这块地的主意很平，适合盖房子。", "explanation": "这里不能用〈主意〉。“主意”是想法，没有平整与否；说地面平整应说“这块地很平”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事他心里早有了一只主意。", "corrected_sentence": "这件事他心里早有了一个主意。", "error_description": "错误：“主意”前用了量词“只”。“只”多用于动物或成对的东西，“主意”应该用“个”，应说“一个主意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于打了定主意，周末去爬山。", "corrected_sentence": "他终于打定了主意，周末去爬山。", "error_description": "错误：“了”放在了“打”和“定”之间。“打定”是动词加补语，“了”应放在“打定”之后，说“打定了主意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
