INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96751, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "甚至，说到更大的也是这样。", "primary_collocate": null, "pronunciation": "nǎi zhì", "ipa": "naɪ˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这本书在中国乃至全世界都很受欢迎。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市乃至整个地区都很安静。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人乃至一家人的生活都会受影响。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想帮助朋友、邻居乃至陌生人。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花在南方乃至北方都能种。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几百人乃至几千人来看了这场比赛。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项规定适用于学生乃至老师。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热爱家乡，乃至愿意放弃好工作回去。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌从中国传到了日本乃至美国。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯水乃至一口饭，他都舍不得浪费。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "甚至，从小的说到更大的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乃至", "is_correct": true, "explanation": "“乃至”从“中国”递进到更大的范围“全世界”，符合句意。"}, {"text": "而是", "is_correct": false, "explanation": "语义：“而是”表示否定后的替换，与句意不合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”表示让步，要与“但是”呼应，不能直接连接“中国”和“全世界”。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”需与“就”呼应，不能直接放在这里。"}], "explanations": {"乃至": "“乃至”从“中国”递进到更大的范围“全世界”，符合句意。", "而是": "语义：“而是”表示否定后的替换，与句意不合。", "虽然": "搭配：“虽然”表示让步，要与“但是”呼应，不能直接连接“中国”和“全世界”。", "只要": "搭配：“只要”需与“就”呼应，不能直接放在这里。"}, "sentence_index": 0, "correct_answer": "乃至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想帮助陌生人乃至朋友、邻居。", "explanation": "这里误把〈乃至〉当成不分先后的并列词，但它只能从小范围递进到大范围，应从朋友、邻居说到陌生人。"}, {"text": "他想帮助朋友、邻居乃至朋友。", "explanation": "这里误把〈乃至〉当成重复强调的〈而且〉，但乃至要引出比前面范围更大的人，“朋友”已在前面出现，不能重复。"}, {"text": "他想帮助朋友、邻居乃至。", "explanation": "这里乃至后面缺少它所递进的对象，句子不完整，应接一个比前面范围更大的人或事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乃至", "is_correct": true, "explanation": "“乃至”引出范围更大的对象，适用范围由学生扩大到老师，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，与“适用于学生”的范围不合。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”需要前后转折呼应，不能直接连接两个适用对象。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，与规定的适用范围不合。"}], "explanations": {"乃至": "“乃至”引出范围更大的对象，适用范围由学生扩大到老师，符合句意。", "因为": "语义：“因为”表示原因，与“适用于学生”的范围不合。", "但是": "搭配：“但是”需要前后转折呼应，不能直接连接两个适用对象。", "如果": "语义：“如果”表示假设，与规定的适用范围不合。"}, "sentence_index": 6, "correct_answer": "乃至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这不是我的错，乃至是他的错。", "explanation": "这里应该用〈而是〉。乃至表示范围递进，不能用于否定之后的替换。"}, {"text": "我喜欢吃水果，乃至是苹果。", "explanation": "这里应该用〈尤其〉。乃至表示范围递进，不能用于单独突出其中一个例子。"}, {"text": "一家人乃至一个人的生活都会受影响。", "explanation": "这里乃至前后顺序颠倒：应从一个人递进到一家人，不能从大范围退到小范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他太忙了，乃至了连饭都忘了吃。", "corrected_sentence": "他太忙了，乃至连饭都忘了吃。", "error_description": "「乃至」是连词，后面不能加「了」，应把「乃至了连饭」改为「乃至连饭」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连老人的乃至小孩都要遵守这项规定。", "corrected_sentence": "连老人乃至小孩都要遵守这项规定。", "error_description": "“的”误加：“乃至”前后不能插入“的”，应说“连老人乃至小孩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
