INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96752, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示更进一层的意思，相当于甚至。", "primary_collocate": null, "pronunciation": "nǎi zhì", "ipa": "naɪ˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件事影响了全市乃至全国。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画在中国乃至世界都很有名。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语需要几个月乃至几年的时间。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌年轻人乃至老人都喜欢。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题让学生、老师乃至家长都很头疼。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，孩子乃至大人都不想出门。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人几十年乃至一辈子都没离开过这个村子。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在我们国家乃至国外都卖得很好。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法对个人乃至公司都有好处。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校乃至整个城市都停电了。", "target_word": "乃至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连接并列项，表示范围更进一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乃至", "is_correct": true, "explanation": "“乃至”连接由小到大的并列范围，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，与“全市、全国”的范围递进不合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”等呼应，不能直接连接并列的范围。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，与句中的事实陈述不合。"}], "explanations": {"乃至": "“乃至”连接由小到大的并列范围，符合句意。", "因为": "语义：“因为”表示原因，与“全市、全国”的范围递进不合。", "虽然": "搭配：“虽然”要与“但是”等呼应，不能直接连接并列的范围。", "如果": "语义：“如果”表示假设，与句中的事实陈述不合。"}, "sentence_index": 0, "correct_answer": "乃至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学汉语需要几年乃至几个月的时间。", "explanation": "这里乃至前后顺序颠倒：应从几个月递进到几年，不能从大范围退到小范围。"}, {"text": "这件事影响了全国乃至全市。", "explanation": "这里误把〈乃至〉当成不分先后的并列词，但它只能从小范围递进到大范围，应说“全市乃至全国”。"}, {"text": "这首歌在国内乃至国内都很有名。", "explanation": "这里误把〈乃至〉当成重复强调的〈而且〉，但乃至要引出比前面范围更大的对象，前后都是“国内”，没有递进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乃至", "is_correct": true, "explanation": "“乃至”连接由短到长的时间范围，符合句意。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”需要与前文转折呼应，不能在这里连接时间范围。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，与句中的时间递进不合。"}, {"text": "而是", "is_correct": false, "explanation": "语义：“而是”表示对前面的否定，与句意不合。"}], "explanations": {"乃至": "“乃至”连接由短到长的时间范围，符合句意。", "但是": "搭配：“但是”需要与前文转折呼应，不能在这里连接时间范围。", "因此": "语义：“因此”表示因果，与句中的时间递进不合。", "而是": "语义：“而是”表示对前面的否定，与句意不合。"}, "sentence_index": 6, "correct_answer": "乃至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没吃早饭，乃至很饿。", "explanation": "这里应该用〈所以〉。乃至只能递进地连接同类的人或事物，不能表示因果。"}, {"text": "他不是老师，乃至是学生。", "explanation": "这里应该用〈而是〉。乃至表示范围递进，不能用于否定之后的替换。"}, {"text": "他很努力，乃至成绩不好。", "explanation": "这里应该用〈可是〉。乃至表示范围递进，不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息传遍了全校和乃至全市。", "corrected_sentence": "这个消息传遍了全校乃至全市。", "error_description": "“和”与“乃至”不能并用：“乃至”本身已连接递进范围，应说“全校乃至全市”，去掉“和”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病在农村乃至的城市都很常见。", "corrected_sentence": "这种病在农村乃至城市都很常见。", "error_description": "“的”误加：“乃至”后面直接接并列的名词“城市”，不能插入“的”，应说“乃至城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
