INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个接一个地做过很多工作或职位。", "primary_collocate": null, "pronunciation": "lì rèn", "ipa": "li˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他历任球队的队长、教练和经理。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她历任报社的记者、编辑和主编。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位厨师历任三家大饭店的主厨。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司历任销售、市场和人事部门的经理。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈老师历任小学、中学和大学的语文老师。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时历任车间主任、厂长和经理。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位演员历任电影学院的老师和系主任。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周先生历任公司的财务、销售和运营总监。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的院长历任科室主任和副院长。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他历任协会的秘书、理事和会长。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷任", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个接一个地做过很多工作或职位（工作经历）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历任", "is_correct": true, "explanation": "正确：历任指先后担任多个职务，与队长、教练、经理相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：“毕业”是不及物动词，后面不能直接带队长、教练等宾语。"}, {"text": "休息", "is_correct": false, "explanation": "语法：“休息”不带宾语，不能说休息队长、教练和经理。"}, {"text": "出发", "is_correct": false, "explanation": "语法：“出发”不带人作宾语，与句子不合。"}], "explanations": {"历任": "正确：历任指先后担任多个职务，与队长、教练、经理相符。", "毕业": "语法：“毕业”是不及物动词，后面不能直接带队长、教练等宾语。", "休息": "语法：“休息”不带宾语，不能说休息队长、教练和经理。", "出发": "语法：“出发”不带人作宾语，与句子不合。"}, "sentence_index": 0, "correct_answer": "历任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他历任一个小时的讲座。", "explanation": "这里应该用〈主讲〉。历任指先后担任多个职务，不用于一次性的讲课活动。"}, {"text": "他历任一次会议的主持人，效果很好。", "explanation": "这里应该用〈主持〉。历任指先后担任多个职务，只担任一次会议的职务时不能说历任。"}, {"text": "他历任人事部工作。", "explanation": "这里应该用〈曾在〉。历任用于担任的职务，不用于一般的工作地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历任", "is_correct": true, "explanation": "正确：历任指先后担任过老师、系主任等职务，与演员的经历相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语法：“游泳”不带宾语，不能说游泳老师和系主任。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”不带宾语，不能说睡觉老师和系主任。"}, {"text": "讲授", "is_correct": false, "explanation": "搭配：“讲授”的对象是课程、知识，不说讲授系主任。"}], "explanations": {"历任": "正确：历任指先后担任过老师、系主任等职务，与演员的经历相符。", "游泳": "语法：“游泳”不带宾语，不能说游泳老师和系主任。", "睡觉": "语法：“睡觉”不带宾语，不能说睡觉老师和系主任。", "讲授": "搭配：“讲授”的对象是课程、知识，不说讲授系主任。"}, "sentence_index": 6, "correct_answer": "历任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他历任北京分公司的一次调查。", "explanation": "这里应该用〈进行〉。历任指担任职务，调查是活动而非职务，应说进行。"}, {"text": "她历任协会的一次宣传。", "explanation": "这里应该用〈开展〉。历任指担任职务，宣传活动应说开展。"}, {"text": "她历任许多磨难。", "explanation": "这里应该用〈经历〉。历任指担任职务，不用于说经历磨难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他历任在三家俱乐部的教练和领队。", "corrected_sentence": "他历任三家俱乐部的教练和领队。", "error_description": "错误在“历任”后插入了“在”。“历任”后直接接职务名称，应改为“历任三家俱乐部的教练和领队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她历任着两家杂志社的编辑和记者。", "corrected_sentence": "她历任两家杂志社的编辑和记者。", "error_description": "错误在“历任”后加了“着”。“历任”表示已经完成的经历，不带“着”；应改为“历任两家杂志社的编辑和记者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "爱", "is_correct": true, "explanation": "正确：爱与“仇恨”构成反义，指喜爱、爱护的情感。"}, {"text": "道路", "is_correct": false, "explanation": "道路是名词，指行走的路，与“仇恨”没有反义关系。"}, {"text": "草原", "is_correct": false, "explanation": "草原是地理环境，与“仇恨”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是具体的物体，与“仇恨”没有反义关系。"}], "correct_answer": "爱", "explanations": {"爱": "正确：爱与“仇恨”构成反义，指喜爱、爱护的情感。", "道路": "道路是名词，指行走的路，与“仇恨”没有反义关系。", "草原": "草原是地理环境，与“仇恨”没有反义关系。", "石头": "石头是具体的物体，与“仇恨”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "友谊", "is_correct": true, "explanation": "正确：友谊与“仇恨”构成反义，指朋友之间友好的感情。"}, {"text": "利润", "is_correct": false, "explanation": "利润是经济收益，与“仇恨”没有反义关系。"}, {"text": "地图", "is_correct": false, "explanation": "地图是具体的物品，与“仇恨”没有反义关系。"}, {"text": "花朵", "is_correct": false, "explanation": "花朵是植物的一部分，与“仇恨”没有反义关系。"}], "correct_answer": "友谊", "explanations": {"友谊": "正确：友谊与“仇恨”构成反义，指朋友之间友好的感情。", "利润": "利润是经济收益，与“仇恨”没有反义关系。", "地图": "地图是具体的物品，与“仇恨”没有反义关系。", "花朵": "花朵是植物的一部分，与“仇恨”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因为被伤害，心里对人很生气，一直忘不了。", "primary_collocate": null, "pronunciation": "chóu hèn", "ipa": "ʈʂʰoʊ˧˥ xən˥˩", "syllable_count": 2, "sentences": [{"text": "朋友骗了她，她心里一直留着仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对那个人的仇恨，十年了还没有消失。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话时，声音里全是仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想把仇恨带到明天，今天就原谅你。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过很大的伤，却没有一点仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人伤害了她的家人，她一直记着这份仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈劝我放下过去，别让仇恨毁了生活。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看那个人的眼神里有仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间一天天过去，她心里的仇恨慢慢变淡了。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，仇恨让人睡不好觉，也吃不下饭。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "受伤害后对人长久不忘的怨恨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfc67122-5602-4672-be92-b592090b5833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指受伤害后长久不忘的怨恨，与“朋友骗了她”相符。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“笑声”是声音，不能说“心里一直留着笑声”，也与“朋友骗了她”不符。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物”是实物，不能说“心里留着礼物”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是身体的数值，不能说“心里留着体重”。"}], "explanations": {"仇恨": "正确：“仇恨”指受伤害后长久不忘的怨恨，与“朋友骗了她”相符。", "笑声": "搭配：“笑声”是声音，不能说“心里一直留着笑声”，也与“朋友骗了她”不符。", "礼物": "搭配：“礼物”是实物，不能说“心里留着礼物”。", "体重": "搭配：“体重”是身体的数值，不能说“心里留着体重”。"}, "sentence_index": 0, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她心里养着一只仇恨，十几年没放下。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“只”多用于动物或成对的东西。"}, {"text": "我很感激他，所以把仇恨送给他做礼物。", "explanation": "仇恨是负面情感，不能当作礼物送人，与“感激”相矛盾。"}, {"text": "听到好消息，她心里充满了仇恨，高兴得跳了起来。", "explanation": "这里应该用〈欢喜〉。“仇恨”是负面情感，听到好消息后的开心要用“欢喜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指长久不忘的怨恨，与“妈妈劝我放下过去”的语境相符。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”与“毁了生活”矛盾。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“粮食”是实物，不能用来“毁了生活”这样的情感描述。"}, {"text": "钟声", "is_correct": false, "explanation": "搭配：“钟声”是声音，不能说“毁了生活”。"}], "explanations": {"仇恨": "正确：“仇恨”指长久不忘的怨恨，与“妈妈劝我放下过去”的语境相符。", "温暖": "语义：“温暖”与“毁了生活”矛盾。", "粮食": "搭配：“粮食”是实物，不能用来“毁了生活”这样的情感描述。", "钟声": "搭配：“钟声”是声音，不能说“毁了生活”。"}, "sentence_index": 6, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸说，他心里有一把仇恨，让人睡不好觉。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“把”用于有柄的器具。"}, {"text": "爸爸说，仇恨让人睡得很香，吃得很好。", "explanation": "这里应该用〈爱〉。仇恨与“睡得很香，吃得很好”相矛盾，换成“爱”才符合语境。"}, {"text": "这个孩子唱歌很好听，大家都喜欢听他的仇恨。", "explanation": "这里应该用〈歌声〉。“仇恨”是情感，不能被听到，大家喜欢听的应该是“歌声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友骗了她，她心里一直留着一只仇恨。", "corrected_sentence": "朋友骗了她，她心里一直留着一股仇恨。", "error_description": "量词错误：“仇恨”是抽象情感，应用量词“股”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b094eb68-4944-4fe7-827a-fa2051bea310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
