INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外面包着里面东西的硬皮。", "primary_collocate": null, "pronunciation": "ké", "ipa": "kʰɤ˧˥", "syllable_count": 1, "sentences": [{"text": "小鸡用嘴啄破壳，钻了出来。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虾的壳里有白色的肉。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他剥开壳，里面是一颗红色的豆子。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松子的壳很小，里面的仁很香。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的小孩捡到一个大壳，里面住着小螃蟹。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子的壳破了，长出了绿色的小芽。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜗牛遇到危险，就缩进壳里。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些核桃的壳都裂开了，里面是空的。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀撬开壳，取出里面的肉。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把壳放在桌上的小碗里，不要掉在地上。", "target_word": "壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层壳", "label": "量词"}, {"form": "殼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "包在里面的肉、仁或种子外面的硬皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "壳", "is_correct": true, "explanation": "正确。壳（ké）指包在仁、肉或种子外面的硬皮。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 ké（第二声）声调不同，意思是“口渴”。"}, {"text": "刻", "is_correct": false, "explanation": "kè（第四声）与 ké（第二声）声调不同，意思是“雕刻”或“时刻”。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 ké（第二声）声调不同，意思是“科目”。"}, {"text": "克", "is_correct": false, "explanation": "kè（第四声）与 ké（第二声）声调不同，意思是“克”，重量单位。"}], "explanations": {"壳": "正确。壳（ké）指包在仁、肉或种子外面的硬皮。", "渴": "kě（第三声）与 ké（第二声）声调不同，意思是“口渴”。", "刻": "kè（第四声）与 ké（第二声）声调不同，意思是“雕刻”或“时刻”。", "科": "kē（第一声）与 ké（第二声）声调不同，意思是“科目”。", "克": "kè（第四声）与 ké（第二声）声调不同，意思是“克”，重量单位。"}, "sentence_index": null, "correct_answer": "壳"}, "level_3": {"options": [{"text": "壳", "is_correct": true, "explanation": "正确。“小鸡用嘴啄破壳”指啄破包着小鸡的硬壳，与“钻了出来”相符。"}, {"text": "窝", "is_correct": false, "explanation": "语义：小鸡不是从窝里啄破“窝”而钻出来的，句意不通。"}, {"text": "草", "is_correct": false, "explanation": "搭配：“啄破”的对象应是包裹小鸡的硬壳，草不能被啄破来让小鸡出来。"}, {"text": "翅", "is_correct": false, "explanation": "搭配：小鸡不会用嘴啄破自己的翅，“啄破翅”不成立。"}], "explanations": {"壳": "正确。“小鸡用嘴啄破壳”指啄破包着小鸡的硬壳，与“钻了出来”相符。", "窝": "语义：小鸡不是从窝里啄破“窝”而钻出来的，句意不通。", "草": "搭配：“啄破”的对象应是包裹小鸡的硬壳，草不能被啄破来让小鸡出来。", "翅": "搭配：小鸡不会用嘴啄破自己的翅，“啄破翅”不成立。"}, "sentence_index": 0, "correct_answer": "壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我手里拿着一张松子壳，闻起来很香。", "explanation": "这里量词用错。〈张〉用于纸、桌面等平面的东西，松子壳应该用〈个〉。"}, {"text": "猫的壳很软，摸起来很舒服。", "explanation": "这里应该用〈皮毛〉。猫身上是毛，没有硬壳；〈壳〉只指包在仁、肉或种子外面的硬皮。"}, {"text": "这床被子的壳很厚，冬天盖着很暖和。", "explanation": "这里应该用〈被面〉。被子外面的布要说〈被面〉，〈壳〉只指动植物或果实外面的硬皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96757, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "壳", "is_correct": true, "explanation": "正确。壳（ké）指包在仁、肉或种子外面的硬皮。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 ké（第二声）声调不同，意思是“可以”。"}, {"text": "课", "is_correct": false, "explanation": "kè（第四声）与 ké（第二声）声调不同，意思是“课程”。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 ké（第二声）声调不同，意思是“客人”。"}, {"text": "颗", "is_correct": false, "explanation": "kē（第一声）与 ké（第二声）声调不同，意思是“颗粒”。"}], "explanations": {"壳": "正确。壳（ké）指包在仁、肉或种子外面的硬皮。", "可": "kě（第三声）与 ké（第二声）声调不同，意思是“可以”。", "课": "kè（第四声）与 ké（第二声）声调不同，意思是“课程”。", "客": "kè（第四声）与 ké（第二声）声调不同，意思是“客人”。", "颗": "kē（第一声）与 ké（第二声）声调不同，意思是“颗粒”。"}, "sentence_index": null, "correct_answer": "壳"}, "level_3": {"options": [{"text": "壳", "is_correct": true, "explanation": "正确。“缩进壳里”指蜗牛把身体缩回背上的壳中，与“遇到危险”相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：蜗牛不会缩进书里，“缩进书里”与句意不符。"}, {"text": "窗", "is_correct": false, "explanation": "配价：“缩进”需要一个可以容纳身体的物体，窗户不能容纳蜗牛。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不是蜗牛可以缩进去的地方，“缩进歌里”语义不通。"}], "explanations": {"壳": "正确。“缩进壳里”指蜗牛把身体缩回背上的壳中，与“遇到危险”相符。", "书": "语义：蜗牛不会缩进书里，“缩进书里”与句意不符。", "窗": "配价：“缩进”需要一个可以容纳身体的物体，窗户不能容纳蜗牛。", "歌": "语义：歌不是蜗牛可以缩进去的地方，“缩进歌里”语义不通。"}, "sentence_index": 6, "correct_answer": "壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个番茄的壳很厚，我切了半天。", "explanation": "这里应该用〈皮〉。番茄的表皮要说〈皮〉，〈壳〉只指蛋、蟹、贝、龟等坚硬的外壳。"}, {"text": "这床褥子的壳破了，要买一床新的。", "explanation": "这里应该用〈套子〉。床褥外面的罩子要说〈套子〉，〈壳〉只指动植物或果实外面的硬皮。"}, {"text": "这张桌子的壳很结实，我们经常坐在上面。", "explanation": "这里应该用〈桌面〉。桌子的平面要说〈桌面〉，〈壳〉只指动植物或果实外面的硬皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那张壳裂开了，小鸡快要出来了。", "corrected_sentence": "那个壳裂开了，小鸡快要出来了。", "error_description": "错误在量词“张”。“张”用于纸、桌面等平面的东西，壳应该用“个”，应说“那个壳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把三张壳都扔进了垃圾桶。", "corrected_sentence": "他把三个壳都扔进了垃圾桶。", "error_description": "错误在量词“张”。“张”用于纸、桌面等平面的东西，壳应该用“个”，应说“三个壳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
