INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电脑里最小的一个数字单位。", "primary_collocate": null, "pronunciation": "wèi yuán", "ipa": "wei˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "位元是电脑里最小的数字单位。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个位元只能是零或者一。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八个位元合起来是一个字节。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑用零和一这样的位元来记东西。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位元太小，所以我们常常用字节来算。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片一共有几百万个位元。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，位元就是电脑里最小的格子。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的每个位元，不是开就是关。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上学会了什么是位元。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位元越多，能放的信息就越多。", "target_word": "位元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个位元", "label": "量词"}, {"form": "位元组", "label": "复合"}, {"form": "位元率", "label": "复合"}], "register": "书面", "sense_fingerprint": "电脑里只有零和一的最小数字单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位元", "is_correct": true, "explanation": "“位元是电脑里最小的数字单位”，只有“位元”指电脑中最小的数字单位。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘是输入设备，不是数字单位，“最小的数字单位”说不通。"}, {"text": "屏幕", "is_correct": false, "explanation": "搭配：屏幕不是计量单位，不能说成“数字单位”。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里是长度单位，与电脑无关，且远不是最小的单位。"}], "explanations": {"位元": "“位元是电脑里最小的数字单位”，只有“位元”指电脑中最小的数字单位。", "键盘": "语义：键盘是输入设备，不是数字单位，“最小的数字单位”说不通。", "屏幕": "搭配：屏幕不是计量单位，不能说成“数字单位”。", "公里": "语义：公里是长度单位，与电脑无关，且远不是最小的单位。"}, "sentence_index": 0, "correct_answer": "位元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的位元很大，能装很多照片。", "explanation": "这里应该用〈硬盘〉。位元是最小的数字单位，没有大小，也装不了照片。"}, {"text": "这台电脑的位元装得下很多软件，运行得很快。", "explanation": "这里应该用〈内存〉。位元只是一个最小的数字单位，装不下软件。"}, {"text": "一个位元能存下一个英文字母。", "explanation": "这里应该用〈字节〉。位元是最小的单位，只能是零或一；八个位元才是一个字节，一个字节才能存下一个英文字母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位元", "is_correct": true, "explanation": "“老师说，位元就是电脑里最小的格子”，只有“位元”是这个意思的单位。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：硬盘是存储设备，不是数字单位，“最小的格子”也不成立。"}, {"text": "鼠标", "is_correct": false, "explanation": "语义：鼠标是输入设备，与“最小的格子”毫无关系。"}, {"text": "显卡", "is_correct": false, "explanation": "搭配：显卡是硬件，不能说成“最小的格子”这种计量单位。"}], "explanations": {"位元": "“老师说，位元就是电脑里最小的格子”，只有“位元”是这个意思的单位。", "硬盘": "语义：硬盘是存储设备，不是数字单位，“最小的格子”也不成立。", "鼠标": "语义：鼠标是输入设备，与“最小的格子”毫无关系。", "显卡": "搭配：显卡是硬件，不能说成“最小的格子”这种计量单位。"}, "sentence_index": 6, "correct_answer": "位元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "位元的分辨率很高，画面很清楚。", "explanation": "这里应该用〈屏幕〉。分辨率说的是显示设备，位元是数字单位，不能说分辨率。"}, {"text": "这个位元有十二画，很难写。", "explanation": "这里应该用〈字〉。位元是最小的数字单位，没有笔画。"}, {"text": "他坐在第一排的位元上，看得很清楚。", "explanation": "这里应该用〈位子〉。位元是数字单位，不能指坐的地方，应说“位子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每张位元都只能表示开或关两种状态。", "corrected_sentence": "每个位元都只能表示开或关两种状态。", "error_description": "错误形式：每张位元；正确形式：每个位元。位元是抽象的数字单位，不是平面物，量词应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段音乐大约要用几十万只位元来记。", "corrected_sentence": "这段音乐大约要用几十万个位元来记。", "error_description": "错误形式：几十万只位元；正确形式：几十万个位元。“只”多用于动物或成对物品中的单个，位元是抽象数字单位，应用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
