INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "concrete", "definition": "每一个地方。", "primary_collocate": null, "pronunciation": "měi chù", "ipa": "meɪ˨˩˦ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "这座公园有三处入口，每处都有保安。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每处风景都很美。", "target_word": "每处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里有两处漏水，我们每处都修好了。", "target_word": "每处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，书上每处错误都要改。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上有五处停车场，每处都很大。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上有几处医院，他每处都画了红圈。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上有几处小店，每处都卖热茶。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这三处房子我都看过，每处都不错。", "target_word": "每处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身上有几处伤，每处都不深。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几处景点我们每处都玩了一天。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "每處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个地方中的每一个地方（逐一）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每处", "is_correct": true, "explanation": "正确。每处指公园三个入口中的每一处，与“都有保安”相呼应。"}, {"text": "每间", "is_correct": false, "explanation": "搭配：量词“间”用于房屋，入口不用“间”计数，不能说每间都有保安。"}, {"text": "每台", "is_correct": false, "explanation": "搭配：量词“台”用于机器、车辆等，入口不用“台”计数，不能说每台都有保安。"}, {"text": "每位", "is_correct": false, "explanation": "语义：“位”指人，入口不是人，不能说每位都有保安。"}], "explanations": {"每处": "正确。每处指公园三个入口中的每一处，与“都有保安”相呼应。", "每间": "搭配：量词“间”用于房屋，入口不用“间”计数，不能说每间都有保安。", "每台": "搭配：量词“台”用于机器、车辆等，入口不用“台”计数，不能说每台都有保安。", "每位": "语义：“位”指人，入口不是人，不能说每位都有保安。"}, "sentence_index": 0, "correct_answer": "每处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每处考试我都很紧张。", "explanation": "这里应该用〈每次〉。每处指每一个地方，说考试的次数要用每次。"}, {"text": "每处客人都有一个座位。", "explanation": "这里应该用〈每位〉。每处只用于地方，指人要用每位。"}, {"text": "每处衣服都很贵。", "explanation": "这里应该用〈每件〉。衣服要用“件”计数，每处只用于地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每处", "is_correct": true, "explanation": "正确。每处指山上几处小店中的每一处，与“都卖热茶”相呼应。"}, {"text": "每台", "is_correct": false, "explanation": "搭配：量词“台”用于机器、车辆等，小店不用“台”计数，不能说每台都卖热茶。"}, {"text": "每架", "is_correct": false, "explanation": "搭配：量词“架”用于飞机、机器等，小店不用“架”计数。"}, {"text": "每队", "is_correct": false, "explanation": "语义：“队”指团体，小店不是队伍，不能说每队都卖热茶。"}], "explanations": {"每处": "正确。每处指山上几处小店中的每一处，与“都卖热茶”相呼应。", "每台": "搭配：量词“台”用于机器、车辆等，小店不用“台”计数，不能说每台都卖热茶。", "每架": "搭配：量词“架”用于飞机、机器等，小店不用“架”计数。", "每队": "语义：“队”指团体，小店不是队伍，不能说每队都卖热茶。"}, "sentence_index": 6, "correct_answer": "每处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每处歌都很好听。", "explanation": "这里应该用〈每首〉。歌曲要用“首”计数，每处只用于地方。"}, {"text": "每处菜都很香。", "explanation": "这里应该用〈每道〉。菜要用“道”计数，每处只用于地方。"}, {"text": "每处信都写得很长。", "explanation": "这里应该用〈每封〉。信件要用“封”计数，每处只用于地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站有四处出口，一每处都挂着地图。", "corrected_sentence": "这个车站有四处出口，每处都挂着地图。", "error_description": "“每处”前面不能加数词“一”，“每”本身已经表示“每一”的意思；应说“每处都挂着地图”，不说“一每处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖边有三处码头，每处很都热闹。", "corrected_sentence": "这个湖边有三处码头，每处都很热闹。", "error_description": "错误在“都”的位置。“都”须位于“很”之前，应说“每处都很热闹”，不说“每处很都热闹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
