INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友说的，肚子里排出来的东西。", "primary_collocate": null, "pronunciation": "biàn bian", "ipa": "pi̯ɛn˥˩ pi̯ɛn", "syllable_count": 2, "sentences": [{"text": "小狗在草地上拉了一堆便便。", "target_word": "便便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝的便便今天是黄色的。", "target_word": "便便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有便便，别踩到它。", "target_word": "便便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈看了看宝宝的便便，说他很健康。", "target_word": "便便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边的狗便便要用袋子捡起来。", "target_word": "便便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小弟弟指着地上说：“那是便便！”", "target_word": "便便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟在我的车上留下了便便。", "target_word": "便便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家猫的便便很臭。", "target_word": "便便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友，别用手去摸便便。", "target_word": "便便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "宝宝的尿布上有一坨便便，妈妈赶紧去换。", "target_word": "便便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坨", "label": "量词"}], "register": "儿语", "sense_fingerprint": "儿童用语，指排出的粪便这种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83cb033c-65f2-4245-880f-781ee5f7bd8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便便", "is_correct": true, "explanation": "“拉了一堆便便”中，便便是小朋友说的排出的东西，与“拉”和“一堆”搭配自然。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“拉”指排泄，不能拉出石头。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是小狗排出来的东西。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是排泄物，与“拉”的意思不符。"}], "explanations": {"便便": "“拉了一堆便便”中，便便是小朋友说的排出的东西，与“拉”和“一堆”搭配自然。", "石头": "搭配：“拉”指排泄，不能拉出石头。", "树叶": "语义：树叶不是小狗排出来的东西。", "面包": "语义：面包是食物，不是排泄物，与“拉”的意思不符。"}, "sentence_index": 0, "correct_answer": "便便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚家里来客人，我们只准备了一顿便便，很简单。", "explanation": "这里应该用〈便饭〉。便饭指家常的简单饭菜；〈便便〉指大便，不能用来指饭菜。"}, {"text": "这里交通很便便，去哪儿都方便。", "explanation": "这里应该用〈便利〉。便便指排出的粪便，不能用来形容交通方便。"}, {"text": "这首歌真便便，我听了好喜欢！", "explanation": "这里应该用〈棒〉。便便只指排出的粪便，不能用来评价歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便便", "is_correct": true, "explanation": "“留下了便便”指小鸟在车上排出的东西，符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：小鸟不会在车上留下钥匙，与“留下”的语境不符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是小鸟会留下的东西。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“留下”常搭配痕迹或排出物，不说留下汽油。"}], "explanations": {"便便": "“留下了便便”指小鸟在车上排出的东西，符合语境。", "钥匙": "语义：小鸟不会在车上留下钥匙，与“留下”的语境不符。", "课本": "语义：课本不是小鸟会留下的东西。", "汽油": "搭配：“留下”常搭配痕迹或排出物，不说留下汽油。"}, "sentence_index": 6, "correct_answer": "便便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝宝拉完一片便便，妈妈让他快去洗手。", "explanation": "这里应该用〈坨〉。〈片〉用于扁平的东西，便便不是扁平的，不能这样计量。"}, {"text": "宝宝的尿布上有一只便便，妈妈赶紧去换。", "explanation": "这里应该用〈坨〉。〈只〉用于动物或成对的东西，不用于便便。"}, {"text": "妈妈把一瓶便便倒进了马桶。", "explanation": "这里应该用〈坨〉。〈瓶〉用于液体或装在瓶里的东西，便便是固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草地上有一只便便，要赶快清理。", "corrected_sentence": "草地上有一堆便便，要赶快清理。", "error_description": "量词错误：便便应用“堆”或“坨”计量。“只”用于动物，不用于粪便，应改为“草地上有一堆便便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗今天拉了两只便便。", "corrected_sentence": "小狗今天拉了两坨便便。", "error_description": "量词错误：便便应用“坨”计量，“只”用于动物，不用于粪便。正确说“拉了两坨便便”，不能说“拉了两只便便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de67aff-ba20-4b82-ac24-d6b9c43ed18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
