INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "说一个例子给你听的时候，用这个词开头。", "primary_collocate": null, "pronunciation": "bǐ rú shuō", "ipa": "pi˨˩ ɻu˧˥ ʂwo˥", "syllable_count": 3, "sentences": [{"text": "我喜欢很多运动，比如说游泳和跑步。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有很多好吃的，比如说北京烤鸭。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些水果很甜，比如说西瓜和葡萄。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的方法很多，比如说看电影、听歌。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过几个国家，比如说日本和法国。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会做很多菜，比如说红烧肉。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以买点礼物，比如说一本书或者一束花。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有不少名胜，比如说故宫和长城。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常做家务，比如说洗衣服、做饭。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些动物很可爱，比如说熊猫。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "说话时用来开头举例的连接词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比如说", "is_correct": true, "explanation": "正确：「比如说」引出游泳和跑步这个例子，符合语境。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，与列举例子的语境不符。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，「游泳和跑步」不能作为喜欢运动的原因。"}, {"text": "即使", "is_correct": false, "explanation": "配价：「即使」要与后面的「也」呼应，不能直接带「游泳和跑步」。"}], "explanations": {"比如说": "正确：「比如说」引出游泳和跑步这个例子，符合语境。", "但是": "语义：「但是」表示转折，与列举例子的语境不符。", "因为": "语义：「因为」表示原因，「游泳和跑步」不能作为喜欢运动的原因。", "即使": "配价：「即使」要与后面的「也」呼应，不能直接带「游泳和跑步」。"}, "sentence_index": 0, "correct_answer": "比如说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆环境很好，比如说菜也很便宜。", "explanation": "这里应该用〈而且〉。「比如说」用于引出例子，不用来并列补充另一个情况。"}, {"text": "他很努力，比如说成绩不太好。", "explanation": "这里应该用〈但是〉。「比如说」引出例子，不能表示转折。"}, {"text": "他先吃了饭，比如说去了学校。", "explanation": "这里应该用〈然后〉。「比如说」引出例子，不表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比如说", "is_correct": true, "explanation": "正确：「比如说」引出一本书和一束花这个例子，符合语境。"}, {"text": "总之", "is_correct": false, "explanation": "语义：「总之」用于总结，不能引出具体的例子。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，不能直接接「一本书或者一束花」这样的名词短语。"}, {"text": "否则", "is_correct": false, "explanation": "配价：「否则」要接分句，不能直接带「一本书或者一束花」这样的名词短语。"}], "explanations": {"比如说": "正确：「比如说」引出一本书和一束花这个例子，符合语境。", "总之": "语义：「总之」用于总结，不能引出具体的例子。", "因此": "语义：「因此」表示因果，不能直接接「一本书或者一束花」这样的名词短语。", "否则": "配价：「否则」要接分句，不能直接带「一本书或者一束花」这样的名词短语。"}, "sentence_index": 6, "correct_answer": "比如说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，比如说我们没去公园。", "explanation": "这里应该用〈因此〉。「比如说」引出例子，不表示因果关系。"}, {"text": "他听到消息，比如说立刻回家了。", "explanation": "这里应该用〈于是〉。「比如说」引出例子，不表示接着做某事。"}, {"text": "这个计划很好，比如说没人愿意参加。", "explanation": "这里应该用〈然而〉。「比如说」引出例子，不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢吃水果，比如说的苹果。", "corrected_sentence": "我喜欢吃水果，比如说苹果。", "error_description": "词尾错误：「比如说」是连词，后面不能加「的」，应把「比如说的苹果」改为「比如说苹果」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可以学一门外语，比如说了日语。", "corrected_sentence": "你可以学一门外语，比如说日语。", "error_description": "词尾错误：「比如说」是连词，后面不能加「了」，应把「比如说了日语」改为「比如说日语」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
