INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96770, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来引出例子的说法。", "primary_collocate": null, "pronunciation": "bǐ rú shuō", "ipa": "pi˨˩ ɻu˧˥ ʂwo˥", "syllable_count": 3, "sentences": [{"text": "我想学一些新东西，比如说画画。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人有坏习惯，比如说睡得太晚。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃中国菜，比如说饺子。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人喜欢安静，比如说我姐姐。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以换个方式，比如说坐地铁去。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会做一些简单的菜，比如说炒鸡蛋。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城里有很多老店，比如说那家茶馆。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好很特别，比如说收集旧钥匙。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好会影响心情，比如说下雨天。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常举例子，比如说用故事讲语法。", "target_word": "比如说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "引出例子的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比如说", "is_correct": true, "explanation": "正确：「比如说」引出画画这个例子，符合语境。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，与「学新东西」之后举例画画的语境不符。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，「画画」不是学新东西的原因。"}, {"text": "否则", "is_correct": false, "explanation": "配价：「否则」要接分句，不能直接带名词「画画」。"}], "explanations": {"比如说": "正确：「比如说」引出画画这个例子，符合语境。", "但是": "语义：「但是」表示转折，与「学新东西」之后举例画画的语境不符。", "因为": "语义：「因为」表示原因，「画画」不是学新东西的原因。", "否则": "配价：「否则」要接分句，不能直接带名词「画画」。"}, "sentence_index": 0, "correct_answer": "比如说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天熬夜了，比如说今天很累。", "explanation": "这里应该用〈所以〉。「比如说」引出例子，不表示因果关系。"}, {"text": "这个房间很大，比如说很安静。", "explanation": "这里应该用〈而且〉。「比如说」引出例子，不表示并列补充。"}, {"text": "我们先吃饭，比如说去看电影。", "explanation": "这里应该用〈然后〉。「比如说」引出例子，不表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比如说", "is_correct": true, "explanation": "正确：「比如说」引出那家茶馆这个例子，符合语境。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，与「很多老店」和「那家茶馆」之间的关系不符。"}, {"text": "然而", "is_correct": false, "explanation": "语义：「然而」表示转折，与举例的语境不符。"}, {"text": "而且", "is_correct": false, "explanation": "配价：「而且」要连接分句，不能直接带「那家茶馆」这样的名词。"}], "explanations": {"比如说": "正确：「比如说」引出那家茶馆这个例子，符合语境。", "所以": "语义：「所以」表示因果，与「很多老店」和「那家茶馆」之间的关系不符。", "然而": "语义：「然而」表示转折，与举例的语境不符。", "而且": "配价：「而且」要连接分句，不能直接带「那家茶馆」这样的名词。"}, "sentence_index": 6, "correct_answer": "比如说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字写得很好，比如说画得不太好。", "explanation": "这里应该用〈不过〉。「比如说」引出例子，不表示转折。"}, {"text": "他很有钱，比如说很节俭。", "explanation": "这里应该用〈却〉。「比如说」引出例子，不表示转折。"}, {"text": "我们走了很久，比如说决定休息。", "explanation": "这里应该用〈于是〉。「比如说」引出例子，不表示接着做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想养一些宠物，比如说了猫。", "corrected_sentence": "我想养一些宠物，比如说猫。", "error_description": "「比如说」是连词，后面不能加「了」，应把「比如说了猫」改为「比如说猫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人喜欢运动，比如说了跑步。", "corrected_sentence": "很多人喜欢运动，比如说跑步。", "error_description": "词尾错误：「比如说」是连词，后面不能加「了」，应把「比如说了跑步」改为「比如说跑步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
