INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用图画把很多内容画出来，让人一看就懂。", "primary_collocate": null, "pronunciation": "xìn xī tú", "ipa": "ɕin⁵¹ ɕi⁵⁵ tʰu³⁵", "syllable_count": 3, "sentences": [{"text": "这张信息图把做饭的步骤都画出来了。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一张信息图讲了水的循环。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了这张信息图，我马上就懂了。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信息图上画了很多小图标。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信息图告诉我们一天该喝多少水。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看色彩鲜艳的信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找到一张讲地铁路线的信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信息图用不同颜色分开每个季节。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一张信息图，介绍自己的家人。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一张信息图，说明植物怎么长大。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张信息图", "label": "量词"}, {"form": "一幅信息图", "label": "量词"}, {"form": "信息圖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用图画画出很多内容、一看就懂的讲解图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照片", "is_correct": false, "explanation": "搭配：照片是拍出来的，不能说“画出来”，与句中“画”的动作不搭。"}, {"text": "信息图", "is_correct": true, "explanation": "正确。信息图是用图画把内容画出来的设计，可以把做饭的步骤画出来。"}, {"text": "购物单", "is_correct": false, "explanation": "语义：购物单记录要买的东西，不能把做饭的步骤画出来。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片用来写姓名和联系方式，不会画出做饭的步骤。"}], "explanations": {"照片": "搭配：照片是拍出来的，不能说“画出来”，与句中“画”的动作不搭。", "信息图": "正确。信息图是用图画把内容画出来的设计，可以把做饭的步骤画出来。", "购物单": "语义：购物单记录要买的东西，不能把做饭的步骤画出来。", "名片": "语义：名片用来写姓名和联系方式，不会画出做饭的步骤。"}, "sentence_index": 0, "correct_answer": "信息图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这张信息图洗出来，寄给了远方的朋友。", "explanation": "这里应该用〈照片〉。信息图是设计出来的图，不是拍出来的，不能“洗出来”，“洗”只用于照片。"}, {"text": "妈妈送了我一只信息图做生日礼物。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈只〉，〈只〉多用于动物或成对的东西。"}, {"text": "他拿着一把信息图走进了教室。", "explanation": "量词用错：信息图应该用〈张〉，不能用〈把〉，〈把〉用于有柄或能握住的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车票", "is_correct": false, "explanation": "语义：车票只是乘车的凭证，不能用来讲解地铁路线。"}, {"text": "信息图", "is_correct": true, "explanation": "正确。信息图可以用图形讲解地铁路线，与“讲”搭配。"}, {"text": "菜单", "is_correct": false, "explanation": "搭配：“讲……路线”的对象应是能说明路线的东西，“菜单”上列的是菜，不能说“讲地铁路线的菜单”。"}, {"text": "书签", "is_correct": false, "explanation": "语义：书签用来标记读到的位置，不能用来讲解地铁路线。"}], "explanations": {"车票": "语义：车票只是乘车的凭证，不能用来讲解地铁路线。", "信息图": "正确。信息图可以用图形讲解地铁路线，与“讲”搭配。", "菜单": "搭配：“讲……路线”的对象应是能说明路线的东西，“菜单”上列的是菜，不能说“讲地铁路线的菜单”。", "书签": "语义：书签用来标记读到的位置，不能用来讲解地铁路线。"}, "sentence_index": 6, "correct_answer": "信息图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把信息图放进微波炉热了一下，然后就吃了。", "explanation": "这里应该用〈饭菜〉。信息图是印出来或画出来给人看的图，不能放进微波炉加热，也不能吃，“热”“吃”只用于食物。"}, {"text": "他从口袋里掏出一颗信息图给我看。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈颗〉，〈颗〉用于粒状或圆形的小东西。"}, {"text": "他在广场中央立了一座信息图。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈座〉，〈座〉用于山、桥、建筑等大型的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天做了三只信息图，给同学们讲解天气变化。", "corrected_sentence": "我昨天做了三张信息图，给同学们讲解天气变化。", "error_description": "量词错误：信息图是平面的图，应该用量词“张”（或“幅”），不能用“只”（“只”多用于动物）。应说“三张信息图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些数据做成了一信息图。", "corrected_sentence": "他把这些数据做成了信息图。", "error_description": "错误在“一信息图”。数词“一”后面不能直接接名词，要加量词，应说“做成了一张信息图”；若不用数量，则说“做成了信息图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
