INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以图形、图表直观呈现信息的设计形式。", "primary_collocate": null, "pronunciation": "xìn xī tú", "ipa": "ɕin⁵¹ ɕi⁵⁵ tʰu³⁵", "syllable_count": 3, "sentences": [{"text": "这家公司请设计师做了一张信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的信息图要用图表，不要写太多字。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学设计，最喜欢做信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里的信息图让数字更清楚。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信息图的颜色和图表都很好看。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求把销售数据做成信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做信息图要先选对图表的样式。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站有很多免费的信息图模板。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师用线条和图形做出一张信息图。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信息图用柱状图比较了三年的销量。", "target_word": "信息图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张信息图", "label": "量词"}, {"form": "一幅信息图", "label": "量词"}, {"form": "信息圖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用图形图表直观呈现信息的设计形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份证", "is_correct": false, "explanation": "语义：身份证由政府机关签发，不可能由设计师做出来。"}, {"text": "信息图", "is_correct": true, "explanation": "正确。信息图是设计出来的作品，公司可以请设计师做。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医院记录病情的文件，不是设计师做的东西。"}, {"text": "请假条", "is_correct": false, "explanation": "搭配：“请假条”是个人写给别人看的，与“请设计师做”不搭。"}], "explanations": {"身份证": "语义：身份证由政府机关签发，不可能由设计师做出来。", "信息图": "正确。信息图是设计出来的作品，公司可以请设计师做。", "病历": "语义：病历是医院记录病情的文件，不是设计师做的东西。", "请假条": "搭配：“请假条”是个人写给别人看的，与“请设计师做”不搭。"}, "sentence_index": 0, "correct_answer": "信息图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这张信息图冲洗好，放进了相册。", "explanation": "这里应该用〈照片〉。信息图是设计出来的图表，不是拍的，不需要冲洗，冲洗要用于照片。"}, {"text": "他在纸上画了一颗信息图。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈颗〉，〈颗〉用于粒状或圆形的小东西。"}, {"text": "她拿着一把信息图去开会。", "explanation": "量词用错：信息图应该用〈张〉，不能用〈把〉，〈把〉用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不用图表的样式来选择，“做蛋糕”与句意不符。"}, {"text": "信息图", "is_correct": true, "explanation": "正确。做信息图时要选图表的样式，与句意一致。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，做面条不需要选图表的样式。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：名片上一般不用图表，“图表的样式”与“名片”不搭。"}], "explanations": {"蛋糕": "语义：蛋糕是食物，不用图表的样式来选择，“做蛋糕”与句意不符。", "信息图": "正确。做信息图时要选图表的样式，与句意一致。", "面条": "语义：面条是食物，做面条不需要选图表的样式。", "名片": "搭配：名片上一般不用图表，“图表的样式”与“名片”不搭。"}, "sentence_index": 6, "correct_answer": "信息图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这首歌的信息图背了下来，还唱给朋友听。", "explanation": "这里应该用〈歌词〉。信息图是图表，不能背诵，也不能唱，“背”“唱”应该用于歌词。"}, {"text": "他在墙上挂了一座信息图。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈座〉，〈座〉用于山、桥、建筑等大型的东西。"}, {"text": "妈妈给我买了一只信息图。", "explanation": "量词用错：信息图应该用〈张〉或〈幅〉，不能用〈只〉，〈只〉多用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司请设计师做了三只信息图，用来介绍新产品。", "corrected_sentence": "这家公司请设计师做了三张信息图，用来介绍新产品。", "error_description": "量词错误：信息图是平面的设计作品，应该用量词“张”（或“幅”），不能用“只”。应说“三张信息图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在展览上见过这张的信息图。", "corrected_sentence": "我在展览上见过这张信息图。", "error_description": "错误在“这张的信息图”。“这张”是指示词加量词，后面直接接名词，中间不能加“的”，应说“这张信息图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
