INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "贴在墙上，告诉大家有什么好看的画报。", "primary_collocate": null, "pronunciation": "hǎi bào", "ipa": "xaɪ²¹⁴ paʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "宿舍的墙上贴满了海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报告诉我们剧场最近演什么。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很喜欢看墙上的海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走过地铁站，看了一眼新海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海报上的画很漂亮，我想拍下来。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店门口的海报上写着今晚有演出。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报是谁画的？", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把喜欢的歌手海报贴在床边。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的海报上有一只很大的老虎。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆外面的海报介绍了这个月的好书。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张海报", "label": "量词"}, {"form": "一幅海报", "label": "量词"}, {"form": "海报设计", "label": "复合"}, {"form": "海報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "贴在墙上、告诉大家有什么好看内容的画报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96773, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海报", "is_correct": true, "explanation": "正确。海报 hǎi bào，贴在墙上告诉大家有什么好看的画报。"}, {"text": "海盗", "is_correct": false, "explanation": "声母 d 与 b 不同（dào 与 bào），意思是海盗。"}, {"text": "海道", "is_correct": false, "explanation": "dào 与 bào 只差声母（d 与 b），意思是海上的航道。"}, {"text": "海堡", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）只差声调，意思是海上的堡垒。"}], "explanations": {"海报": "正确。海报 hǎi bào，贴在墙上告诉大家有什么好看的画报。", "海盗": "声母 d 与 b 不同（dào 与 bào），意思是海盗。", "海道": "dào 与 bào 只差声母（d 与 b），意思是海上的航道。", "海堡": "bǎo（第三声）与 bào（第四声）只差声调，意思是海上的堡垒。"}, "sentence_index": null, "correct_answer": "海报"}, "level_3": {"options": [{"text": "垃圾", "is_correct": false, "explanation": "语义：墙上不会被贴满垃圾，“贴满”的对象应是宣传品。"}, {"text": "海报", "is_correct": true, "explanation": "正确。宿舍墙上贴满的是海报，与“贴满了”搭配。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：空调是挂在墙上的电器，不能说“贴满”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，不用来贴满宿舍的墙。"}], "explanations": {"垃圾": "语义：墙上不会被贴满垃圾，“贴满”的对象应是宣传品。", "海报": "正确。宿舍墙上贴满的是海报，与“贴满了”搭配。", "空调": "搭配：空调是挂在墙上的电器，不能说“贴满”。", "课本": "语义：课本是学习用书，不用来贴满宿舍的墙。"}, "sentence_index": 0, "correct_answer": "海报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看了一眼墙上的海报，已经十点了。", "explanation": "这里应该用〈挂钟〉。海报是用来宣传的，不能用来看时间，看时间要用挂钟。"}, {"text": "妹妹在书店买了一只海报。", "explanation": "量词用错：海报应该用〈张〉或〈幅〉，不能用〈只〉，〈只〉多用于动物或成对的东西。"}, {"text": "妹妹拿着一条海报跑出了门。", "explanation": "量词用错：海报应该用〈张〉，不能用〈条〉，〈条〉用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96773, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海报", "is_correct": true, "explanation": "正确。海报 hǎi bào，贴在墙上的画报。"}, {"text": "黑豹", "is_correct": false, "explanation": "hēi 与 hǎi 韵母和声调不同（ei 与 ai），第二个字相同，意思是黑色的豹子。"}, {"text": "好报", "is_correct": false, "explanation": "hǎo 与 hǎi 只差韵母（ao 与 ai），意思是善有善报的报应。"}, {"text": "海岛", "is_correct": false, "explanation": "dǎo 与 bào 声母、声调都不同，听起来相近，意思是海里的岛。"}], "explanations": {"海报": "正确。海报 hǎi bào，贴在墙上的画报。", "黑豹": "hēi 与 hǎi 韵母和声调不同（ei 与 ai），第二个字相同，意思是黑色的豹子。", "好报": "hǎo 与 hǎi 只差韵母（ao 与 ai），意思是善有善报的报应。", "海岛": "dǎo 与 bào 声母、声调都不同，听起来相近，意思是海里的岛。"}, "sentence_index": null, "correct_answer": "海报"}, "level_3": {"options": [{"text": "车票", "is_correct": false, "explanation": "语义：车票是乘车的凭证，不是人画出来的东西。"}, {"text": "海报", "is_correct": true, "explanation": "正确。海报是人设计、画出来的，可以问“是谁画的”。"}, {"text": "护照", "is_correct": false, "explanation": "搭配：护照是政府签发的证件，不说“谁画的”。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是消费记录，不是画出来的东西。"}], "explanations": {"车票": "语义：车票是乘车的凭证，不是人画出来的东西。", "海报": "正确。海报是人设计、画出来的，可以问“是谁画的”。", "护照": "搭配：护照是政府签发的证件，不说“谁画的”。", "账单": "语义：账单是消费记录，不是画出来的东西。"}, "sentence_index": 6, "correct_answer": "海报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上躺在床上读这张海报，已经读到第三章了。", "explanation": "这里应该用〈书〉。海报是贴在墙上的单张宣传画，没有章节，不能“读到第三章”，“章”和“读”用于书。"}, {"text": "他在广场上立了一座海报。", "explanation": "量词用错：海报应该用〈张〉或〈幅〉，不能用〈座〉，〈座〉用于山、桥、建筑等大型的东西。"}, {"text": "我在墙角看到一颗海报。", "explanation": "量词用错：海报应该用〈张〉或〈幅〉，不能用〈颗〉，〈颗〉用于粒状或圆形的小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿舍的墙上贴了三只海报，画得都很漂亮。", "corrected_sentence": "宿舍的墙上贴了三张海报，画得都很漂亮。", "error_description": "量词错误：海报是纸张，应该用量词“张”（或“幅”），不能用“只”。应说“三张海报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在地铁站见过这只海报，很喜欢它的颜色。", "corrected_sentence": "我在地铁站见过这张海报，很喜欢它的颜色。", "error_description": "量词错误：海报是平面的纸张，应该用量词“张”（或“幅”），不能用“只”。应说“见过这张海报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
