INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "张贴的宣传画，常用来宣传电影、活动。", "primary_collocate": null, "pronunciation": "hǎi bào", "ipa": "xaɪ²¹⁴ paʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "电影院门口贴着一张新电影的海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为音乐会做了很多海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在墙上贴了运动会的海报。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报上写着活动的时间和地点。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她设计的海报很吸引人。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要用海报宣传新产品。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的海报告诉大家周末有一场演出。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在教室里画海报，准备迎新活动。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到海报，我才知道明天有电影节。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张电影海报的颜色很特别。", "target_word": "海报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张海报", "label": "量词"}, {"form": "一幅海报", "label": "量词"}, {"form": "海报设计", "label": "复合"}, {"form": "海報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "张贴出来宣传电影、活动的宣传画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e975e5-966d-46d8-94da-f8c9caca528d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海报", "is_correct": true, "explanation": "正确。海报 hǎi bào，张贴出来宣传的画。"}, {"text": "海盗", "is_correct": false, "explanation": "声母 d 与 b 不同（dào 与 bào），意思是海盗。"}, {"text": "海道", "is_correct": false, "explanation": "dào 与 bào 只差声母（d 与 b），意思是海上的航道。"}, {"text": "海堡", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）只差声调，意思是海上的堡垒。"}], "explanations": {"海报": "正确。海报 hǎi bào，张贴出来宣传的画。", "海盗": "声母 d 与 b 不同（dào 与 bào），意思是海盗。", "海道": "dào 与 bào 只差声母（d 与 b），意思是海上的航道。", "海堡": "bǎo（第三声）与 bào（第四声）只差声调，意思是海上的堡垒。"}, "sentence_index": null, "correct_answer": "海报"}, "level_3": {"options": [{"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱讲做菜的方法，不是宣传电影的东西，与“新电影”不符。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：说明书讲产品的用法，不用来宣传电影。"}, {"text": "海报", "is_correct": true, "explanation": "正确。电影院门口贴的宣传画是海报，与“贴着”“新电影”搭配。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“新电影的名片”不成立，名片不是为电影宣传而贴的。"}], "explanations": {"菜谱": "语义：菜谱讲做菜的方法，不是宣传电影的东西，与“新电影”不符。", "说明书": "语义：说明书讲产品的用法，不用来宣传电影。", "海报": "正确。电影院门口贴的宣传画是海报，与“贴着”“新电影”搭配。", "名片": "搭配：“新电影的名片”不成立，名片不是为电影宣传而贴的。"}, "sentence_index": 0, "correct_answer": "海报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们拿着海报找路，很快就到了。", "explanation": "这里应该用〈地图〉。海报是张贴宣传的画，不能用来找路，找路要用地图。"}, {"text": "妈妈在超市买了一只海报送给我。", "explanation": "量词用错：海报应该用〈张〉或〈幅〉，不能用〈只〉，〈只〉多用于动物或成对的东西。"}, {"text": "他拿着一条海报走进了教室。", "explanation": "量词用错：海报应该用〈张〉，不能用〈条〉，〈条〉用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96774, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海报", "is_correct": true, "explanation": "正确。海报 hǎi bào，张贴出来宣传的画。"}, {"text": "黑豹", "is_correct": false, "explanation": "hēi 与 hǎi 韵母和声调不同（ei 与 ai），第二个字相同，意思是黑色的豹子。"}, {"text": "好报", "is_correct": false, "explanation": "hǎo 与 hǎi 只差韵母（ao 与 ai），意思是善有善报的报应。"}, {"text": "海岛", "is_correct": false, "explanation": "dǎo 与 bào 声母、声调都不同，听起来相近，意思是海里的岛。"}], "explanations": {"海报": "正确。海报 hǎi bào，张贴出来宣传的画。", "黑豹": "hēi 与 hǎi 韵母和声调不同（ei 与 ai），第二个字相同，意思是黑色的豹子。", "好报": "hǎo 与 hǎi 只差韵母（ao 与 ai），意思是善有善报的报应。", "海岛": "dǎo 与 bào 声母、声调都不同，听起来相近，意思是海里的岛。"}, "sentence_index": null, "correct_answer": "海报"}, "level_3": {"options": [{"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出菜品，不用来告诉大家演出的信息。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“街上的课本”不合理，课本不会贴在街上宣传演出。"}, {"text": "海报", "is_correct": true, "explanation": "正确。海报张贴在街上，可以告诉大家周末有演出。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图标示位置，不能用来报道演出的时间。"}], "explanations": {"菜单": "语义：菜单列出菜品，不用来告诉大家演出的信息。", "课本": "搭配：“街上的课本”不合理，课本不会贴在街上宣传演出。", "海报": "正确。海报张贴在街上，可以告诉大家周末有演出。", "地图": "语义：地图标示位置，不能用来报道演出的时间。"}, "sentence_index": 6, "correct_answer": "海报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天翻一下墙上的海报，看看今天是几号。", "explanation": "这里应该用〈日历〉。海报是用来宣传的，不能用来查日期，查日期要用日历。"}, {"text": "他从口袋里掏出一颗海报给我看。", "explanation": "量词用错：海报应该用〈张〉或〈幅〉，不能用〈颗〉，〈颗〉用于粒状或圆形的小东西。"}, {"text": "他在墙上贴了一段海报。", "explanation": "量词用错：海报应该用〈张〉，不能用〈段〉，〈段〉用于文章、视频等有段落的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX