INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了两只海报，贴在房间的墙上。", "corrected_sentence": "我昨天买了两张海报，贴在房间的墙上。", "error_description": "量词错误：海报是平面的纸张，应该用量词“张”（或“幅”），不能用“只”。应说“两张海报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把照片做成了一只海报，挂在墙上。", "corrected_sentence": "他把照片做成了一张海报，挂在墙上。", "error_description": "量词错误：海报是平面的纸张，应该用量词“张”（或“幅”），不能用“只”。应说“做成了一张海报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '298a12de-51a0-4853-ba2a-cf3691009441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
