INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96775, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "最先说出来，叫大家一起去做。", "primary_collocate": null, "pronunciation": "chàng dǎo", "ipa": "ʈʂʰɑŋ˥˩ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校倡导同学们每天锻炼身体。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师倡导大家多读书，少玩手机。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司倡导员工坐公共汽车上班。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区倡导大家把旧衣服送给需要的人。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府倡导市民少开车，多走路。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最早倡导大家在家里分类扔垃圾。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们倡导节约用水，请大家一起做。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校倡导的读书活动，得到了很多人支持。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生倡导大家每天早睡早起。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倡导全班同学一起打扫公园。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡导了", "label": "体标"}, {"form": "倡导者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "向众人提出号召，请大家一起照着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倡导", "is_correct": true, "explanation": "倡导即带头提出、号召大家去做，与“学校……同学们每天锻炼身体”的语义一致。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与鼓励锻炼的语境相反，“学校嘲笑同学们锻炼身体”句意不通。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：学校不会“逃避”让同学锻炼，这一搭配讲不通。"}, {"text": "反驳", "is_correct": false, "explanation": "配价：“反驳”的对象应是言论或说法，不能带“同学们每天锻炼身体”作宾语。"}], "explanations": {"倡导": "倡导即带头提出、号召大家去做，与“学校……同学们每天锻炼身体”的语义一致。", "嘲笑": "语义：“嘲笑”与鼓励锻炼的语境相反，“学校嘲笑同学们锻炼身体”句意不通。", "逃避": "语义：学校不会“逃避”让同学锻炼，这一搭配讲不通。", "反驳": "配价：“反驳”的对象应是言论或说法，不能带“同学们每天锻炼身体”作宾语。"}, "sentence_index": 0, "correct_answer": "倡导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市政府倡导了今年的疫情数据。", "explanation": "这里应该用〈通报〉。倡导是提出主张、号召大家去做，发布数据要用“通报”。"}, {"text": "医生倡导我每天多喝水。", "explanation": "这里应该用〈建议〉。倡导面向大家提出主张，只针对个人的意见要用“建议”。"}, {"text": "校长倡导了放假的消息。", "explanation": "这里应该用〈宣布〉。倡导的对象是主张或做法，告知消息要用“宣布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡导", "is_correct": true, "explanation": "倡导即号召，与后句“请大家一起做”的态度一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与后句“请大家一起做”的态度相反，句意矛盾。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评节约用水与后句的号召相矛盾，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与后句“请大家一起做”的号召相矛盾，句意不通。"}], "explanations": {"倡导": "倡导即号召，与后句“请大家一起做”的态度一致。", "反对": "语义：“反对”与后句“请大家一起做”的态度相反，句意矛盾。", "批评": "语义：批评节约用水与后句的号召相矛盾，句意不通。", "拒绝": "语义：“拒绝”与后句“请大家一起做”的号召相矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "倡导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师倡导了我们的作业。", "explanation": "这里应该用〈检查〉。倡导是提出主张、号召大家去做，检查作业要用“检查”。"}, {"text": "将军倡导士兵立刻出发。", "explanation": "这里应该用〈命令〉。倡导不带强制性，军中的行动指令要用“命令”。"}, {"text": "老师倡导了他的努力。", "explanation": "这里应该用〈表扬〉。倡导的对象是主张或做法，对已做到的努力表示赞许要用“表扬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长倡导得大家节约纸张。", "corrected_sentence": "班长倡导大家节约纸张。", "error_description": "“倡导”后直接带宾语“大家”，不用结构助词“得”。“倡导得大家”错误。正确：班长倡导大家节约纸张。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把倡导全班同学一起保护环境。", "corrected_sentence": "他倡导全班同学一起保护环境。", "error_description": "“把”后不能直接接动词“倡导”，“把”字句不适用于此句。“把倡导全班同学”错误。正确：他倡导全班同学一起保护环境。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
