INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带头提出并提倡。", "primary_collocate": null, "pronunciation": "chàng dǎo", "ipa": "ʈʂʰɑŋ˥˩ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位校长带头倡导新的学习方法。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是最早倡导环保生活的人。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前，她就开始倡导健康的饮食习惯。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长倡导建设一座绿色的城市。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法是李老师最先倡导的。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长期倡导男女平等。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家倡导用新办法保护河水。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理倡导开放的工作方式。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她倡导简单的生活方式。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们倡导的新生活方式。", "target_word": "倡导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡导了", "label": "体标"}, {"form": "倡导者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "带头提出某种主张或做法并加以提倡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倡导", "is_correct": true, "explanation": "倡导即带头提出主张，与“带头”的语境相合。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”与“带头”推行新方法的语境相反，句意矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：校长不会“带头忘记”新的学习方法，句意矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与“带头”推行新方法的语境相反，句意矛盾。"}], "explanations": {"倡导": "倡导即带头提出主张，与“带头”的语境相合。", "浪费": "语义：“浪费”与“带头”推行新方法的语境相反，句意矛盾。", "忘记": "语义：校长不会“带头忘记”新的学习方法，句意矛盾。", "嘲笑": "语义：“嘲笑”与“带头”推行新方法的语境相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "倡导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校倡导了一场比赛。", "explanation": "这里应该用〈举办〉。倡导指提出主张，组织比赛或活动要用“举办”。"}, {"text": "医生倡导我戒烟。", "explanation": "这里应该用〈建议〉。倡导面向大家提出主张，对个人的意见要用“建议”。"}, {"text": "他倡导了这个邀请。", "explanation": "这里应该用〈拒绝〉。倡导的对象是主张或做法，邀请是别人发来的，不能倡导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡导", "is_correct": true, "explanation": "倡导即提出并提倡，与句中“用新办法保护河水”的语境相合。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“用新办法保护河水”作宾语。"}, {"text": "美丽", "is_correct": false, "explanation": "词性：“美丽”是形容词，不能带宾语，句子不通。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”不能带“用新办法保护河水”这样的宾语，句子不通。"}], "explanations": {"倡导": "倡导即提出并提倡，与句中“用新办法保护河水”的语境相合。", "散步": "配价：“散步”是不及物动词，不能带“用新办法保护河水”作宾语。", "美丽": "词性：“美丽”是形容词，不能带宾语，句子不通。", "毕业": "配价：“毕业”不能带“用新办法保护河水”这样的宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "倡导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导演倡导了一部纪录片。", "explanation": "这里应该用〈拍摄〉。倡导是提出主张，拍摄作品要用“拍摄”。"}, {"text": "市政府倡导了一座公园。", "explanation": "这里应该用〈修建〉。倡导的对象是主张或做法，建造公园要用“修建”。"}, {"text": "他倡导了一本书。", "explanation": "这里应该用〈借〉。倡导的对象是主张或做法，借阅书籍要用“借”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教育局把倡导开设体育课。", "corrected_sentence": "教育局倡导开设体育课。", "error_description": "“把”后面要先接名词宾语，再接动词，不能直接接动词“倡导”；这句话不需要“把”。“把倡导开设体育课”错误。正确：教育局倡导开设体育课。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们倡导得一种健康习惯。", "corrected_sentence": "这是我们倡导的一种健康习惯。", "error_description": "修饰语后应用结构助词“的”，不是补语“得”。“倡导得”错误。正确：这是我们倡导的一种健康习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
