INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在地下挖煤的地方。", "primary_collocate": null, "pronunciation": "méi kuàng", "ipa": "mei˧˥ kuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷年轻时在煤矿工作。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座煤矿在山的下面。", "target_word": "煤矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "煤矿里面很黑，工人要戴灯。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家乡有一座很大的煤矿。", "target_word": "煤矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天坐车去煤矿上班。", "target_word": "煤矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "煤矿离我们的村子很远。", "target_word": "煤矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座老煤矿现在已经关了。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年那个煤矿出过事，现在很安全。", "target_word": "煤矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤矿里的工人们在地下挖煤。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把全家都带到了煤矿附近的小城。", "target_word": "煤矿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座煤矿", "label": "量词"}, {"form": "一个煤矿", "label": "量词"}, {"form": "煤矿工人", "label": "复合词"}, {"form": "煤礦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地下挖煤的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是工人工作的场所，“在月亮工作”说不通。"}, {"text": "煤矿", "is_correct": true, "explanation": "煤矿：在地下挖煤的地方，正是爷爷年轻时工作的场所。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是可以工作的地方。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“在…工作”要求地点名词，“星期”是时间词，不能作工作场所。"}], "explanations": {"月亮": "语义：月亮不是工人工作的场所，“在月亮工作”说不通。", "煤矿": "煤矿：在地下挖煤的地方，正是爷爷年轻时工作的场所。", "钢琴": "语义：钢琴是乐器，不是可以工作的地方。", "星期": "搭配：“在…工作”要求地点名词，“星期”是时间词，不能作工作场所。"}, "sentence_index": 0, "correct_answer": "煤矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家冬天烧煤矿取暖。", "explanation": "这里应该用〈煤炭〉。煤矿是开采煤炭的场所，烧的是煤炭这种燃料，不能说烧煤矿。"}, {"text": "这些煤矿装上了货车。", "explanation": "这里应该用〈煤炭〉。装车运送的是煤炭这类货物，煤矿是开采煤炭的场所，不能被装上货车。"}, {"text": "煤矿每天下井挖煤。", "explanation": "这里应该用〈矿工〉。煤矿是场所，不会下井挖煤；做这件事的是矿工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山", "is_correct": false, "explanation": "语义：山是自然地貌，不能“关”，“这座老山现在已经关了”说不通。"}, {"text": "煤矿", "is_correct": true, "explanation": "煤矿：开采煤炭的场所，已经停止开采、关闭，与“现在已经关了”相符。"}, {"text": "纪念碑", "is_correct": false, "explanation": "搭配：“关”一般搭配门、店、厂、矿等，不能说“关纪念碑”。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是艺术品，不是可以关闭的场所。"}], "explanations": {"山": "语义：山是自然地貌，不能“关”，“这座老山现在已经关了”说不通。", "煤矿": "煤矿：开采煤炭的场所，已经停止开采、关闭，与“现在已经关了”相符。", "纪念碑": "搭配：“关”一般搭配门、店、厂、矿等，不能说“关纪念碑”。", "雕像": "语义：雕像是艺术品，不是可以关闭的场所。"}, "sentence_index": 6, "correct_answer": "煤矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们沿着煤矿下去挖煤。", "explanation": "这里应该用〈矿井〉。矿井是通到地下的竖井，“沿着…下去”走的是井道；煤矿指整个场所，不能这样说。"}, {"text": "煤矿可以用来照明。", "explanation": "这里应该用〈煤油〉。煤油是可以燃烧照明的液体，煤矿是开采煤炭的场所，不能用来照明。"}, {"text": "他的爸爸是煤矿，每天下井挖煤。", "explanation": "这里应该用〈煤矿工人〉。煤矿是场所，指人时要说“煤矿工人”，“他的爸爸是煤矿”说法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只煤矿已经开采了二十年。", "corrected_sentence": "那座煤矿已经开采了二十年。", "error_description": "量词错误：“只”用于动物等，煤矿这类大型场所应说“座”，应为“那座煤矿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煤矿工人每天很早就下海。", "corrected_sentence": "煤矿工人每天很早就下井。", "error_description": "搭配错误：煤矿工人进入矿下工作应说“下井”；“下海”指出海或弃职经商，与煤矿无关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
