INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开采煤炭的场所。", "primary_collocate": null, "pronunciation": "méi kuàng", "ipa": "mei˧˥ kuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个煤矿每年开采很多煤炭。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤矿的空气不好，要戴口罩。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府关了几个小煤矿。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家大煤矿当工程师。", "target_word": "煤矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那座煤矿有一百多年的历史。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里新开了一个煤矿，村民都很高兴。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤矿安全很重要，工人都要学习。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐火车去参观了一个煤矿。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里以前是煤矿，现在变成了公园。", "target_word": "煤矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤矿旁边有一条长长的铁路。", "target_word": "煤矿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座煤矿", "label": "量词"}, {"form": "一个煤矿", "label": "量词"}, {"form": "煤矿工人", "label": "复合词"}, {"form": "煤礦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开采煤炭的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农场", "is_correct": false, "explanation": "语义：农场种植作物，不开采煤炭，“这个农场每年开采很多煤炭”说不通。"}, {"text": "煤矿", "is_correct": true, "explanation": "煤矿：开采煤炭的场所，与“每年开采很多煤炭”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不开采煤炭。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“开采煤炭”的主体应是采矿场所，不能搭配“银行”。"}], "explanations": {"农场": "语义：农场种植作物，不开采煤炭，“这个农场每年开采很多煤炭”说不通。", "煤矿": "煤矿：开采煤炭的场所，与“每年开采很多煤炭”相符。", "学校": "语义：学校是教育机构，不开采煤炭。", "银行": "搭配：“开采煤炭”的主体应是采矿场所，不能搭配“银行”。"}, "sentence_index": 0, "correct_answer": "煤矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂用煤矿发电。", "explanation": "这里应该用〈煤炭〉。发电烧的是煤炭这种燃料，煤矿是开采煤炭的场所，不能用来发电。"}, {"text": "煤矿很重，需要两个人才能抬动。", "explanation": "这里应该用〈煤块〉。能用人力抬动的是煤块，煤矿是开采场所，不是可以搬运的物体。"}, {"text": "他在井下当煤矿。", "explanation": "这里应该用〈矿工〉。煤矿是场所，不能当职业；在井下工作的是矿工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花不是工作场所，“鲜花安全很重要，工人都要学习”说不通。"}, {"text": "煤矿", "is_correct": true, "explanation": "煤矿：开采煤炭的场所，需要注意安全，工人要学习，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然现象，不谈安全问题。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“安全”不能修饰“数学”这样的学科。"}], "explanations": {"鲜花": "语义：鲜花不是工作场所，“鲜花安全很重要，工人都要学习”说不通。", "煤矿": "煤矿：开采煤炭的场所，需要注意安全，工人要学习，与语境相符。", "天空": "语义：天空是自然现象，不谈安全问题。", "数学": "搭配：“安全”不能修饰“数学”这样的学科。"}, "sentence_index": 6, "correct_answer": "煤矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条铁路运输很多煤矿。", "explanation": "这里应该用〈煤炭〉。铁路运输的是煤炭这类货物，煤矿是开采煤炭的场所，不能被运输。"}, {"text": "煤矿可以用来点灯。", "explanation": "这里应该用〈煤油〉。煤油是可以点灯照明的燃料，煤矿是开采煤炭的场所，不能用来点灯。"}, {"text": "这里出产很多煤矿。", "explanation": "这里应该用〈矿产〉。煤矿是开采矿产的场所，不是出产的东西；这里出产的是矿产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两煤矿今年都增产了。", "corrected_sentence": "那两家煤矿今年都增产了。", "error_description": "量词缺失：“两”后面要加量词，煤矿说“两家”，应为“那两家煤矿”，不能说“那两煤矿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年参加了一个煤矿。", "corrected_sentence": "我们去年参观了一个煤矿。", "error_description": "动词错误：“煤矿”是场所，应说“参观”，不能说“参加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
