INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96779, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一篇文章从头到尾全部的字。", "primary_collocate": null, "pronunciation": "quán wén", "ipa": "tɕʰɥɛn˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "请把这篇文章的全文读一遍。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上登了他的演讲全文。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只看了摘要，没有看全文。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文一共有五百个字。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们背下这首诗的全文。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在网上下载这本书的全文。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的全文很短。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把全文抄在本子上。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里只有开头，没有全文。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文读完，我一个错字也没发现。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一篇文章从头到尾完整的文字，不是摘要或节选", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全文", "is_correct": true, "explanation": "全文指一篇文章从头到尾的全部文字，可以“读一遍”，符合句意。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者指写文章的人，不是文字，不能“读一遍”。"}, {"text": "标点", "is_correct": false, "explanation": "搭配：“读”一般不以标点为宾语，“读标点”不这样说，与“这篇文章的”也不搭。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：字数是数量，不是可以“读”的内容，“读一遍字数”不成立。"}], "explanations": {"全文": "全文指一篇文章从头到尾的全部文字，可以“读一遍”，符合句意。", "作者": "语义：作者指写文章的人，不是文字，不能“读一遍”。", "标点": "搭配：“读”一般不以标点为宾语，“读标点”不这样说，与“这篇文章的”也不搭。", "字数": "搭配：字数是数量，不是可以“读”的内容，“读一遍字数”不成立。"}, "sentence_index": 0, "correct_answer": "全文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的全文窗户都换成了新的。", "explanation": "这里应该用〈全部〉。全文只指一篇文章的完整文字，不能修饰“窗户”，表示“所有窗户”要说〈全部〉。"}, {"text": "他把自己的全文财产都捐给了学校。", "explanation": "这里应该用〈全部〉。全文只指一篇文章的完整文字，不能修饰“财产”，表示“全部财产”要说〈全部〉。"}, {"text": "周末我们全文去公园玩。", "explanation": "这里应该用〈全家〉。全家指一家所有的人；全文只指文章的完整文字，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全文", "is_correct": true, "explanation": "全文指信的完整文字，句中说它很短，符合句意。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票是贴在信封上的票证，不是可以用“很短”形容的文字内容。"}, {"text": "邮戳", "is_correct": false, "explanation": "语义：邮戳是寄信时盖上的印记，不能说“很短”。"}, {"text": "笔迹", "is_correct": false, "explanation": "搭配：笔迹可以说“工整”或“潦草”，不用“很短”来形容。"}], "explanations": {"全文": "全文指信的完整文字，句中说它很短，符合句意。", "邮票": "语义：邮票是贴在信封上的票证，不是可以用“很短”形容的文字内容。", "邮戳": "语义：邮戳是寄信时盖上的印记，不能说“很短”。", "笔迹": "搭配：笔迹可以说“工整”或“潦草”，不用“很短”来形容。"}, "sentence_index": 6, "correct_answer": "全文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让全文同学都站起来回答问题。", "explanation": "这里应该用〈全班〉。全班指整个班级，可以修饰“同学”；全文只指文章的完整文字，不能修饰人。"}, {"text": "他跑完步，全文都湿透了。", "explanation": "这里应该用〈全身〉。湿透说的是身体，全文指文章的完整文字，不能作为身体的主语。"}, {"text": "比赛结束时，全文的观众都站了起来。", "explanation": "这里应该用〈全场〉。全场指整个场地里的人；全文只指文章的完整文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没有看了全文。", "corrected_sentence": "我没有看过全文。", "error_description": "体标错误：否定过去的经历用“没有……过”，“没有”不能和“了”一起用。应把“了”改成“过”：“我没有看过全文。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天读过这份论文得全文。", "corrected_sentence": "我昨天读过这份论文的全文。", "error_description": "助词错误：修饰名词“全文”要用结构助词“的”，“得”是补语标志，不能用在这里。正确说法是“这份论文的全文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
