INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一篇文章的全部内容。", "primary_collocate": null, "pronunciation": "quán wén", "ipa": "tɕʰɥɛn˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这篇文章全文都在讲环保。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文的意思很容易懂。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用一句话说出全文的意思。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文分成三个部分。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我全文写了什么。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文的重点是要多运动。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完全文，我明白了他的想法。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇报道全文都是好消息。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全文没有一句说到价格。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把全文的意思告诉了朋友。", "target_word": "全文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一篇文章整体的内容、意思和重点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全文", "is_correct": true, "explanation": "全文指文章的全部内容，句中说“都在讲环保”，符合句意。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是数量，不表示文章的内容，不能“讲环保”。"}, {"text": "页数", "is_correct": false, "explanation": "搭配：“讲”的对象是内容，不能是页数；“页数都在讲环保”不成立。"}, {"text": "笔迹", "is_correct": false, "explanation": "语义：笔迹是书写的样子，不是文章内容，不能“讲”环保。"}], "explanations": {"全文": "全文指文章的全部内容，句中说“都在讲环保”，符合句意。", "字数": "语义：字数是数量，不表示文章的内容，不能“讲环保”。", "页数": "搭配：“讲”的对象是内容，不能是页数；“页数都在讲环保”不成立。", "笔迹": "语义：笔迹是书写的样子，不是文章内容，不能“讲”环保。"}, "sentence_index": 0, "correct_answer": "全文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要全文地考虑这个问题。", "explanation": "这里应该用〈全面〉。全面形容范围广，表示考虑得周到；全文指一篇文章的全部内容，不能修饰“考虑”。"}, {"text": "这项政策要在全文推广。", "explanation": "这里应该用〈全国〉。全国指整个国家，可以表示推广的范围；全文指一篇文章的全部内容，不能表示地点范围。"}, {"text": "会议开始后，全文都很安静。", "explanation": "这里应该用〈全场〉。全场指整个场地的人；全文指一篇文章的全部内容，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全文", "is_correct": true, "explanation": "全文指文章的内容和意思，句中“看完”之后“明白了他的想法”，符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作，不是可以“看完”的内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是文字，不能“看完”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“看完”的对象是文字或内容，“看完数量”不这样说，也无法“明白想法”。"}], "explanations": {"全文": "全文指文章的内容和意思，句中“看完”之后“明白了他的想法”，符合句意。", "脚步": "语义：脚步是走路的动作，不是可以“看完”的内容。", "天气": "语义：天气不是文字，不能“看完”。", "数量": "搭配：“看完”的对象是文字或内容，“看完数量”不这样说，也无法“明白想法”。"}, "sentence_index": 6, "correct_answer": "全文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到这个消息后，全文都在发抖。", "explanation": "这里应该用〈全身〉。发抖是身体的动作，全文指文章，不能作主语。"}, {"text": "他全文都在为这件事努力。", "explanation": "这里应该用〈全年〉。全年指一整年的时间；全文指一篇文章的全部内容，不能表示时间。"}, {"text": "老师说全文同学都通过了考试。", "explanation": "这里应该用〈全班〉。全班指整个班级，可以修饰“同学”；全文指一篇文章的全部内容，不能修饰人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告全文得意思很清楚。", "corrected_sentence": "这份报告全文的意思很清楚。", "error_description": "助词错误：“全文”修饰“意思”时要用结构助词“的”，不能用“得”。正确说法是“全文的意思”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没看完了全文。", "corrected_sentence": "我昨天没看完全文。", "error_description": "体标错误：用“没”否定时，动词后面不能再加“了”。应去掉“了”：“我昨天没看完全文。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
