INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "设立的奖励的名目或类别。", "primary_collocate": null, "pronunciation": "jiǎng xiàng", "ipa": "tɕjaŋ˨˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "电影节今年新设了一个奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖项每年评一次。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司设立了最佳员工奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家们都很看重这个文学奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有十几个奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐节取消了一个旧奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖项以一位老科学家的名字命名。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说今年的奖项比去年多。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想增加一个新奖项。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖项是为年轻人设的。", "target_word": "奖项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "獎項", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；机构设立的奖励名目或类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奖项", "is_correct": true, "explanation": "正确答案。奖项，jiǎng xiàng，指设立的奖励名目或类别。"}, {"text": "姜香", "is_correct": false, "explanation": "jiāng xiāng（第一声、第一声）与 jiǎng xiàng 两个音节声调都不同，意思是姜的香味。"}, {"text": "酱香", "is_correct": false, "explanation": "jiàng xiāng（第四声、第一声）与 jiǎng xiàng 两个音节的声调都不同，意思是酱的香气。"}, {"text": "将相", "is_correct": false, "explanation": "jiāng xiàng（第一声）与 jiǎng xiàng 第一音节声调不同，意思是将领和宰相。"}], "explanations": {"奖项": "正确答案。奖项，jiǎng xiàng，指设立的奖励名目或类别。", "姜香": "jiāng xiāng（第一声、第一声）与 jiǎng xiàng 两个音节声调都不同，意思是姜的香味。", "酱香": "jiàng xiāng（第四声、第一声）与 jiǎng xiàng 两个音节的声调都不同，意思是酱的香气。", "将相": "jiāng xiàng（第一声）与 jiǎng xiàng 第一音节声调不同，意思是将领和宰相。"}, "sentence_index": null, "correct_answer": "奖项"}, "level_3": {"options": [{"text": "奖项", "is_correct": true, "explanation": "奖项指设立的奖励名目，“电影节今年新设了一个奖项”搭配自然。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：电影节不会“设立”一只老虎，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“设”不与“窗户”搭配，窗户是安装的，不是设立的。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以设立的名目，句子不合逻辑。"}], "explanations": {"奖项": "奖项指设立的奖励名目，“电影节今年新设了一个奖项”搭配自然。", "老虎": "语义：电影节不会“设立”一只老虎，句意不通。", "窗户": "搭配：“设”不与“窗户”搭配，窗户是安装的，不是设立的。", "石头": "语义：石头不是可以设立的名目，句子不合逻辑。"}, "sentence_index": 0, "correct_answer": "奖项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把奖项存进了银行。", "explanation": "这里应该用〈奖学金〉。奖项是奖励的名目，不是钱，不能存进银行。"}, {"text": "他把奖项撕碎了。", "explanation": "这里应该用〈奖状〉。奖项是抽象的类别，撕的应是具体的奖状。"}, {"text": "老师把奖项切成了两半。", "explanation": "这里应该用〈蛋糕〉。奖项是抽象的类别，不能切开，切的应是蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
